    CALL PUSHREAL8ARRAY(vsrez, 4)
    CALL PUSHREAL8(cf1)
    CALL PUSHREAL8(d1)
    CALL PUSHREAL8(di2_ms)
    CALL PUSHREAL8(cq2_u2)
    CALL PUSHREAL8(xt_u2)
    CALL PUSHREAL8(de2_u2)
    CALL PUSHREAL8(xt_u1)
    CALL PUSHREAL8(t1)
    CALL PUSHREAL8(hs2_u2)
    CALL PUSHREAL8(rt1_re)
    CALL PUSHREAL8(cf1_ms)
    CALL PUSHREAL8(r1_ms)
    CALL PUSHREAL8(xt_x2)
    CALL PUSHREAL8(xt_x1)
    CALL PUSHREAL8(di1_u1)
    CALL PUSHREAL8(dw1)
    CALL PUSHREAL8(m1_ms)
    CALL PUSHREAL8(xt)
    CALL PUSHREAL8(hc1_ms)
    CALL PUSHREAL8(us1_ms)
    CALL PUSHREAL8(cf2_ms)
    CALL PUSHREAL8(di2_u2)
    CALL PUSHREAL8(cq1_d1)
    CALL PUSHREAL8(m1)
    CALL PUSHREAL8(de1_d1)
    CALL PUSHREAL8(xt_a1)
    CALL PUSHREAL8(v1_ms)
    CALL PUSHREAL8(hs1_d1)
    CALL PUSHREAL8(hc2_ms)
    CALL PUSHREAL8(us2_ms)
    CALL PUSHREAL8(cq1_t1)
    CALL PUSHREAL8(cf1_u1)
    CALL PUSHREAL8(r1_u1)
    CALL PUSHREAL8(de1_t1)
    CALL PUSHREAL8(hs1_t1)
    CALL PUSHREAL8(cq2_d2)
    CALL PUSHREAL8(xt_d2)
    CALL PUSHREAL8(de2_d2)
    CALL PUSHREAL8(xt_d1)
    CALL PUSHREAL8(m1_u1)
    CALL PUSHREAL8(u1_uei)
    CALL PUSHREAL8(hs2_d2)
    CALL PUSHREAL8(hc1_u1)
    CALL PUSHREAL8(cq2_t2)
    CALL PUSHREAL8(cf2_u2)
    CALL PUSHREAL8(xt_t2)
    CALL PUSHREAL8(us1_u1)
    CALL PUSHREAL8(de2_t2)
    CALL PUSHREAL8(xt_t1)
    CALL PUSHREAL8(cq1_re)
    CALL PUSHREAL8(s1)
    CALL PUSHREAL8(hs2_t2)
    CALL PUSHREAL8ARRAY(vs2, 4*5)
    CALL PUSHREAL8ARRAY(vs1, 4*5)
    CALL PUSHREAL8(hs1_re)
    CALL PUSHREAL8(di1_d1)
    CALL PUSHREAL8(hk1)
    CALL PUSHREAL8(hc2_u2)
    CALL PUSHREAL8(v1_u1)
    CALL PUSHREAL8(us2_u2)
    CALL PUSHREAL8(di1_t1)
    CALL PUSHREAL8(v1)
    CALL PUSHREAL8(cq2_re)
    CALL PUSHREAL8(xt_re)
    CALL PUSHREAL8(u1_ms)
    CALL PUSHREAL8(di2)
    CALL PUSHREAL8(di2_d2)
    CALL PUSHREAL8(di1)
    CALL PUSHREAL8(hs2_re)
    CALL PUSHREAL8(hk1_ms)
    CALL PUSHREAL8(rt1_ms)
    CALL PUSHREAL8(di2_t2)
    setbl = MRCHDU()
! TAPENADE: (AD07) Data-Flow recovery (TBR) on this call to mrchdu needs to save the I-O state
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (daeps SAVEd by trchek2)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to mrchdu needs to save an undeclared side-effect variable: (deps SAVEd by mrchdu)
    IF (abort_on_nan .AND. (.NOT.setbl)) THEN
      hstinvb = 0.0_8
      reyblb = 0.0_8
      tkbl_msb = 0.0_8
      tkblb = 0.0_8
      reybl_reb = 0.0_8
      hstinv_msb = 0.0_8
      rstbl_msb = 0.0_8
      rstblb = 0.0_8
      reybl_msb = 0.0_8
      sst_gob = 0.0_8
      sst_gpb = 0.0_8
      sstb = 0.0_8
      msq_clmrb = 0.0_8
      re_clmrb = 0.0_8
    ELSE
!
      DO is=1,2
        DO ibl=2,nbl(is)
          usav(ibl, is) = uedg(ibl, is)
        END DO
        CALL PUSHINTEGER4(ibl - 1)
      END DO
!
      CALL UESET()
!
      DO is=1,2
        DO ibl=2,nbl(is)
          temp = usav(ibl, is)
          usav(ibl, is) = uedg(ibl, is)
          uedg(ibl, is) = temp
        END DO
        CALL PUSHINTEGER4(ibl - 1)
      END DO
!
      ile1 = ipan(2, 1)
      ile2 = ipan(2, 2)
      ite1 = ipan(iblte(1), 1)
      ite2 = ipan(iblte(2), 2)
!
      jvte1 = isys(iblte(1), 1)
      jvte2 = isys(iblte(2), 2)
!
      dule1 = uedg(2, 1) - usav(2, 1)
      dule2 = uedg(2, 2) - usav(2, 2)
!
!---- set LE and TE Ue sensitivities wrt all m values
      DO js=1,2
        DO jbl=2,nbl(js)
          j = ipan(jbl, js)
          jv = isys(jbl, js)
          ule1_m(jv) = -(vti(2, 1)*vti(jbl, js)*dij(ile1, j))
          ule2_m(jv) = -(vti(2, 2)*vti(jbl, js)*dij(ile2, j))
          ute1_m(jv) = -(vti(iblte(1), 1)*vti(jbl, js)*dij(ite1, j))
          ute2_m(jv) = -(vti(iblte(2), 2)*vti(jbl, js)*dij(ite2, j))
        END DO
        CALL PUSHINTEGER4(jbl - 1)
      END DO
!
      ule1_a = uinv_a(2, 1)
      ule2_a = uinv_a(2, 2)
!
      CALL PUSHINTEGER4(is)
      CALL PUSHCONTROL2B(0)
!
!**** Go over each boundary layer/wake
      DO is=1,2
!
!---- there is no station "1" at similarity, so zero everything out
        DO js=1,2
          DO jbl=2,nbl(js)
            jv = isys(jbl, js)
            CALL PUSHREAL8(u1_m(jv))
            u1_m(jv) = 0.
            CALL PUSHREAL8(d1_m(jv))
            d1_m(jv) = 0.
          END DO
          CALL PUSHINTEGER4(jbl - 1)
        END DO
        u1_a = 0.
        d1_a = 0.
!
        due1 = 0.
        dds1 = 0.
!
!---- similarity station pressure gradient parameter  x/u du/dx
        ibl = 2
        bule = 1.0
!
        amcrit = acrit(is)
!
!---- set forced transition arc length position
        CALL PUSHREAL8ARRAY(w3, 6*iqx)
        CALL PUSHREAL8ARRAY(w1, 6*iqx)
        CALL PUSHREAL8(xiforc)
        CALL XIFSET(is)
!
        CALL PUSHINTEGER4(ibl)
        ad_count = 1
!
!**** Sweep downstream setting up BL equation linearizations
        DO ibl=2,nbl(is)
!
          CALL PUSHINTEGER4(iv)
          iv = isys(ibl, is)
!
          CALL PUSHBOOLEAN(simi)
          simi = ibl .EQ. 2
          wake = ibl .GT. iblte(is)
          CALL PUSHBOOLEAN(tran)
          tran = ibl .EQ. itran(is)
          CALL PUSHBOOLEAN(turb)
          turb = ibl .GT. itran(is)
!
          i = ipan(ibl, is)
!
!---- set primary variables for current station
          xsi = xssi(ibl, is)
          IF (ibl .LT. itran(is)) THEN
            ami = ctau(ibl, is)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (ibl .GE. itran(is)) THEN
            cti = ctau(ibl, is)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHREAL8(uei)
          uei = uedg(ibl, is)
          thi = thet(ibl, is)
          CALL PUSHREAL8(mdi)
          mdi = mass(ibl, is)
!
          CALL PUSHREAL8(dsi)
          dsi = mdi/uei
!
          IF (wake) THEN
            CALL PUSHINTEGER4(iw)
            iw = ibl - iblte(is)
            dswaki = wgap(iw)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
            dswaki = 0.
          END IF
!
!---- set derivatives of DSI (= D2)
          d2_m2 = 1.0/uei
          CALL PUSHREAL8(d2_u2)
          d2_u2 = -(dsi/uei)
!
          DO js=1,2
            DO jbl=2,nbl(js)
              j = ipan(jbl, js)
              jv = isys(jbl, js)
              CALL PUSHREAL8(u2_m(jv))
              u2_m(jv) = -(vti(ibl, is)*vti(jbl, js)*dij(i, j))
              CALL PUSHREAL8(d2_m(jv))
              d2_m(jv) = d2_u2*u2_m(jv)
            END DO
            CALL PUSHINTEGER4(jbl - 1)
          END DO
          CALL PUSHREAL8(d2_m(iv))
          d2_m(iv) = d2_m(iv) + d2_m2
!
          CALL PUSHREAL8(u2_a)
          u2_a = uinv_a(ibl, is)
          CALL PUSHREAL8(d2_a)
          d2_a = d2_u2*u2_a
!
!---- "forced" changes due to mismatch between UEDG and USAV=UINV+dij*MASS
          CALL PUSHREAL8(due2)
          due2 = uedg(ibl, is) - usav(ibl, is)
          CALL PUSHREAL8(dds2)
          dds2 = d2_u2*due2
!
          CALL PUSHREAL8(u2)
          CALL PUSHREAL8(d2)
          CALL PUSHREAL8(t2)
          CALL PUSHREAL8(s2)
          CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
          CALL PUSHREAL8(hk2_ms)
          CALL PUSHREAL8(rt2_ms)
          CALL PUSHREAL8(r2)
          CALL PUSHREAL8(h2_d2)
          CALL PUSHREAL8(hk2_u2)
          CALL PUSHREAL8(rt2_u2)
          CALL PUSHREAL8(h2_t2)
          CALL PUSHREAL8(h2)
          CALL PUSHREAL8(hk2_d2)
          CALL PUSHREAL8(hk2_t2)
          CALL PUSHREAL8(rt2_t2)
          CALL PUSHREAL8(rt2_re)
          CALL PUSHREAL8(m2)
          CALL PUSHREAL8(m2_ms)
          CALL PUSHREAL8(m2_u2)
          CALL PUSHREAL8(rt2)
          CALL BLKIN()
!
!---- check for transition and set TRAN, XT, etc. if found
          IF (tran) THEN
            CALL PUSHREAL8(u2_ms)
            CALL PUSHREAL8(hk2_ms)
            CALL PUSHREAL8(rt2_ms)
            CALL PUSHREAL8(xt_xf)
            CALL PUSHREAL8(cq2)
            CALL PUSHREAL8(cf2_d2)
            CALL PUSHREAL8(di2_re)
            CALL PUSHREAL8(cf2_t2)
            CALL PUSHREAL8(ampl2)
            CALL PUSHREAL8(r2)
            CALL PUSHREAL8(hc2_d2)
            CALL PUSHREAL8(us2_d2)
            CALL PUSHREAL8(de2)
            CALL PUSHREAL8(h2_d2)
            CALL PUSHREAL8(hc2_t2)
            CALL PUSHREAL8(us2_t2)
            CALL PUSHREAL8(u2)
            CALL PUSHREAL8(hk2_u2)
            CALL PUSHREAL8(rt2_u2)
            CALL PUSHREAL8(h2_t2)
            CALL PUSHREAL8(cf2_re)
            CALL PUSHREAL8(h2)
            CALL PUSHREAL8(x2)
            CALL PUSHREAL8ARRAY(c2sav, ncom)
            CALL PUSHREAL8(di2_s2)
            CALL PUSHREAL8(us2_re)
            CALL PUSHREAL8(cq2_ms)
            CALL PUSHREAL8(xt_ms)
            CALL PUSHREAL8(de2_ms)
            CALL PUSHREAL8(hc2)
            CALL PUSHREAL8(hs2_ms)
            CALL PUSHREAL8(hs2)
            CALL PUSHREAL8(v2_re)
            CALL PUSHREAL8(us2)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8(hk2_d2)
            CALL PUSHREAL8(d2)
            CALL PUSHREAL8(di2_ms)
            CALL PUSHREAL8(cq2_u2)
            CALL PUSHREAL8(xt_u2)
            CALL PUSHREAL8(de2_u2)
            CALL PUSHREAL8(xt_u1)
            CALL PUSHREAL8(t2)
            CALL PUSHREAL8(hk2_t2)
            CALL PUSHREAL8(rt2_t2)
            CALL PUSHREAL8(hs2_u2)
            CALL PUSHREAL8(xt_x2)
            CALL PUSHREAL8(xt_x1)
            CALL PUSHREAL8(u2_uei)
            CALL PUSHREAL8(dw2)
            CALL PUSHREAL8(xt)
            CALL PUSHREAL8(rt2_re)
            CALL PUSHREAL8(cf2_ms)
            CALL PUSHREAL8(r2_ms)
            CALL PUSHREAL8(di2_u2)
            CALL PUSHREAL8(m2)
            CALL PUSHREAL8(m2_ms)
            CALL PUSHREAL8(xt_a1)
            CALL PUSHREAL8(hc2_ms)
            CALL PUSHREAL8(us2_ms)
            CALL PUSHREAL8(cq2_d2)
            CALL PUSHREAL8(xt_d2)
            CALL PUSHREAL8(de2_d2)
            CALL PUSHREAL8(xt_d1)
            CALL PUSHREAL8(hs2_d2)
            CALL PUSHREAL8(v2_ms)
            CALL PUSHREAL8(cq2_t2)
            CALL PUSHREAL8(cf2_u2)
            CALL PUSHREAL8(xt_t2)
            CALL PUSHREAL8(r2_u2)
            CALL PUSHREAL8(de2_t2)
            CALL PUSHREAL8(xt_t1)
            CALL PUSHREAL8(s2)
            CALL PUSHREAL8(hs2_t2)
            CALL PUSHREAL8(m2_u2)
            CALL PUSHREAL8(hk2)
            CALL PUSHREAL8(hc2_u2)
            CALL PUSHREAL8(v2)
            CALL PUSHREAL8(us2_u2)
            CALL PUSHREAL8(cq2_re)
            CALL PUSHREAL8(xt_re)
            CALL PUSHREAL8(di2)
            CALL PUSHREAL8(di2_d2)
            CALL PUSHREAL8(hs2_re)
            CALL PUSHREAL8(v2_u2)
            CALL PUSHREAL8(rt2)
            CALL PUSHREAL8(di2_t2)
            setbl = TRCHEK()
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (daeps SAVEd by trchek2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
            IF (abort_on_nan .AND. (.NOT.setbl)) THEN
              GOTO 100
            ELSE
              ami = ampl2
              CALL PUSHCONTROL1B(0)
            END IF
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (ibl .EQ. itran(is) .AND. (.NOT.tran) .AND. show_output) &
&           WRITE(*, *) 'SETBL: Xtr???  n1 n2: ', ampl1, ampl2
!
!---- assemble 10x4 linearized system for dCtau, dTh, dDs, dUe, dXi
!     at the previous "1" station and the current "2" station
!
          IF (ibl .EQ. iblte(is) + 1) THEN
!
!----- define quantities at start of wake, adding TE base thickness to Dstar
            CALL PUSHREAL8(tte)
            tte = thet(iblte(1), 1) + thet(iblte(2), 2)
            dte = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
            CALL PUSHREAL8(cte)
            cte = (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(iblte(2), 2)&
&             *thet(iblte(2), 2))/tte
            CALL PUSHREAL8ARRAY(vsx, 4)
            CALL PUSHREAL8ARRAY(vsr, 4)
            CALL PUSHREAL8ARRAY(vsm, 4)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8ARRAY(vs1, 4*5)
            CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL TESYS(cte, tte, dte)
!
            CALL PUSHREAL8(tte_tte1)
            tte_tte1 = 1.0
            CALL PUSHREAL8(tte_tte2)
            tte_tte2 = 1.0
            dte_mte1 = 1.0/uedg(iblte(1), 1)
            CALL PUSHREAL8(dte_ute1)
            dte_ute1 = -(dstr(iblte(1), 1)/uedg(iblte(1), 1))
            dte_mte2 = 1.0/uedg(iblte(2), 2)
            CALL PUSHREAL8(dte_ute2)
            dte_ute2 = -(dstr(iblte(2), 2)/uedg(iblte(2), 2))
            CALL PUSHREAL8(cte_cte1)
            cte_cte1 = thet(iblte(1), 1)/tte
            CALL PUSHREAL8(cte_cte2)
            cte_cte2 = thet(iblte(2), 2)/tte
            CALL PUSHREAL8(cte_tte1)
            cte_tte1 = (ctau(iblte(1), 1)-cte)/tte
            CALL PUSHREAL8(cte_tte2)
            cte_tte2 = (ctau(iblte(2), 2)-cte)/tte
!
!----- re-define D1 sensitivities wrt m since D1 depends on both TE Ds values
            DO js=1,2
              DO jbl=2,nbl(js)
                jv = isys(jbl, js)
                CALL PUSHREAL8(d1_m(jv))
                d1_m(jv) = dte_ute1*ute1_m(jv) + dte_ute2*ute2_m(jv)
              END DO
              CALL PUSHINTEGER4(jbl - 1)
            END DO
            CALL PUSHREAL8(d1_m(jvte1))
            d1_m(jvte1) = d1_m(jvte1) + dte_mte1
            CALL PUSHREAL8(d1_m(jvte2))
            d1_m(jvte2) = d1_m(jvte2) + dte_mte2
!
!----- "forced" changes from  UEDG --- USAV=UINV+dij*MASS  mismatch
            due1 = 0.
            dds1 = dte_ute1*(uedg(iblte(1), 1)-usav(iblte(1), 1)) + &
&             dte_ute2*(uedg(iblte(2), 2)-usav(iblte(2), 2))
!
            CALL PUSHCONTROL1B(0)
          ELSE
!
            CALL PUSHREAL8(rt1)
            CALL PUSHREAL8(di1_re)
            CALL PUSHREAL8(cf1_d1)
            CALL PUSHREAL8(u2_ms)
            CALL PUSHREAL8(hk2_ms)
            CALL PUSHREAL8(cf1_t1)
            CALL PUSHREAL8(rt2_ms)
            CALL PUSHREAL8(cq1)
            CALL PUSHREAL8(hc1_d1)
            CALL PUSHREAL8(us1_d1)
            CALL PUSHREAL8(h1_d1)
            CALL PUSHREAL8(hc1_t1)
            CALL PUSHREAL8(ampl2)
            CALL PUSHREAL8(us1_t1)
            CALL PUSHREAL8(hk1_u1)
            CALL PUSHREAL8(ampl1)
            CALL PUSHREAL8(rt1_u1)
            CALL PUSHREAL8(r2)
            CALL PUSHREAL8(cf1_re)
            CALL PUSHREAL8ARRAY(vsx, 4)
            CALL PUSHREAL8(r1)
            CALL PUSHREAL8(h1_t1)
            CALL PUSHREAL8(de1)
            CALL PUSHREAL8(h2_d2)
            CALL PUSHREAL8ARRAY(c1sav, ncom)
            CALL PUSHREAL8ARRAY(vsr, 4)
            CALL PUSHREAL8(u2)
            CALL PUSHREAL8(hk2_u2)
            CALL PUSHREAL8(di1_s1)
            CALL PUSHREAL8(u1)
            CALL PUSHREAL8(rt2_u2)
            CALL PUSHREAL8(us1_re)
            CALL PUSHREAL8(h2_t2)
            CALL PUSHREAL8(h2)
            CALL PUSHREAL8(cq1_ms)
            CALL PUSHREAL8(h1)
            CALL PUSHREAL8(de1_ms)
            CALL PUSHREAL8ARRAY(vsm, 4)
            CALL PUSHREAL8(hs1_ms)
            CALL PUSHREAL8(x2)
            CALL PUSHREAL8(x1)
            CALL PUSHREAL8ARRAY(c2sav, ncom)
            CALL PUSHREAL8(v1_re)
            CALL PUSHREAL8(hc1)
            CALL PUSHREAL8(v2_re)
            CALL PUSHREAL8(hs1)
            CALL PUSHREAL8(hk1_d1)
            CALL PUSHREAL8(di1_ms)
            CALL PUSHREAL8(cq1_u1)
            CALL PUSHREAL8(de1_u1)
            CALL PUSHREAL8(hk1_t1)
            CALL PUSHREAL8(rt1_t1)
            CALL PUSHREAL8(hs1_u1)
            CALL PUSHREAL8(us1)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8(hk2_d2)
            CALL PUSHREAL8(d2)
            CALL PUSHREAL8(cf1)
            CALL PUSHREAL8(d1)
            CALL PUSHREAL8(t2)
            CALL PUSHREAL8(hk2_t2)
            CALL PUSHREAL8(t1)
            CALL PUSHREAL8(rt2_t2)
            CALL PUSHREAL8(rt1_re)
            CALL PUSHREAL8(cf1_ms)
            CALL PUSHREAL8(r1_ms)
            CALL PUSHREAL8(u2_uei)
            CALL PUSHREAL8(dw2)
            CALL PUSHREAL8(di1_u1)
            CALL PUSHREAL8(dw1)
            CALL PUSHREAL8(m1_ms)
            CALL PUSHREAL8(hc1_ms)
            CALL PUSHREAL8(us1_ms)
            CALL PUSHREAL8(rt2_re)
            CALL PUSHREAL8(r2_ms)
            CALL PUSHREAL8(m2)
            CALL PUSHREAL8(cq1_d1)
            CALL PUSHREAL8(m2_ms)
            CALL PUSHREAL8(m1)
            CALL PUSHREAL8(de1_d1)
            CALL PUSHREAL8(v1_ms)
            CALL PUSHREAL8(hs1_d1)
            CALL PUSHREAL8(cq1_t1)
            CALL PUSHREAL8(cf1_u1)
            CALL PUSHREAL8(r1_u1)
            CALL PUSHREAL8(de1_t1)
            CALL PUSHREAL8(hs1_t1)
            CALL PUSHREAL8(m1_u1)
            CALL PUSHREAL8(u1_uei)
            CALL PUSHREAL8(v2_ms)
            CALL PUSHREAL8(hc1_u1)
            CALL PUSHREAL8(us1_u1)
            CALL PUSHREAL8(r2_u2)
            CALL PUSHREAL8(s2)
            CALL PUSHREAL8(cq1_re)
            CALL PUSHREAL8(s1)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8ARRAY(vs1, 4*5)
            CALL PUSHREAL8(hs1_re)
            CALL PUSHREAL8(di1_d1)
            CALL PUSHREAL8(m2_u2)
            CALL PUSHREAL8(hk2)
            CALL PUSHREAL8(hk1)
            CALL PUSHREAL8(v2)
            CALL PUSHREAL8(v1_u1)
            CALL PUSHREAL8(di1_t1)
            CALL PUSHREAL8(v1)
            CALL PUSHREAL8(u1_ms)
            CALL PUSHREAL8(di1)
            CALL PUSHREAL8(hk1_ms)
            CALL PUSHREAL8(rt1_ms)
            CALL PUSHREAL8(v2_u2)
            CALL PUSHREAL8(rt2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL BLSYS()
!
            CALL PUSHCONTROL1B(1)
          END IF
!
!
!---- Save wall shear and equil. max shear coefficient for plotting output
!
!@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
!      IF(WAKE) THEN
!        ALD = DLCON
!      ELSE
!       ALD = 1.0
!      ENDIF
!C
!      IF(TURB .AND. .NOT.WAKE) THEN
!        GCC = GCCON
!        HKC     = HK2 - 1.0 - GCC/RT2
!        IF(HKC .LT. 0.01) THEN
!         HKC = 0.01
!        ENDIF
!       ELSE
!        HKC = HK2 - 1.0
!       ENDIF
!C
!       HR = HKC     / (GACON*ALD*HK2)
!       UQ = (0.5*CF2 - HR**2) / (GBCON*D2)
!C
!       IF(TURB) THEN
!        IBLP = MIN(IBL+1,NBL(IS))
!        IBLM = MAX(IBL-1,2      )
!        DXSSI = XSSI(IBLP,IS) - XSSI(IBLM,IS)
!        IF(DXXSI.EQ.0.0) DXSSI = 1.0
!        GUXD(IBL,IS) = -LOG(UEDG(IBLP,IS)/UEDG(IBLM,IS)) / DXSSI
!        GUXQ(IBL,IS) = -UQ
!       ELSE
!        GUXD(IBL,IS) = 0.0
!        GUXQ(IBL,IS) = 0.0
!       ENDIF
!@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
!
!---- set XI sensitivities wrt LE Ue changes
          IF (is .EQ. 1) THEN
            CALL PUSHREAL8(xi_ule1)
            xi_ule1 = sst_go
            CALL PUSHREAL8(xi_ule2)
            xi_ule2 = -sst_gp
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHREAL8(xi_ule1)
            xi_ule1 = -sst_go
            CALL PUSHREAL8(xi_ule2)
            xi_ule2 = sst_gp
            CALL PUSHCONTROL1B(0)
          END IF
          CALL PUSHINTEGER4(jv)
!
!
!
          IF (lalfa) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!
!
          IF (lalfa) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!
!
          IF (lalfa) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!
!
          IF (ibl .EQ. iblte(is) + 1) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!---- turbulent intervals will follow if currently at transition interval
          IF (tran) THEN
!
!------ save transition location
            itran(is) = ibl
            tforce(is) = trforc
!
!------ interpolate airfoil geometry to find transition x/c
!-      (for user output)
            IF (is .EQ. 1) THEN
              CALL PUSHREAL8(str)
              str = sst - xt
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHREAL8(str)
              str = sst + xt
              CALL PUSHCONTROL2B(1)
            END IF
            chx = xte - xle
            chy = yte - yle
            chsq = chx**2 + chy**2
            xtr = SEVAL(str, x, xp, s, n)
            ytr = SEVAL(str, y, yp, s, n)
            xoctr(is) = ((xtr-xle)*chx+(ytr-yle)*chy)/chsq
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
!
!
          IF (ibl .EQ. iblte(is)) THEN
!----- set "2" variables at TE to wake correlations for next station
!
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL BLVAR(3)
            CALL PUSHREAL8(rt1)
            CALL PUSHREAL8(hk1_u1)
            CALL PUSHREAL8(rt1_u1)
            CALL PUSHREAL8(hk1_d1)
            CALL PUSHREAL8(hk1_t1)
            CALL PUSHREAL8(rt1_t1)
            CALL PUSHREAL8(rt1_re)
            CALL PUSHREAL8(hk1)
            CALL PUSHREAL8(hk1_ms)
            CALL PUSHREAL8(rt1_ms)
            CALL BLMID(3)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
!
          DO js=1,2
            DO jbl=2,nbl(js)
              jv = isys(jbl, js)
              CALL PUSHREAL8(u1_m(jv))
              u1_m(jv) = u2_m(jv)
              CALL PUSHREAL8(d1_m(jv))
              d1_m(jv) = d2_m(jv)
            END DO
            CALL PUSHINTEGER4(jbl - 1)
          END DO
!
          CALL PUSHREAL8(u1_a)
          u1_a = u2_a
          CALL PUSHREAL8(d1_a)
          d1_a = d2_a
!
          CALL PUSHREAL8(due1)
          due1 = due2
          CALL PUSHREAL8(dds1)
          dds1 = dds2
!
! if (ibl==ITRan(is) .and. X2>X1) then
!
!---- set BL variables for next station
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(ampl1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(u1)
          CALL PUSHREAL8(x1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(d1)
          CALL PUSHREAL8(t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLC_1FROM2()
          CALL PUSHINTEGER4(ibl)
          ad_count = ad_count + 1
        END DO
        CALL PUSHCONTROL1B(0)
        CALL PUSHINTEGER4(ad_count)
!
!---- next streamwise station
!
        IF (tforce(is)) THEN
          IF (show_output) THEN
            CALL PUSHINTEGER4(is)
            CALL PUSHCONTROL2B(1)
            WRITE(*, 99001) is, xoctr(is), itran(is)
          ELSE
            CALL PUSHINTEGER4(is)
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE IF (show_output) THEN
          CALL PUSHINTEGER4(is)
          CALL PUSHCONTROL2B(2)
          WRITE(*, 99002) is, xoctr(is), itran(is)
        ELSE
          CALL PUSHINTEGER4(is)
          CALL PUSHCONTROL2B(2)
        END IF
      END DO
      hstinvb = 0.0_8
      reyblb = 0.0_8
      tkbl_msb = 0.0_8
      tkblb = 0.0_8
      reybl_reb = 0.0_8
      hstinv_msb = 0.0_8
      rstbl_msb = 0.0_8
      rstblb = 0.0_8
      reybl_msb = 0.0_8
      sst_gob = 0.0_8
      sst_gpb = 0.0_8
      sstb = 0.0_8
      amib = 0.0_8
      ute2_mb = 0.0_8
      d2_mb = 0.0_8
      dule1b = 0.0_8
      dule2b = 0.0_8
      ule2_ab = 0.0_8
      cte_cte1b = 0.0_8
      cte_cte2b = 0.0_8
      ule2_mb = 0.0_8
      ctib = 0.0_8
      ute1_mb = 0.0_8
      d1_mb = 0.0_8
      u2_mb = 0.0_8
      msq_clmrb = 0.0_8
      ule1_ab = 0.0_8
      re_clmrb = 0.0_8
      ule1_mb = 0.0_8
      cte_tte1b = 0.0_8
      cte_tte2b = 0.0_8
      usavb = 0.0_8
      u1_mb = 0.0_8
      GOTO 140
 100  CALL PUSHCONTROL1B(1)
      CALL PUSHINTEGER4(ad_count)
 110  CALL POPINTEGER4(ad_count)
      DO i0=1,ad_count
        IF (i0 .EQ. 1) THEN
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            xiforcb = 0.0_8
            amcritb = 0.0_8
            dds1b = 0.0_8
            due1b = 0.0_8
            d1_ab = 0.0_8
            u1_ab = 0.0_8
            GOTO 130
          ELSE
            rt2b = 0.0_8
            v2_u2b = 0.0_8
            v2b = 0.0_8
            hk2b = 0.0_8
            m2_u2b = 0.0_8
            hstinvb = 0.0_8
            reyblb = 0.0_8
            xiforcb = 0.0_8
            s2b = 0.0_8
            r2_u2b = 0.0_8
            v2_msb = 0.0_8
            tkbl_msb = 0.0_8
            m2_msb = 0.0_8
            tkblb = 0.0_8
            m2b = 0.0_8
            reybl_reb = 0.0_8
            r2_msb = 0.0_8
            rt2_reb = 0.0_8
            dw2b = 0.0_8
            u2_ueib = 0.0_8
            rt2_t2b = 0.0_8
            hk2_t2b = 0.0_8
            t2b = 0.0_8
            d2b = 0.0_8
            hk2_d2b = 0.0_8
            v2_reb = 0.0_8
            x2b = 0.0_8
            hstinv_msb = 0.0_8
            amcritb = 0.0_8
            h2b = 0.0_8
            h2_t2b = 0.0_8
            rt2_u2b = 0.0_8
            hk2_u2b = 0.0_8
            u2b = 0.0_8
            h2_d2b = 0.0_8
            rstbl_msb = 0.0_8
            rstblb = 0.0_8
            r2b = 0.0_8
            ampl2b = 0.0_8
            reybl_msb = 0.0_8
            rt2_msb = 0.0_8
            hk2_msb = 0.0_8
            u2_msb = 0.0_8
            sst_gob = 0.0_8
            sst_gpb = 0.0_8
            sstb = 0.0_8
            ute2_mb = 0.0_8
            d2_mb = 0.0_8
            dds1b = 0.0_8
            dule1b = 0.0_8
            dds2b = 0.0_8
            dule2b = 0.0_8
            due1b = 0.0_8
            due2b = 0.0_8
            ule2_ab = 0.0_8
            d1_ab = 0.0_8
            cte_cte1b = 0.0_8
            cte_cte2b = 0.0_8
            ule2_mb = 0.0_8
            u2_ab = 0.0_8
            ctib = 0.0_8
            ute1_mb = 0.0_8
            d1_mb = 0.0_8
            u2_mb = 0.0_8
            msq_clmrb = 0.0_8
            ule1_ab = 0.0_8
            re_clmrb = 0.0_8
            ule1_mb = 0.0_8
            u1_ab = 0.0_8
            cte_tte1b = 0.0_8
            cte_tte2b = 0.0_8
            usavb = 0.0_8
            u1_mb = 0.0_8
            d2_ab = 0.0_8
          END IF
        ELSE
          CALL POPREAL8(rt1_ms)
          CALL POPREAL8(hk1_ms)
          CALL POPREAL8(hk1)
          CALL POPREAL8(rt1_re)
          CALL POPREAL8(t1)
          CALL POPREAL8(d1)
          CALL POPREAL8(rt1_t1)
          CALL POPREAL8(hk1_t1)
          CALL POPREAL8(hk1_d1)
          CALL POPREAL8(x1)
          CALL POPREAL8(u1)
          CALL POPREAL8(rt1_u1)
          CALL POPREAL8(ampl1)
          CALL POPREAL8(hk1_u1)
          CALL POPREAL8(rt1)
          u2_msb = 0.0_8
          hk2_msb = 0.0_8
          rt2_msb = 0.0_8
          ampl2b = 0.0_8
          r2b = 0.0_8
          h2_d2b = 0.0_8
          u2b = 0.0_8
          hk2_u2b = 0.0_8
          rt2_u2b = 0.0_8
          h2_t2b = 0.0_8
          h2b = 0.0_8
          x2b = 0.0_8
          v2_reb = 0.0_8
          hk2_d2b = 0.0_8
          d2b = 0.0_8
          t2b = 0.0_8
          hk2_t2b = 0.0_8
          rt2_t2b = 0.0_8
          u2_ueib = 0.0_8
          dw2b = 0.0_8
          rt2_reb = 0.0_8
          r2_msb = 0.0_8
          m2b = 0.0_8
          m2_msb = 0.0_8
          v2_msb = 0.0_8
          r2_u2b = 0.0_8
          s2b = 0.0_8
          m2_u2b = 0.0_8
          hk2b = 0.0_8
          v2b = 0.0_8
          v2_u2b = 0.0_8
          rt2b = 0.0_8
          CALL BLC_1FROM2_B()
          CALL POPREAL8(dds1)
          dds2b = dds1b
          CALL POPREAL8(due1)
          due2b = due1b
          CALL POPREAL8(d1_a)
          d2_ab = d1_ab
          CALL POPREAL8(u1_a)
          u2_ab = u1_ab
          DO js=2,1,-1
            CALL POPINTEGER4(ad_to5)
            DO jbl=ad_to5,2,-1
              jv = isys(jbl, js)
              CALL POPREAL8(d1_m(jv))
              d2_mb(jv) = d2_mb(jv) + d1_mb(jv)
              d1_mb(jv) = 0.0_8
              CALL POPREAL8(u1_m(jv))
              u2_mb(jv) = u2_mb(jv) + u1_mb(jv)
              u1_mb(jv) = 0.0_8
            END DO
          END DO
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            simi = ibl .EQ. 2
            CALL POPREAL8(rt1_ms)
            CALL POPREAL8(hk1_ms)
            CALL POPREAL8(hk1)
            CALL POPREAL8(rt1_re)
            CALL POPREAL8(rt1_t1)
            CALL POPREAL8(hk1_t1)
            CALL POPREAL8(hk1_d1)
            CALL POPREAL8(rt1_u1)
            CALL POPREAL8(hk1_u1)
            CALL POPREAL8(rt1)
            CALL POPREAL8(hk2)
            CALL POPREAL8(cf2)
            CALL BLVAR_B(3)
            di2_t2b = 0.0_8
            hs2_reb = 0.0_8
            di2_d2b = 0.0_8
            di2b = 0.0_8
            cq2_reb = 0.0_8
            us2_u2b = 0.0_8
            hc2_u2b = 0.0_8
            hs2_t2b = 0.0_8
            de2_t2b = 0.0_8
            cf2_u2b = 0.0_8
            cq2_t2b = 0.0_8
            hs2_d2b = 0.0_8
            de2_d2b = 0.0_8
            cq2_d2b = 0.0_8
            us2_msb = 0.0_8
            hc2_msb = 0.0_8
            di2_u2b = 0.0_8
            cf2_msb = 0.0_8
            hs2_u2b = 0.0_8
            de2_u2b = 0.0_8
            cq2_u2b = 0.0_8
            di2_msb = 0.0_8
            cf2b = 0.0_8
            us2b = 0.0_8
            hs2b = 0.0_8
            hs2_msb = 0.0_8
            hc2b = 0.0_8
            de2_msb = 0.0_8
            cq2_msb = 0.0_8
            us2_reb = 0.0_8
            di2_s2b = 0.0_8
            cf2_reb = 0.0_8
            us2_t2b = 0.0_8
            hc2_t2b = 0.0_8
            de2b = 0.0_8
            us2_d2b = 0.0_8
            hc2_d2b = 0.0_8
            cf2_t2b = 0.0_8
            di2_reb = 0.0_8
            cf2_d2b = 0.0_8
            cq2b = 0.0_8
          END IF
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(str)
          ELSE IF (branch .EQ. 1) THEN
            CALL POPREAL8(str)
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            iv = isys(ibl, is)
            vs1b(3, 1) = vs1b(3, 1) + cte_tte2*vbb(3, 2, iv) + cte_cte2*&
&             vbb(3, 1, iv) + cte_tte1*vzb(3, 2) + cte_cte1*vzb(3, 1)
            cte_tte2b = cte_tte2b + vs1(3, 1)*vbb(3, 2, iv) + vs1(2, 1)*&
&             vbb(2, 2, iv) + vs1(1, 1)*vbb(1, 2, iv)
            vs1b(3, 2) = vs1b(3, 2) + tte_tte2*vbb(3, 2, iv) + tte_tte1*&
&             vzb(3, 2)
            vbb(3, 2, iv) = 0.0_8
            cte_cte2b = cte_cte2b + vs1(3, 1)*vbb(3, 1, iv) + vs1(2, 1)*&
&             vbb(2, 1, iv) + vs1(1, 1)*vbb(1, 1, iv)
            vbb(3, 1, iv) = 0.0_8
            cte_tte1b = cte_tte1b + vs1(3, 1)*vzb(3, 2) + vs1(2, 1)*vzb(&
&             2, 2) + vs1(1, 1)*vzb(1, 2)
            vzb(3, 2) = 0.0_8
            cte_cte1b = cte_cte1b + vs1(3, 1)*vzb(3, 1) + vs1(2, 1)*vzb(&
&             2, 1) + vs1(1, 1)*vzb(1, 1)
            vzb(3, 1) = 0.0_8
            vs1b(2, 1) = vs1b(2, 1) + cte_tte2*vbb(2, 2, iv) + cte_cte2*&
&             vbb(2, 1, iv) + cte_tte1*vzb(2, 2) + cte_cte1*vzb(2, 1)
            vs1b(2, 2) = vs1b(2, 2) + tte_tte2*vbb(2, 2, iv) + tte_tte1*&
&             vzb(2, 2)
            vbb(2, 2, iv) = 0.0_8
            vbb(2, 1, iv) = 0.0_8
            vzb(2, 2) = 0.0_8
            vzb(2, 1) = 0.0_8
            vs1b(1, 1) = vs1b(1, 1) + cte_tte2*vbb(1, 2, iv) + cte_cte2*&
&             vbb(1, 1, iv) + cte_tte1*vzb(1, 2) + cte_cte1*vzb(1, 1)
            vs1b(1, 2) = vs1b(1, 2) + tte_tte2*vbb(1, 2, iv) + tte_tte1*&
&             vzb(1, 2)
            vbb(1, 2, iv) = 0.0_8
            vbb(1, 1, iv) = 0.0_8
            vzb(1, 2) = 0.0_8
            vzb(1, 1) = 0.0_8
          END IF
          vsrezb(3) = vsrezb(3) + vdelb(3, 1, iv)
          vs1b(3, 4) = vs1b(3, 4) + due1*vdelb(3, 1, iv)
          due1b = vs1(3, 4)*vdelb(3, 1, iv)
          vs1b(3, 3) = vs1b(3, 3) + dds1*vdelb(3, 1, iv)
          dds1b = vs1(3, 3)*vdelb(3, 1, iv)
          vs2b(3, 4) = vs2b(3, 4) + due2*vdelb(3, 1, iv)
          due2b = due2b + vs2(3, 4)*vdelb(3, 1, iv)
          vs2b(3, 3) = vs2b(3, 3) + dds2*vdelb(3, 1, iv)
          dds2b = dds2b + vs2(3, 3)*vdelb(3, 1, iv)
          tempb2 = (xi_ule1*dule1+xi_ule2*dule2)*vdelb(3, 1, iv)
          tempb0 = (vs1(3, 5)+vs2(3, 5)+vsx(3))*vdelb(3, 1, iv)
          vdelb(3, 1, iv) = 0.0_8
          xi_ule1b = dule1*tempb0
          dule1b = dule1b + xi_ule1*tempb0
          xi_ule2b = dule2*tempb0
          dule2b = dule2b + xi_ule2*tempb0
          vs1b(3, 5) = vs1b(3, 5) + tempb2
          vs2b(3, 5) = vs2b(3, 5) + tempb2
          vsxb(3) = vsxb(3) + tempb2
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            vsrb(3) = vsrb(3) + re_clmr*vdelb(3, 2, iv)
            re_clmrb = re_clmrb + vsr(3)*vdelb(3, 2, iv)
            vsmb(3) = vsmb(3) + msq_clmr*vdelb(3, 2, iv)
            msq_clmrb = msq_clmrb + vsm(3)*vdelb(3, 2, iv)
            vdelb(3, 2, iv) = 0.0_8
            d1_ab = 0.0_8
            u1_ab = 0.0_8
          ELSE
            vs1b(3, 4) = vs1b(3, 4) + u1_a*vdelb(3, 2, iv)
            u1_ab = vs1(3, 4)*vdelb(3, 2, iv)
            vs1b(3, 3) = vs1b(3, 3) + d1_a*vdelb(3, 2, iv)
            d1_ab = vs1(3, 3)*vdelb(3, 2, iv)
            vs2b(3, 4) = vs2b(3, 4) + u2_a*vdelb(3, 2, iv)
            u2_ab = u2_ab + vs2(3, 4)*vdelb(3, 2, iv)
            vs2b(3, 3) = vs2b(3, 3) + d2_a*vdelb(3, 2, iv)
            d2_ab = d2_ab + vs2(3, 3)*vdelb(3, 2, iv)
            tempb2 = (xi_ule1*ule1_a+xi_ule2*ule2_a)*vdelb(3, 2, iv)
            tempb0 = (vs1(3, 5)+vs2(3, 5)+vsx(3))*vdelb(3, 2, iv)
            vdelb(3, 2, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_a*tempb0
            ule1_ab = ule1_ab + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_a*tempb0
            ule2_ab = ule2_ab + xi_ule2*tempb0
            vs1b(3, 5) = vs1b(3, 5) + tempb2
            vs2b(3, 5) = vs2b(3, 5) + tempb2
            vsxb(3) = vsxb(3) + tempb2
          END IF
          vs2b(3, 2) = vs2b(3, 2) + vab(3, 2, iv)
          vab(3, 2, iv) = 0.0_8
          vs2b(3, 1) = vs2b(3, 1) + vab(3, 1, iv)
          vab(3, 1, iv) = 0.0_8
          vs1b(3, 2) = vs1b(3, 2) + vbb(3, 2, iv)
          vbb(3, 2, iv) = 0.0_8
          vs1b(3, 1) = vs1b(3, 1) + vbb(3, 1, iv)
          vbb(3, 1, iv) = 0.0_8
          DO jv=nsys,1,-1
            vs1b(3, 3) = vs1b(3, 3) + d1_m(jv)*vmb(3, jv, iv)
            d1_mb(jv) = d1_mb(jv) + vs1(3, 3)*vmb(3, jv, iv)
            vs1b(3, 4) = vs1b(3, 4) + u1_m(jv)*vmb(3, jv, iv)
            u1_mb(jv) = u1_mb(jv) + vs1(3, 4)*vmb(3, jv, iv)
            vs2b(3, 3) = vs2b(3, 3) + d2_m(jv)*vmb(3, jv, iv)
            d2_mb(jv) = d2_mb(jv) + vs2(3, 3)*vmb(3, jv, iv)
            vs2b(3, 4) = vs2b(3, 4) + u2_m(jv)*vmb(3, jv, iv)
            u2_mb(jv) = u2_mb(jv) + vs2(3, 4)*vmb(3, jv, iv)
            tempb2 = (xi_ule1*ule1_m(jv)+xi_ule2*ule2_m(jv))*vmb(3, jv, &
&             iv)
            tempb0 = (vs1(3, 5)+vs2(3, 5)+vsx(3))*vmb(3, jv, iv)
            vmb(3, jv, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_m(jv)*tempb0
            ule1_mb(jv) = ule1_mb(jv) + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_m(jv)*tempb0
            ule2_mb(jv) = ule2_mb(jv) + xi_ule2*tempb0
            vs1b(3, 5) = vs1b(3, 5) + tempb2
            vs2b(3, 5) = vs2b(3, 5) + tempb2
            vsxb(3) = vsxb(3) + tempb2
          END DO
          vsrezb(2) = vsrezb(2) + vdelb(2, 1, iv)
          vs1b(2, 4) = vs1b(2, 4) + due1*vdelb(2, 1, iv)
          due1b = due1b + vs1(2, 4)*vdelb(2, 1, iv)
          vs1b(2, 3) = vs1b(2, 3) + dds1*vdelb(2, 1, iv)
          dds1b = dds1b + vs1(2, 3)*vdelb(2, 1, iv)
          vs2b(2, 4) = vs2b(2, 4) + due2*vdelb(2, 1, iv)
          due2b = due2b + vs2(2, 4)*vdelb(2, 1, iv)
          vs2b(2, 3) = vs2b(2, 3) + dds2*vdelb(2, 1, iv)
          dds2b = dds2b + vs2(2, 3)*vdelb(2, 1, iv)
          tempb2 = (xi_ule1*dule1+xi_ule2*dule2)*vdelb(2, 1, iv)
          tempb0 = (vs1(2, 5)+vs2(2, 5)+vsx(2))*vdelb(2, 1, iv)
          vdelb(2, 1, iv) = 0.0_8
          xi_ule1b = xi_ule1b + dule1*tempb0
          dule1b = dule1b + xi_ule1*tempb0
          xi_ule2b = xi_ule2b + dule2*tempb0
          dule2b = dule2b + xi_ule2*tempb0
          vs1b(2, 5) = vs1b(2, 5) + tempb2
          vs2b(2, 5) = vs2b(2, 5) + tempb2
          vsxb(2) = vsxb(2) + tempb2
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            vsrb(2) = vsrb(2) + re_clmr*vdelb(2, 2, iv)
            re_clmrb = re_clmrb + vsr(2)*vdelb(2, 2, iv)
            vsmb(2) = vsmb(2) + msq_clmr*vdelb(2, 2, iv)
            msq_clmrb = msq_clmrb + vsm(2)*vdelb(2, 2, iv)
            vdelb(2, 2, iv) = 0.0_8
          ELSE
            vs1b(2, 4) = vs1b(2, 4) + u1_a*vdelb(2, 2, iv)
            u1_ab = u1_ab + vs1(2, 4)*vdelb(2, 2, iv)
            vs1b(2, 3) = vs1b(2, 3) + d1_a*vdelb(2, 2, iv)
            d1_ab = d1_ab + vs1(2, 3)*vdelb(2, 2, iv)
            vs2b(2, 4) = vs2b(2, 4) + u2_a*vdelb(2, 2, iv)
            u2_ab = u2_ab + vs2(2, 4)*vdelb(2, 2, iv)
            vs2b(2, 3) = vs2b(2, 3) + d2_a*vdelb(2, 2, iv)
            d2_ab = d2_ab + vs2(2, 3)*vdelb(2, 2, iv)
            tempb2 = (xi_ule1*ule1_a+xi_ule2*ule2_a)*vdelb(2, 2, iv)
            tempb0 = (vs1(2, 5)+vs2(2, 5)+vsx(2))*vdelb(2, 2, iv)
            vdelb(2, 2, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_a*tempb0
            ule1_ab = ule1_ab + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_a*tempb0
            ule2_ab = ule2_ab + xi_ule2*tempb0
            vs1b(2, 5) = vs1b(2, 5) + tempb2
            vs2b(2, 5) = vs2b(2, 5) + tempb2
            vsxb(2) = vsxb(2) + tempb2
          END IF
          vs2b(2, 2) = vs2b(2, 2) + vab(2, 2, iv)
          vab(2, 2, iv) = 0.0_8
          vs2b(2, 1) = vs2b(2, 1) + vab(2, 1, iv)
          vab(2, 1, iv) = 0.0_8
          vs1b(2, 2) = vs1b(2, 2) + vbb(2, 2, iv)
          vbb(2, 2, iv) = 0.0_8
          vs1b(2, 1) = vs1b(2, 1) + vbb(2, 1, iv)
          vbb(2, 1, iv) = 0.0_8
          DO jv=nsys,1,-1
            vs1b(2, 3) = vs1b(2, 3) + d1_m(jv)*vmb(2, jv, iv)
            d1_mb(jv) = d1_mb(jv) + vs1(2, 3)*vmb(2, jv, iv)
            vs1b(2, 4) = vs1b(2, 4) + u1_m(jv)*vmb(2, jv, iv)
            u1_mb(jv) = u1_mb(jv) + vs1(2, 4)*vmb(2, jv, iv)
            vs2b(2, 3) = vs2b(2, 3) + d2_m(jv)*vmb(2, jv, iv)
            d2_mb(jv) = d2_mb(jv) + vs2(2, 3)*vmb(2, jv, iv)
            vs2b(2, 4) = vs2b(2, 4) + u2_m(jv)*vmb(2, jv, iv)
            u2_mb(jv) = u2_mb(jv) + vs2(2, 4)*vmb(2, jv, iv)
            tempb2 = (xi_ule1*ule1_m(jv)+xi_ule2*ule2_m(jv))*vmb(2, jv, &
&             iv)
            tempb0 = (vs1(2, 5)+vs2(2, 5)+vsx(2))*vmb(2, jv, iv)
            vmb(2, jv, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_m(jv)*tempb0
            ule1_mb(jv) = ule1_mb(jv) + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_m(jv)*tempb0
            ule2_mb(jv) = ule2_mb(jv) + xi_ule2*tempb0
            vs1b(2, 5) = vs1b(2, 5) + tempb2
            vs2b(2, 5) = vs2b(2, 5) + tempb2
            vsxb(2) = vsxb(2) + tempb2
          END DO
          vsrezb(1) = vsrezb(1) + vdelb(1, 1, iv)
          vs1b(1, 4) = vs1b(1, 4) + due1*vdelb(1, 1, iv)
          due1b = due1b + vs1(1, 4)*vdelb(1, 1, iv)
          vs1b(1, 3) = vs1b(1, 3) + dds1*vdelb(1, 1, iv)
          dds1b = dds1b + vs1(1, 3)*vdelb(1, 1, iv)
          vs2b(1, 4) = vs2b(1, 4) + due2*vdelb(1, 1, iv)
          due2b = due2b + vs2(1, 4)*vdelb(1, 1, iv)
          vs2b(1, 3) = vs2b(1, 3) + dds2*vdelb(1, 1, iv)
          dds2b = dds2b + vs2(1, 3)*vdelb(1, 1, iv)
          tempb2 = (xi_ule1*dule1+xi_ule2*dule2)*vdelb(1, 1, iv)
          tempb0 = (vs1(1, 5)+vs2(1, 5)+vsx(1))*vdelb(1, 1, iv)
          vdelb(1, 1, iv) = 0.0_8
          xi_ule1b = xi_ule1b + dule1*tempb0
          dule1b = dule1b + xi_ule1*tempb0
          xi_ule2b = xi_ule2b + dule2*tempb0
          dule2b = dule2b + xi_ule2*tempb0
          vs1b(1, 5) = vs1b(1, 5) + tempb2
          vs2b(1, 5) = vs2b(1, 5) + tempb2
          vsxb(1) = vsxb(1) + tempb2
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            vsrb(1) = vsrb(1) + re_clmr*vdelb(1, 2, iv)
            re_clmrb = re_clmrb + vsr(1)*vdelb(1, 2, iv)
            vsmb(1) = vsmb(1) + msq_clmr*vdelb(1, 2, iv)
            msq_clmrb = msq_clmrb + vsm(1)*vdelb(1, 2, iv)
            vdelb(1, 2, iv) = 0.0_8
          ELSE
            vs1b(1, 4) = vs1b(1, 4) + u1_a*vdelb(1, 2, iv)
            u1_ab = u1_ab + vs1(1, 4)*vdelb(1, 2, iv)
            vs1b(1, 3) = vs1b(1, 3) + d1_a*vdelb(1, 2, iv)
            d1_ab = d1_ab + vs1(1, 3)*vdelb(1, 2, iv)
            vs2b(1, 4) = vs2b(1, 4) + u2_a*vdelb(1, 2, iv)
            u2_ab = u2_ab + vs2(1, 4)*vdelb(1, 2, iv)
            vs2b(1, 3) = vs2b(1, 3) + d2_a*vdelb(1, 2, iv)
            d2_ab = d2_ab + vs2(1, 3)*vdelb(1, 2, iv)
            tempb2 = (xi_ule1*ule1_a+xi_ule2*ule2_a)*vdelb(1, 2, iv)
            tempb0 = (vs1(1, 5)+vs2(1, 5)+vsx(1))*vdelb(1, 2, iv)
            vdelb(1, 2, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_a*tempb0
            ule1_ab = ule1_ab + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_a*tempb0
            ule2_ab = ule2_ab + xi_ule2*tempb0
            vs1b(1, 5) = vs1b(1, 5) + tempb2
            vs2b(1, 5) = vs2b(1, 5) + tempb2
            vsxb(1) = vsxb(1) + tempb2
          END IF
          vs2b(1, 2) = vs2b(1, 2) + vab(1, 2, iv)
          vab(1, 2, iv) = 0.0_8
          vs2b(1, 1) = vs2b(1, 1) + vab(1, 1, iv)
          vab(1, 1, iv) = 0.0_8
          vs1b(1, 2) = vs1b(1, 2) + vbb(1, 2, iv)
          vbb(1, 2, iv) = 0.0_8
          vs1b(1, 1) = vs1b(1, 1) + vbb(1, 1, iv)
          vbb(1, 1, iv) = 0.0_8
          DO jv=nsys,1,-1
            vs1b(1, 3) = vs1b(1, 3) + d1_m(jv)*vmb(1, jv, iv)
            d1_mb(jv) = d1_mb(jv) + vs1(1, 3)*vmb(1, jv, iv)
            vs1b(1, 4) = vs1b(1, 4) + u1_m(jv)*vmb(1, jv, iv)
            u1_mb(jv) = u1_mb(jv) + vs1(1, 4)*vmb(1, jv, iv)
            vs2b(1, 3) = vs2b(1, 3) + d2_m(jv)*vmb(1, jv, iv)
            d2_mb(jv) = d2_mb(jv) + vs2(1, 3)*vmb(1, jv, iv)
            vs2b(1, 4) = vs2b(1, 4) + u2_m(jv)*vmb(1, jv, iv)
            u2_mb(jv) = u2_mb(jv) + vs2(1, 4)*vmb(1, jv, iv)
            tempb2 = (xi_ule1*ule1_m(jv)+xi_ule2*ule2_m(jv))*vmb(1, jv, &
&             iv)
            tempb0 = (vs1(1, 5)+vs2(1, 5)+vsx(1))*vmb(1, jv, iv)
            vmb(1, jv, iv) = 0.0_8
            xi_ule1b = xi_ule1b + ule1_m(jv)*tempb0
            ule1_mb(jv) = ule1_mb(jv) + xi_ule1*tempb0
            xi_ule2b = xi_ule2b + ule2_m(jv)*tempb0
            ule2_mb(jv) = ule2_mb(jv) + xi_ule2*tempb0
            vs1b(1, 5) = vs1b(1, 5) + tempb2
            vs2b(1, 5) = vs2b(1, 5) + tempb2
            vsxb(1) = vsxb(1) + tempb2
          END DO
          CALL POPINTEGER4(jv)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(xi_ule2)
            sst_gpb = sst_gpb + xi_ule2b
            CALL POPREAL8(xi_ule1)
            sst_gob = sst_gob - xi_ule1b
          ELSE
            CALL POPREAL8(xi_ule2)
            sst_gpb = sst_gpb - xi_ule2b
            CALL POPREAL8(xi_ule1)
            sst_gob = sst_gob + xi_ule1b
          END IF
          u2b = u2b + 2*u2*r2*cf2*0.5*taub(ibl, is)
          tempb2 = u2**2*0.5*taub(ibl, is)
          taub(ibl, is) = 0.0_8
          r2b = r2b + cf2*tempb2
          cf2b = cf2b + r2*tempb2
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            dte_ute1b = (uedg(iblte(1), 1)-usav(iblte(1), 1))*dds1b
            uedgb(iblte(1), 1) = uedgb(iblte(1), 1) + dte_ute1*dds1b
            usavb(iblte(1), 1) = usavb(iblte(1), 1) - dte_ute1*dds1b
            dte_ute2b = (uedg(iblte(2), 2)-usav(iblte(2), 2))*dds1b
            uedgb(iblte(2), 2) = uedgb(iblte(2), 2) + dte_ute2*dds1b
            usavb(iblte(2), 2) = usavb(iblte(2), 2) - dte_ute2*dds1b
            CALL POPREAL8(d1_m(jvte2))
            dte_mte2b = d1_mb(jvte2)
            CALL POPREAL8(d1_m(jvte1))
            dte_mte1b = d1_mb(jvte1)
            DO js=2,1,-1
              CALL POPINTEGER4(ad_to4)
              DO jbl=ad_to4,2,-1
                jv = isys(jbl, js)
                CALL POPREAL8(d1_m(jv))
                dte_ute1b = dte_ute1b + ute1_m(jv)*d1_mb(jv)
                ute1_mb(jv) = ute1_mb(jv) + dte_ute1*d1_mb(jv)
                dte_ute2b = dte_ute2b + ute2_m(jv)*d1_mb(jv)
                ute2_mb(jv) = ute2_mb(jv) + dte_ute2*d1_mb(jv)
                d1_mb(jv) = 0.0_8
              END DO
            END DO
            CALL POPREAL8(cte_tte2)
            tempb2 = cte_tte2b/tte
            ctaub(iblte(2), 2) = ctaub(iblte(2), 2) + tempb2
            cteb = -tempb2
            tteb = -((ctau(iblte(2), 2)-cte)*tempb2/tte)
            CALL POPREAL8(cte_tte1)
            tempb2 = cte_tte1b/tte
            ctaub(iblte(1), 1) = ctaub(iblte(1), 1) + tempb2
            cteb = cteb - tempb2
            tteb = tteb - (ctau(iblte(1), 1)-cte)*tempb2/tte - thet(&
&             iblte(2), 2)*cte_cte2b/tte**2 - thet(iblte(1), 1)*&
&             cte_cte1b/tte**2
            CALL POPREAL8(cte_cte2)
            CALL POPREAL8(cte_cte1)
            CALL POPREAL8(dte_ute2)
            tempb2 = -(dte_ute2b/uedg(iblte(2), 2))
            uedgb(iblte(2), 2) = uedgb(iblte(2), 2) - dstr(iblte(2), 2)*&
&             tempb2/uedg(iblte(2), 2) - dte_mte2b/uedg(iblte(2), 2)**2
            CALL POPREAL8(dte_ute1)
            CALL POPREAL8(tte_tte2)
            CALL POPREAL8(tte_tte1)
            CALL POPREAL8(hk2)
            CALL POPREAL8ARRAY(vs1, 4*5)
            CALL POPREAL8ARRAY(vs2, 4*5)
            CALL POPREAL8(cf2)
            CALL POPREAL8ARRAY(vsm, 4)
            CALL POPREAL8ARRAY(vsr, 4)
            CALL POPREAL8ARRAY(vsx, 4)
            dteb = 0.0_8
            CALL TESYS_B(cte, cteb, tte, tteb, dte, dteb)
            dstrb(iblte(2), 2) = dstrb(iblte(2), 2) + tempb2 + dteb
            tempb2 = -(dte_ute1b/uedg(iblte(1), 1))
            dstrb(iblte(1), 1) = dstrb(iblte(1), 1) + tempb2 + dteb
            uedgb(iblte(1), 1) = uedgb(iblte(1), 1) - dstr(iblte(1), 1)*&
&             tempb2/uedg(iblte(1), 1) - dte_mte1b/uedg(iblte(1), 1)**2
            CALL POPREAL8(cte)
            tempb2 = cteb/tte
            ctaub(iblte(1), 1) = ctaub(iblte(1), 1) + thet(iblte(1), 1)*&
&             tempb2
            ctaub(iblte(2), 2) = ctaub(iblte(2), 2) + thet(iblte(2), 2)*&
&             tempb2
            tteb = tteb - (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(&
&             iblte(2), 2)*thet(iblte(2), 2))*tempb2/tte
            thetb(iblte(2), 2) = thetb(iblte(2), 2) + cte_cte2b/tte + &
&             ctau(iblte(2), 2)*tempb2 + tteb
            thetb(iblte(1), 1) = thetb(iblte(1), 1) + cte_cte1b/tte + &
&             ctau(iblte(1), 1)*tempb2 + tteb
            anteb = anteb + dteb
            CALL POPREAL8(tte)
            rt1_msb = 0.0_8
            hk1_msb = 0.0_8
            di1b = 0.0_8
            u1_msb = 0.0_8
            v1b = 0.0_8
            di1_t1b = 0.0_8
            v1_u1b = 0.0_8
            hk1b = 0.0_8
            di1_d1b = 0.0_8
            hs1_reb = 0.0_8
            s1b = 0.0_8
            cq1_reb = 0.0_8
            us1_u1b = 0.0_8
            hc1_u1b = 0.0_8
            u1_ueib = 0.0_8
            m1_u1b = 0.0_8
            hs1_t1b = 0.0_8
            de1_t1b = 0.0_8
            r1_u1b = 0.0_8
            cf1_u1b = 0.0_8
            cq1_t1b = 0.0_8
            hs1_d1b = 0.0_8
            v1_msb = 0.0_8
            de1_d1b = 0.0_8
            m1b = 0.0_8
            cq1_d1b = 0.0_8
            us1_msb = 0.0_8
            hc1_msb = 0.0_8
            m1_msb = 0.0_8
            dw1b = 0.0_8
            di1_u1b = 0.0_8
            r1_msb = 0.0_8
            cf1_msb = 0.0_8
            rt1_reb = 0.0_8
            t1b = 0.0_8
            d1b = 0.0_8
            cf1b = 0.0_8
            us1b = 0.0_8
            hs1_u1b = 0.0_8
            rt1_t1b = 0.0_8
            hk1_t1b = 0.0_8
            de1_u1b = 0.0_8
            cq1_u1b = 0.0_8
            di1_msb = 0.0_8
            hk1_d1b = 0.0_8
