!*==IBLSYS.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE MRCHUE_B()
    USE M_XBLSYS_DIFF, ONLY : hkin, hkin_b, tesys, tesys_b, trchek, trchek_b, blprv, blprv_b, blkin, blkin_b, &
&      blsys, blsys_b, blvar, blvar_b, blmid, blmid_b
    USE M_XSOLVE_DIFF, ONLY : gauss, gauss_fwd, gauss_bwd
    USE I_XFOIL_DIFF
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
    LOGICAL :: mrchue
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ami, const, cte, cti, dmax, dsi, dsw, dswaki, dte, dummy, &
