&   tsq, tte, ucon, uei, xsi, dummyy
    REAL :: amib, constb, cteb, ctib, dmaxb, dsib, dswb, dswakib, dteb, &
&   htargb, msqb, ratlenb, thib, tsqb, tteb, uconb, ueib, xsib
    LOGICAL :: direct
    INTEGER :: ibl, ibm, icom, is, itbl, iw
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC MAX
    INTRINSIC MIN
    REAL :: x3
    REAL :: x3b
    REAL :: y1
    REAL :: y1b
    REAL :: y2
    REAL :: y2b
    REAL :: y3
    REAL :: y3b
    REAL :: x4
    REAL :: x4b
    REAL :: y4
    REAL :: y4b
