!----------------------------------------------------
!
!---- shape parameters for separation criteria
    hlmax = 3.8
    htmax = 2.5
    CALL PUSHINTEGER4(is)
    CALL PUSHCONTROL1B(0)
!
    DO is=1,2
!
      IF (show_output) WRITE(*, *) '   side ', is, ' ...'
!
      CALL PUSHREAL8(amcrit)
