          CALL PUSHINTEGER4(iw)
          iw = ibl - iblte(is)
          dswaki = wgap(iw)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          dswaki = 0.
        END IF
!
        direct = .true.
        ad_count = 1
!
!------ Newton iteration loop for current station
        DO itbl=1,25
!
!-------- assemble 10x3 linearized system for dCtau, dTh, dDs, dUe, dXi
!         at the previous "1" station and the current "2" station
!         (the "1" station coefficients will be ignored)
!
!
          CALL PUSHREAL8(u2)
          CALL PUSHREAL8(x2)
          CALL PUSHREAL8(d2)
          CALL PUSHREAL8(t2)
          CALL PUSHREAL8(s2)
          CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
          CALL PUSHREAL8(hk2_ms)
          CALL PUSHREAL8(rt2_ms)
          CALL PUSHREAL8(h2_d2)
          CALL PUSHREAL8(hk2_u2)
          CALL PUSHREAL8(rt2_u2)
          CALL PUSHREAL8(h2_t2)
          CALL PUSHREAL8(h2)
          CALL PUSHREAL8(hk2_d2)
          CALL PUSHREAL8(hk2_t2)
          CALL PUSHREAL8(rt2_t2)
          CALL PUSHREAL8(rt2_re)
          CALL PUSHREAL8(m2)
          CALL PUSHREAL8(m2_ms)
          CALL PUSHREAL8(m2_u2)
          CALL PUSHREAL8(rt2)
          CALL BLKIN()
!
!-------- check for transition and set appropriate flags and things
          IF (.NOT.simi .AND. (.NOT.turb)) THEN
            CALL PUSHREAL8(u2_ms)
            CALL PUSHREAL8(hk2_ms)
            CALL PUSHREAL8(rt2_ms)
            CALL PUSHREAL8(xt_xf)
            CALL PUSHREAL8(cq2)
            CALL PUSHREAL8(cf2_d2)
            CALL PUSHREAL8(di2_re)
            CALL PUSHREAL8(cf2_t2)
            CALL PUSHREAL8(ampl2)
            CALL PUSHREAL8(r2)
            CALL PUSHREAL8(hc2_d2)
            CALL PUSHREAL8(us2_d2)
            CALL PUSHREAL8(de2)
            CALL PUSHREAL8(h2_d2)
            CALL PUSHREAL8(hc2_t2)
            CALL PUSHREAL8(us2_t2)
            CALL PUSHREAL8(u2)
            CALL PUSHREAL8(hk2_u2)
            CALL PUSHREAL8(rt2_u2)
            CALL PUSHREAL8(h2_t2)
            CALL PUSHREAL8(cf2_re)
            CALL PUSHREAL8(h2)
            CALL PUSHREAL8(x2)
            CALL PUSHREAL8ARRAY(c2sav, ncom)
            CALL PUSHREAL8(di2_s2)
            CALL PUSHREAL8(us2_re)
            CALL PUSHREAL8(cq2_ms)
            CALL PUSHREAL8(xt_ms)
            CALL PUSHREAL8(de2_ms)
            CALL PUSHREAL8(hc2)
            CALL PUSHREAL8(hs2_ms)
            CALL PUSHREAL8(hs2)
            CALL PUSHREAL8(v2_re)
            CALL PUSHREAL8(us2)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8(hk2_d2)
            CALL PUSHREAL8(d2)
            CALL PUSHREAL8(di2_ms)
            CALL PUSHREAL8(cq2_u2)
            CALL PUSHREAL8(xt_u2)
            CALL PUSHREAL8(de2_u2)
            CALL PUSHREAL8(xt_u1)
            CALL PUSHREAL8(t2)
            CALL PUSHREAL8(hk2_t2)
            CALL PUSHREAL8(rt2_t2)
            CALL PUSHREAL8(hs2_u2)
            CALL PUSHREAL8(xt_x2)
            CALL PUSHREAL8(xt_x1)
            CALL PUSHREAL8(u2_uei)
            CALL PUSHREAL8(dw2)
            CALL PUSHREAL8(xt)
            CALL PUSHREAL8(rt2_re)
            CALL PUSHREAL8(cf2_ms)
            CALL PUSHREAL8(r2_ms)
            CALL PUSHREAL8(di2_u2)
            CALL PUSHREAL8(m2)
            CALL PUSHREAL8(m2_ms)
            CALL PUSHBOOLEAN(tran)
            CALL PUSHREAL8(xt_a1)
            CALL PUSHREAL8(hc2_ms)
            CALL PUSHREAL8(us2_ms)
            CALL PUSHREAL8(cq2_d2)
            CALL PUSHREAL8(xt_d2)
            CALL PUSHREAL8(de2_d2)
            CALL PUSHREAL8(xt_d1)
            CALL PUSHREAL8(hs2_d2)
            CALL PUSHREAL8(v2_ms)
            CALL PUSHREAL8(cq2_t2)
            CALL PUSHREAL8(cf2_u2)
            CALL PUSHREAL8(xt_t2)
            CALL PUSHREAL8(r2_u2)
            CALL PUSHREAL8(de2_t2)
            CALL PUSHREAL8(xt_t1)
            CALL PUSHREAL8(s2)
            CALL PUSHREAL8(hs2_t2)
            CALL PUSHREAL8(m2_u2)
            CALL PUSHREAL8(hk2)
            CALL PUSHREAL8(hc2_u2)
            CALL PUSHREAL8(v2)
            CALL PUSHREAL8(us2_u2)
            CALL PUSHREAL8(cq2_re)
            CALL PUSHREAL8(xt_re)
            CALL PUSHREAL8(di2)
            CALL PUSHREAL8(di2_d2)
            CALL PUSHREAL8(hs2_re)
            CALL PUSHREAL8(v2_u2)
            CALL PUSHREAL8(rt2)
            CALL PUSHREAL8(di2_t2)
            mrchue = TRCHEK()
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (daeps SAVEd by trchek2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
            IF (abort_on_nan .AND. (.NOT.mrchue)) THEN
              GOTO 130
            ELSE
              ami = ampl2
!
              IF (tran) THEN
                CALL PUSHINTEGER4(itran(is))
                itran(is) = ibl
                IF (cti .LE. 0.0) THEN
                  CALL PUSHREAL8(cti)
                  cti = 0.03
                  s2 = cti
                  CALL PUSHCONTROL2B(0)
                ELSE
                  CALL PUSHCONTROL2B(1)
                END IF
              ELSE
                CALL PUSHINTEGER4(itran(is))
                itran(is) = ibl + 2
                CALL PUSHCONTROL2B(2)
              END IF
            END IF
          ELSE
            CALL PUSHCONTROL2B(3)
          END IF
!
!
!
          IF (ibl .EQ. iblte(is) + 1) THEN
            CALL PUSHREAL8(tte)
            tte = thet(iblte(1), 1) + thet(iblte(2), 2)
            dte = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
            cte = (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(iblte(2), 2)&
&             *thet(iblte(2), 2))/tte
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8ARRAY(vsrez, 4)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL TESYS(cte, tte, dte)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(rt1)
            CALL PUSHREAL8(di1_re)
            CALL PUSHREAL8(cf1_d1)
            CALL PUSHREAL8(u2_ms)
            CALL PUSHREAL8(hk2_ms)
            CALL PUSHREAL8(cf1_t1)
            CALL PUSHREAL8(rt2_ms)
            CALL PUSHREAL8(cq1)
            CALL PUSHREAL8(hc1_d1)
            CALL PUSHREAL8(us1_d1)
            CALL PUSHREAL8(h1_d1)
            CALL PUSHREAL8(hc1_t1)
            CALL PUSHREAL8(ampl2)
            CALL PUSHREAL8(us1_t1)
            CALL PUSHREAL8(hk1_u1)
            CALL PUSHREAL8(ampl1)
            CALL PUSHREAL8(rt1_u1)
            CALL PUSHREAL8(r2)
            CALL PUSHREAL8(cf1_re)
            CALL PUSHREAL8(r1)
            CALL PUSHREAL8(h1_t1)
            CALL PUSHREAL8(de1)
            CALL PUSHREAL8(h2_d2)
            CALL PUSHREAL8ARRAY(c1sav, ncom)
            CALL PUSHREAL8(u2)
            CALL PUSHREAL8(hk2_u2)
            CALL PUSHREAL8(di1_s1)
            CALL PUSHREAL8(u1)
            CALL PUSHREAL8(rt2_u2)
            CALL PUSHREAL8(us1_re)
            CALL PUSHREAL8(h2_t2)
            CALL PUSHREAL8(h2)
            CALL PUSHREAL8(cq1_ms)
            CALL PUSHREAL8(h1)
            CALL PUSHREAL8(de1_ms)
            CALL PUSHREAL8(hs1_ms)
            CALL PUSHREAL8(x2)
            CALL PUSHREAL8(x1)
            CALL PUSHREAL8ARRAY(c2sav, ncom)
            CALL PUSHREAL8(v1_re)
            CALL PUSHREAL8(hc1)
            CALL PUSHREAL8(v2_re)
            CALL PUSHREAL8(hs1)
            CALL PUSHREAL8(hk1_d1)
            CALL PUSHREAL8(di1_ms)
            CALL PUSHREAL8(cq1_u1)
            CALL PUSHREAL8(de1_u1)
            CALL PUSHREAL8(hk1_t1)
            CALL PUSHREAL8(rt1_t1)
            CALL PUSHREAL8(hs1_u1)
            CALL PUSHREAL8(us1)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8ARRAY(vsrez, 4)
            CALL PUSHREAL8(hk2_d2)
            CALL PUSHREAL8(d2)
            CALL PUSHREAL8(cf1)
            CALL PUSHREAL8(d1)
            CALL PUSHREAL8(t2)
            CALL PUSHREAL8(hk2_t2)
            CALL PUSHREAL8(t1)
            CALL PUSHREAL8(rt2_t2)
            CALL PUSHREAL8(rt1_re)
            CALL PUSHREAL8(cf1_ms)
            CALL PUSHREAL8(r1_ms)
            CALL PUSHREAL8(u2_uei)
            CALL PUSHREAL8(dw2)
            CALL PUSHREAL8(di1_u1)
            CALL PUSHREAL8(dw1)
            CALL PUSHREAL8(m1_ms)
            CALL PUSHREAL8(hc1_ms)
            CALL PUSHREAL8(us1_ms)
            CALL PUSHREAL8(rt2_re)
            CALL PUSHREAL8(r2_ms)
            CALL PUSHREAL8(m2)
            CALL PUSHREAL8(cq1_d1)
            CALL PUSHREAL8(m2_ms)
            CALL PUSHREAL8(m1)
            CALL PUSHREAL8(de1_d1)
            CALL PUSHREAL8(v1_ms)
            CALL PUSHREAL8(hs1_d1)
            CALL PUSHREAL8(cq1_t1)
            CALL PUSHREAL8(cf1_u1)
            CALL PUSHREAL8(r1_u1)
            CALL PUSHREAL8(de1_t1)
            CALL PUSHREAL8(hs1_t1)
            CALL PUSHREAL8(m1_u1)
            CALL PUSHREAL8(u1_uei)
            CALL PUSHREAL8(v2_ms)
            CALL PUSHREAL8(hc1_u1)
            CALL PUSHREAL8(us1_u1)
            CALL PUSHREAL8(r2_u2)
            CALL PUSHREAL8(s2)
            CALL PUSHREAL8(cq1_re)
            CALL PUSHREAL8(s1)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8ARRAY(vs1, 4*5)
            CALL PUSHREAL8(hs1_re)
            CALL PUSHREAL8(di1_d1)
            CALL PUSHREAL8(m2_u2)
            CALL PUSHREAL8(hk2)
            CALL PUSHREAL8(hk1)
            CALL PUSHREAL8(v2)
            CALL PUSHREAL8(v1_u1)
            CALL PUSHREAL8(di1_t1)
            CALL PUSHREAL8(v1)
            CALL PUSHREAL8(u1_ms)
            CALL PUSHREAL8(di1)
            CALL PUSHREAL8(hk1_ms)
            CALL PUSHREAL8(rt1_ms)
            CALL PUSHREAL8(v2_u2)
            CALL PUSHREAL8(rt2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL BLSYS()
            CALL PUSHCONTROL1B(1)
          END IF
!
          IF (direct) THEN
!
!--------- try direct mode (set dUe = 0 in currently empty 4th line)
            vs2(4, 1) = 0.
            vs2(4, 2) = 0.
            vs2(4, 3) = 0.
            vs2(4, 4) = 1.0
            vsrez(4) = 0.
!
!--------- solve Newton system for current "2" station
            CALL GAUSS_FWD(4, 4, vs2, vsrez, 1)
            IF (vsrez(2)/thi .GE. 0.) THEN
              x3 = vsrez(2)/thi
              CALL PUSHCONTROL1B(0)
            ELSE
              x3 = -(vsrez(2)/thi)
              CALL PUSHCONTROL1B(1)
            END IF
            IF (vsrez(3)/dsi .GE. 0.) THEN
              y1 = vsrez(3)/dsi
              CALL PUSHCONTROL1B(0)
            ELSE
              y1 = -(vsrez(3)/dsi)
              CALL PUSHCONTROL1B(1)
            END IF
            IF (x3 .LT. y1) THEN
              CALL PUSHREAL8(dmax)
              dmax = y1
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(dmax)
              dmax = x3
              CALL PUSHCONTROL1B(1)
            END IF
            IF (ibl .LT. itran(is)) THEN
              IF (vsrez(1)/10.0 .GE. 0.) THEN
                y2 = vsrez(1)/10.0
                CALL PUSHCONTROL1B(0)
              ELSE
                y2 = -(vsrez(1)/10.0)
                CALL PUSHCONTROL1B(1)
              END IF
              IF (dmax .LT. y2) THEN
                dmax = y2
                CALL PUSHCONTROL2B(2)
              ELSE
                dmax = dmax
                CALL PUSHCONTROL2B(1)
              END IF
            ELSE
              CALL PUSHCONTROL2B(0)
            END IF
            IF (ibl .GE. itran(is)) THEN
              IF (vsrez(1)/cti .GE. 0.) THEN
                y3 = vsrez(1)/cti
                CALL PUSHCONTROL1B(0)
              ELSE
                y3 = -(vsrez(1)/cti)
                CALL PUSHCONTROL1B(1)
              END IF
              IF (dmax .LT. y3) THEN
                dmax = y3
                CALL PUSHCONTROL2B(2)
              ELSE
                dmax = dmax
                CALL PUSHCONTROL2B(1)
              END IF
            ELSE
              CALL PUSHCONTROL2B(0)
            END IF
!
            CALL PUSHREAL8(rlx)
            rlx = 1.0
            IF (dmax .GT. 0.3) THEN
              rlx = 0.3/dmax
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
!--------- see if direct mode is not applicable
            IF (ibl .NE. iblte(is) + 1) THEN
!
!---------- calculate resulting kinematic shape parameter Hk
              msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
              htest = (dsi+rlx*vsrez(3))/(thi+rlx*vsrez(2))
              CALL HKIN(htest, msq, hktest, dummy, dummyy)
!
!---------- decide whether to do direct or inverse problem based on Hk
              IF (ibl .LT. itran(is)) hmax = hlmax
              IF (ibl .GE. itran(is)) THEN
                CALL PUSHCONTROL1B(0)
                hmax = htmax
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
              direct = hktest .LT. hmax
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
            IF (direct) THEN
!---------- update as usual
!cc            IF(IBL.LT.ITRAN(IS)) AMI = AMI + RLX*VSREZ(1)
              IF (ibl .GE. itran(is)) THEN
                CALL PUSHREAL8(cti)
                cti = cti + rlx*vsrez(1)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHREAL8(thi)
              thi = thi + rlx*vsrez(2)
              CALL PUSHREAL8(dsi)
              dsi = dsi + rlx*vsrez(3)
              CALL PUSHCONTROL1B(0)
            ELSE
!---------- set prescribed Hk for inverse calculation at the current station
              IF (ibl .LT. itran(is)) THEN
!----------- laminar case: relatively slow increase in Hk downstream
                htarg = hk1 + 0.03*(x2-x1)/t1
                CALL PUSHCONTROL2B(0)
              ELSE IF (ibl .EQ. itran(is)) THEN
!----------- transition interval: weighted laminar and turbulent case
                htarg = hk1 + (0.03*(xt-x1)-0.15*(x2-xt))/t1
                CALL PUSHCONTROL2B(1)
              ELSE IF (wake) THEN
!----------- turbulent wake case:
!-           asymptotic wake behavior with approximate Backward Euler
                const = 0.03*(x2-x1)/t1
                hk2 = hk1
                CALL PUSHREAL8(hk2)
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                CALL PUSHREAL8(hk2)
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                CALL PUSHREAL8(hk2)
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                htarg = hk2
                CALL PUSHCONTROL2B(2)
              ELSE
!----------- turbulent case: relatively fast decrease in Hk downstream
                htarg = hk1 - 0.15*(x2-x1)/t1
                CALL PUSHCONTROL2B(3)
              END IF
!
!---------- limit specified Hk to something reasonable
              IF (wake) THEN
                IF (htarg .LT. 1.01) THEN
                  htarg = 1.01
                  CALL PUSHCONTROL2B(1)
                ELSE
                  CALL PUSHCONTROL2B(0)
                  htarg = htarg
                END IF
              ELSE IF (htarg .LT. hmax) THEN
                htarg = hmax
                CALL PUSHCONTROL2B(3)
              ELSE
                CALL PUSHCONTROL2B(2)
                htarg = htarg
              END IF
!
              IF (show_output) THEN
                CALL PUSHCONTROL2B(1)
                WRITE(*, 99001) ibl, htarg
              ELSE
                CALL PUSHCONTROL2B(0)
              END IF
              GOTO 100
            END IF
          ELSE
!
!---------- try again with prescribed Hk
!
!
!
!-------- inverse mode (force Hk to prescribed value HTARG)
            vs2(4, 1) = 0.
            vs2(4, 2) = hk2_t2
            vs2(4, 3) = hk2_d2
            vs2(4, 4) = hk2_u2
            vsrez(4) = htarg - hk2
!
            CALL GAUSS_FWD(4, 4, vs2, vsrez, 1)
            IF (vsrez(2)/thi .GE. 0.) THEN
              x4 = vsrez(2)/thi
              CALL PUSHCONTROL1B(0)
            ELSE
              x4 = -(vsrez(2)/thi)
              CALL PUSHCONTROL1B(1)
            END IF
            IF (vsrez(3)/dsi .GE. 0.) THEN
              y4 = vsrez(3)/dsi
              CALL PUSHCONTROL1B(0)
            ELSE
              y4 = -(vsrez(3)/dsi)
              CALL PUSHCONTROL1B(1)
            END IF
            IF (vsrez(4)/uei .GE. 0.) THEN
              z1 = vsrez(4)/uei
              CALL PUSHCONTROL1B(0)
            ELSE
              z1 = -(vsrez(4)/uei)
              CALL PUSHCONTROL1B(1)
            END IF
            IF (x4 .LT. y4) THEN
              IF (y4 .LT. z1) THEN
                CALL PUSHREAL8(dmax)
                dmax = z1
                CALL PUSHCONTROL2B(0)
              ELSE
                CALL PUSHREAL8(dmax)
                dmax = y4
                CALL PUSHCONTROL2B(1)
              END IF
            ELSE IF (x4 .LT. z1) THEN
              CALL PUSHREAL8(dmax)
              dmax = z1
              CALL PUSHCONTROL2B(2)
            ELSE
              CALL PUSHREAL8(dmax)
              dmax = x4
              CALL PUSHCONTROL2B(3)
            END IF
            IF (ibl .GE. itran(is)) THEN
              IF (vsrez(1)/cti .GE. 0.) THEN
                y5 = vsrez(1)/cti
                CALL PUSHCONTROL1B(0)
              ELSE
                y5 = -(vsrez(1)/cti)
                CALL PUSHCONTROL1B(1)
              END IF
              IF (dmax .LT. y5) THEN
                dmax = y5
                CALL PUSHCONTROL2B(2)
              ELSE
                dmax = dmax
                CALL PUSHCONTROL2B(1)
              END IF
            ELSE
              CALL PUSHCONTROL2B(0)
            END IF
!
            CALL PUSHREAL8(rlx)
            rlx = 1.0
            IF (dmax .GT. 0.3) THEN
              rlx = 0.3/dmax
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
!--------- update variables
!cc           IF(IBL.LT.ITRAN(IS)) AMI = AMI + RLX*VSREZ(1)
            IF (ibl .GE. itran(is)) THEN
              CALL PUSHREAL8(cti)
              cti = cti + rlx*vsrez(1)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHREAL8(thi)
            thi = thi + rlx*vsrez(2)
            CALL PUSHREAL8(dsi)
            dsi = dsi + rlx*vsrez(3)
            CALL PUSHREAL8(uei)
            uei = uei + rlx*vsrez(4)
!
            CALL PUSHCONTROL1B(1)
          END IF
!
!-------- eliminate absurd transients
          IF (ibl .GE. itran(is)) THEN
            IF (cti .GT. 0.30) THEN
              CALL PUSHREAL8(cti)
              cti = 0.30
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(cti)
              cti = cti
              CALL PUSHCONTROL1B(1)
            END IF
            IF (cti .LT. 0.0000001) THEN
              cti = 0.0000001
              CALL PUSHCONTROL2B(2)
            ELSE
              CALL PUSHCONTROL2B(1)
              cti = cti
            END IF
          ELSE
            CALL PUSHCONTROL2B(0)
          END IF
!
          IF (ibl .LE. iblte(is)) THEN
            CALL PUSHREAL8(hklim)
            hklim = 1.02
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(hklim)
            hklim = 1.00005
            CALL PUSHCONTROL1B(1)
          END IF
          msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
          dsw = dsi - dswaki
          CALL PUSHREAL8(dsw)
          CALL DSLIM(dsw, thi, uei, msq, hklim)
          dsi = dsw + dswaki
!
          IF (dmax .LE. 1.0e-5) THEN
            GOTO 110
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
 100      ad_count = ad_count + 1
        END DO
        CALL PUSHCONTROL2B(0)
        CALL PUSHINTEGER4(ad_count)
!
        IF (show_output) WRITE(*, 99002) ibl, is, dmax
!
!------ the current unconverged solution might still be reasonable...
!CC        IF(DMAX .LE. 0.1) GO TO 110
        IF (dmax .GT. 0.1) THEN
!
!------- the current solution is garbage --> extrapolate values instead
          IF (ibl .GT. 3) THEN
            IF (ibl .LE. iblte(is)) THEN
              CALL PUSHREAL8(thi)
              thi = thet(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              CALL PUSHREAL8(dsi)
              dsi = dstr(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              CALL PUSHCONTROL2B(0)
            ELSE IF (ibl .EQ. iblte(is) + 1) THEN
              CALL PUSHREAL8(cti)
              cti = cte
              CALL PUSHREAL8(thi)
              thi = tte
              CALL PUSHREAL8(dsi)
              dsi = dte
              CALL PUSHCONTROL2B(1)
            ELSE
              CALL PUSHREAL8(thi)
              thi = thet(ibm, is)
              CALL PUSHREAL8(ratlen)
              ratlen = (xssi(ibl, is)-xssi(ibm, is))/(10.0*dstr(ibm, is)&
&               )
              CALL PUSHREAL8(dsi)
              dsi = (dstr(ibm, is)+thi*ratlen)/(1.0+ratlen)
              CALL PUSHCONTROL2B(2)
            END IF
            IF (ibl .EQ. itran(is)) THEN
              CALL PUSHREAL8(cti)
              cti = 0.05
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (ibl .GT. itran(is)) THEN
              CALL PUSHREAL8(cti)
              cti = ctau(ibm, is)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
            CALL PUSHREAL8(uei)
            uei = uedg(ibl, is)
            IF (ibl .GT. 2 .AND. ibl .LT. nbl(is)) THEN
              uei = 0.5*(uedg(ibl-1, is)+uedg(ibl+1, is))
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
        ELSE
          CALL PUSHCONTROL2B(3)
        END IF
!
        CALL PUSHREAL8(u2)
        CALL PUSHREAL8(x2)
        CALL PUSHREAL8(d2)
        CALL PUSHREAL8(t2)
        CALL PUSHREAL8(s2)
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL PUSHREAL8(hk2_ms)
        CALL PUSHREAL8(rt2_ms)
        CALL PUSHREAL8(h2_d2)
        CALL PUSHREAL8(hk2_u2)
        CALL PUSHREAL8(rt2_u2)
        CALL PUSHREAL8(h2_t2)
        CALL PUSHREAL8(h2)
        CALL PUSHREAL8(hk2_d2)
        CALL PUSHREAL8(hk2_t2)
        CALL PUSHREAL8(rt2_t2)
        CALL PUSHREAL8(rt2_re)
        CALL PUSHREAL8(m2)
        CALL PUSHREAL8(m2_ms)
        CALL PUSHREAL8(m2_u2)
        CALL PUSHREAL8(rt2)
        CALL BLKIN()
!
!------- check for transition and set appropriate flags and things
        IF (.NOT.simi .AND. (.NOT.turb)) THEN
          CALL PUSHREAL8(u2_ms)
          CALL PUSHREAL8(hk2_ms)
          CALL PUSHREAL8(rt2_ms)
          CALL PUSHREAL8(xt_xf)
          CALL PUSHREAL8(cq2)
          CALL PUSHREAL8(cf2_d2)
          CALL PUSHREAL8(di2_re)
          CALL PUSHREAL8(cf2_t2)
          CALL PUSHREAL8(ampl2)
          CALL PUSHREAL8(r2)
          CALL PUSHREAL8(hc2_d2)
          CALL PUSHREAL8(us2_d2)
          CALL PUSHREAL8(de2)
          CALL PUSHREAL8(h2_d2)
          CALL PUSHREAL8(hc2_t2)
          CALL PUSHREAL8(us2_t2)
          CALL PUSHREAL8(u2)
          CALL PUSHREAL8(hk2_u2)
          CALL PUSHREAL8(rt2_u2)
          CALL PUSHREAL8(h2_t2)
          CALL PUSHREAL8(cf2_re)
          CALL PUSHREAL8(h2)
          CALL PUSHREAL8(x2)
          CALL PUSHREAL8ARRAY(c2sav, ncom)
          CALL PUSHREAL8(di2_s2)
          CALL PUSHREAL8(us2_re)
          CALL PUSHREAL8(cq2_ms)
          CALL PUSHREAL8(xt_ms)
          CALL PUSHREAL8(de2_ms)
          CALL PUSHREAL8(hc2)
          CALL PUSHREAL8(hs2_ms)
          CALL PUSHREAL8(hs2)
          CALL PUSHREAL8(v2_re)
          CALL PUSHREAL8(us2)
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2_d2)
          CALL PUSHREAL8(d2)
          CALL PUSHREAL8(di2_ms)
          CALL PUSHREAL8(cq2_u2)
          CALL PUSHREAL8(xt_u2)
          CALL PUSHREAL8(de2_u2)
          CALL PUSHREAL8(xt_u1)
          CALL PUSHREAL8(t2)
          CALL PUSHREAL8(hk2_t2)
          CALL PUSHREAL8(rt2_t2)
          CALL PUSHREAL8(hs2_u2)
          CALL PUSHREAL8(xt_x2)
          CALL PUSHREAL8(xt_x1)
          CALL PUSHREAL8(u2_uei)
          CALL PUSHREAL8(dw2)
          CALL PUSHREAL8(xt)
          CALL PUSHREAL8(rt2_re)
          CALL PUSHREAL8(cf2_ms)
          CALL PUSHREAL8(r2_ms)
          CALL PUSHREAL8(di2_u2)
          CALL PUSHREAL8(m2)
          CALL PUSHREAL8(m2_ms)
          CALL PUSHBOOLEAN(tran)
          CALL PUSHREAL8(xt_a1)
          CALL PUSHREAL8(hc2_ms)
          CALL PUSHREAL8(us2_ms)
          CALL PUSHREAL8(cq2_d2)
          CALL PUSHREAL8(xt_d2)
          CALL PUSHREAL8(de2_d2)
          CALL PUSHREAL8(xt_d1)
          CALL PUSHREAL8(hs2_d2)
          CALL PUSHREAL8(v2_ms)
          CALL PUSHREAL8(cq2_t2)
          CALL PUSHREAL8(cf2_u2)
          CALL PUSHREAL8(xt_t2)
          CALL PUSHREAL8(r2_u2)
          CALL PUSHREAL8(de2_t2)
          CALL PUSHREAL8(xt_t1)
          CALL PUSHREAL8(s2)
          CALL PUSHREAL8(hs2_t2)
          CALL PUSHREAL8(m2_u2)
          CALL PUSHREAL8(hk2)
          CALL PUSHREAL8(hc2_u2)
          CALL PUSHREAL8(v2)
          CALL PUSHREAL8(us2_u2)
          CALL PUSHREAL8(cq2_re)
          CALL PUSHREAL8(xt_re)
          CALL PUSHREAL8(di2)
          CALL PUSHREAL8(di2_d2)
          CALL PUSHREAL8(hs2_re)
          CALL PUSHREAL8(v2_u2)
          CALL PUSHREAL8(rt2)
          CALL PUSHREAL8(di2_t2)
          mrchue = TRCHEK()
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (daeps SAVEd by trchek2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
          IF (abort_on_nan .AND. (.NOT.mrchue)) THEN
            GOTO 120
          ELSE
            ami = ampl2
            IF (tran) THEN
              CALL PUSHINTEGER4(itran(is))
              itran(is) = ibl
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (.NOT.tran) THEN
              CALL PUSHINTEGER4(itran(is))
              itran(is) = ibl + 2
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          END IF
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
!
!------- set all other extrapolated values for current station
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(1)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (wake) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(3)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
!
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(1)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (wake) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(3)
          CALL PUSHCONTROL2B(1)
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
        GOTO 20
 110    CALL PUSHCONTROL2B(2)
        CALL PUSHINTEGER4(ad_count)
        CALL PUSHCONTROL2B(0)
!
!------ pick up here after the Newton iterations
!
!------ store primary variables
 20     IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(ctau(ibl, is))
          ctau(ibl, is) = ami
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(ctau(ibl, is))
          ctau(ibl, is) = cti
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(thet(ibl, is))
        thet(ibl, is) = thi
        CALL PUSHREAL8(dstr(ibl, is))
        dstr(ibl, is) = dsi
        CALL PUSHREAL8(uedg(ibl, is))
        uedg(ibl, is) = uei
!
!------ set "1" variables to "2" variables for next streamwise station
        CALL PUSHREAL8(u2)
        CALL PUSHREAL8(d2)
        CALL PUSHREAL8(t2)
        CALL PUSHREAL8(s2)
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL PUSHREAL8(hk2_ms)
        CALL PUSHREAL8(rt2_ms)
        CALL PUSHREAL8(r2)
        CALL PUSHREAL8(h2_d2)
        CALL PUSHREAL8(hk2_u2)
        CALL PUSHREAL8(rt2_u2)
        CALL PUSHREAL8(h2_t2)
        CALL PUSHREAL8(h2)
        CALL PUSHREAL8(hk2_d2)
        CALL PUSHREAL8(hk2_t2)
        CALL PUSHREAL8(rt2_t2)
        CALL PUSHREAL8(rt2_re)
        CALL PUSHREAL8(m2)
        CALL PUSHREAL8(m2_ms)
        CALL PUSHREAL8(m2_u2)
        CALL PUSHREAL8(rt2)
        CALL BLKIN()
        CALL PUSHREAL8(rt1)
        CALL PUSHREAL8(hk1_u1)
        CALL PUSHREAL8(ampl1)
        CALL PUSHREAL8(rt1_u1)
        CALL PUSHREAL8(u1)
        CALL PUSHREAL8(x1)
        CALL PUSHREAL8(hk1_d1)
        CALL PUSHREAL8(hk1_t1)
        CALL PUSHREAL8(rt1_t1)
        CALL PUSHREAL8(d1)
        CALL PUSHREAL8(t1)
        CALL PUSHREAL8(rt1_re)
        CALL PUSHREAL8(hk1)
        CALL PUSHREAL8(hk1_ms)
        CALL PUSHREAL8(rt1_ms)
        CALL BLC_1FROM2()
!
!------ turbulent intervals will follow transition interval or TE
        IF (tran .OR. ibl .EQ. iblte(is)) THEN
          CALL PUSHBOOLEAN(turb)
          turb = .true.
!
!------- save transition location
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
!
        CALL PUSHBOOLEAN(tran)
        tran = .false.
!
        IF (ibl .EQ. iblte(is)) THEN
          CALL PUSHREAL8(thi)
          thi = thet(iblte(1), 1) + thet(iblte(2), 2)
          CALL PUSHREAL8(dsi)
          dsi = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        CALL PUSHINTEGER4(ibl)
        ad_count0 = ad_count0 + 1
      END DO
      CALL PUSHCONTROL2B(0)
      CALL PUSHINTEGER4(ad_count0)
      CALL PUSHINTEGER4(is)
      CALL PUSHCONTROL1B(1)
    END DO
    cteb = 0.0_8
    tteb = 0.0_8
    htargb = 0.0_8
    dteb = 0.0_8
    GOTO 240
 120 CALL PUSHCONTROL2B(2)
    CALL PUSHINTEGER4(ad_count0)
    GOTO 140
 130 CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count0)
 140 CALL POPINTEGER4(ad_count0)
    DO i0=1,ad_count0
      IF (i0 .EQ. 1) THEN
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          xiforcb = 0.0_8
          amcritb = 0.0_8
          amib = 0.0_8
          thib = 0.0_8
          ctib = 0.0_8
          dsib = 0.0_8
          GOTO 230
        ELSE IF (branch .EQ. 1) THEN
          rt2b = 0.0_8
          v2_u2b = 0.0_8
          v2b = 0.0_8
          hk2b = 0.0_8
          m2_u2b = 0.0_8
          xiforcb = 0.0_8
          s2b = 0.0_8
          r2_u2b = 0.0_8
          v2_msb = 0.0_8
          m2_msb = 0.0_8
          m2b = 0.0_8
          r2_msb = 0.0_8
          rt2_reb = 0.0_8
          dw2b = 0.0_8
          u2_ueib = 0.0_8
          rt2_t2b = 0.0_8
          hk2_t2b = 0.0_8
          t2b = 0.0_8
          d2b = 0.0_8
          hk2_d2b = 0.0_8
          v2_reb = 0.0_8
          x2b = 0.0_8
          amcritb = 0.0_8
          h2b = 0.0_8
          h2_t2b = 0.0_8
          rt2_u2b = 0.0_8
          hk2_u2b = 0.0_8
          u2b = 0.0_8
          h2_d2b = 0.0_8
          r2b = 0.0_8
          ampl2b = 0.0_8
          rt2_msb = 0.0_8
          hk2_msb = 0.0_8
          u2_msb = 0.0_8
          thib = 0.0_8
          cteb = 0.0_8
          ctib = 0.0_8
          dsib = 0.0_8
          ueib = 0.0_8
          tteb = 0.0_8
          dswakib = 0.0_8
          xsib = 0.0_8
          htargb = 0.0_8
          dteb = 0.0_8
          GOTO 160
        ELSE
          rt2b = 0.0_8
          hk2b = 0.0_8
          m2_u2b = 0.0_8
          xiforcb = 0.0_8
          s2b = 0.0_8
          m2_msb = 0.0_8
          m2b = 0.0_8
          rt2_reb = 0.0_8
          rt2_t2b = 0.0_8
          hk2_t2b = 0.0_8
          t2b = 0.0_8
          d2b = 0.0_8
          hk2_d2b = 0.0_8
          amcritb = 0.0_8
          h2b = 0.0_8
          h2_t2b = 0.0_8
          rt2_u2b = 0.0_8
          hk2_u2b = 0.0_8
          u2b = 0.0_8
          h2_d2b = 0.0_8
          r2b = 0.0_8
          ampl2b = 0.0_8
          rt2_msb = 0.0_8
          hk2_msb = 0.0_8
          thib = 0.0_8
          cteb = 0.0_8
          ctib = 0.0_8
          dsib = 0.0_8
          ueib = 0.0_8
          tteb = 0.0_8
          dswakib = 0.0_8
          xsib = 0.0_8
          htargb = 0.0_8
          dteb = 0.0_8
        END IF
      ELSE
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPREAL8(dsi)
          dstrb(iblte(1), 1) = dstrb(iblte(1), 1) + dsib
          dstrb(iblte(2), 2) = dstrb(iblte(2), 2) + dsib
          anteb = anteb + dsib
          CALL POPREAL8(thi)
          thetb(iblte(1), 1) = thetb(iblte(1), 1) + thib
          thetb(iblte(2), 2) = thetb(iblte(2), 2) + thib
          thib = 0.0_8
          dsib = 0.0_8
        END IF
        CALL POPBOOLEAN(tran)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) CALL POPBOOLEAN(turb)
        CALL POPREAL8(rt1_ms)
        CALL POPREAL8(hk1_ms)
        CALL POPREAL8(hk1)
        CALL POPREAL8(rt1_re)
        CALL POPREAL8(t1)
        CALL POPREAL8(d1)
        CALL POPREAL8(rt1_t1)
        CALL POPREAL8(hk1_t1)
        CALL POPREAL8(hk1_d1)
        CALL POPREAL8(x1)
        CALL POPREAL8(u1)
        CALL POPREAL8(rt1_u1)
        CALL POPREAL8(ampl1)
        CALL POPREAL8(hk1_u1)
        CALL POPREAL8(rt1)
        u2_msb = 0.0_8
        hk2_msb = 0.0_8
        rt2_msb = 0.0_8
        ampl2b = 0.0_8
        r2b = 0.0_8
        h2_d2b = 0.0_8
        u2b = 0.0_8
        hk2_u2b = 0.0_8
        rt2_u2b = 0.0_8
        h2_t2b = 0.0_8
        h2b = 0.0_8
        x2b = 0.0_8
        v2_reb = 0.0_8
        hk2_d2b = 0.0_8
        d2b = 0.0_8
        t2b = 0.0_8
        hk2_t2b = 0.0_8
        rt2_t2b = 0.0_8
        u2_ueib = 0.0_8
        dw2b = 0.0_8
        rt2_reb = 0.0_8
        r2_msb = 0.0_8
        m2b = 0.0_8
        m2_msb = 0.0_8
        v2_msb = 0.0_8
        r2_u2b = 0.0_8
        s2b = 0.0_8
        m2_u2b = 0.0_8
        hk2b = 0.0_8
        v2b = 0.0_8
        v2_u2b = 0.0_8
        rt2b = 0.0_8
        CALL BLC_1FROM2_B()
        CALL POPREAL8(rt2)
        CALL POPREAL8(m2_u2)
        CALL POPREAL8(m2_ms)
        CALL POPREAL8(m2)
        CALL POPREAL8(rt2_re)
        CALL POPREAL8(rt2_t2)
        CALL POPREAL8(hk2_t2)
        CALL POPREAL8(hk2_d2)
        CALL POPREAL8(h2)
        CALL POPREAL8(h2_t2)
        CALL POPREAL8(rt2_u2)
        CALL POPREAL8(hk2_u2)
        CALL POPREAL8(h2_d2)
        CALL POPREAL8(r2)
        CALL POPREAL8(rt2_ms)
        CALL POPREAL8(hk2_ms)
        CALL BLKIN_B()
        CALL POPREAL8(s2)
        CALL POPREAL8(t2)
        CALL POPREAL8(d2)
        CALL POPREAL8(u2)
        xsib = 0.0_8
        dswakib = 0.0_8
        ueib = 0.0_8
