  FUNCTION MRCHUE()
    USE M_XBLSYS_DIFF, ONLY : hkin, tesys, trchek, blprv, blkin, blsys, blvar, blmid
    USE M_XSOLVE_DIFF, ONLY : gauss
    USE I_XFOIL_DIFF
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
    LOGICAL :: mrchue
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ami, const, cte, cti, dmax, dsi, dsw, dswaki, dte, dummy, &
&   hklim, hktest, hlmax, hmax, htarg, htest, htmax, msq, ratlen, thi, &
&   tsq, tte, ucon, uei, xsi, dummyy
    LOGICAL :: direct
    INTEGER :: ibl, ibm, icom, is, itbl, iw
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC MAX
    INTRINSIC MIN
    REAL :: x3
    REAL :: y1
    REAL :: y2
    REAL :: y3
    REAL :: x4
    REAL :: y4
    REAL :: z1
    REAL :: y5
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!----------------------------------------------------
!     Marches the BLs and wake in direct mode using
!     the UEDG array. If separation is encountered,
!     a plausible value of Hk extrapolated from
!     upstream is prescribed instead.  Continuous
!     checking of transition onset is performed.
!----------------------------------------------------
!
    mrchue = .true.
!---- shape parameters for separation criteria
    hlmax = 3.8
    htmax = 2.5
!
    DO is=1,2
!
      IF (show_output) WRITE(*, *) '   side ', is, ' ...'
!
      amcrit = acrit(is)
!
!---- set forced transition arc length position
      CALL XIFSET(is)
!
!---- initialize similarity station with Thwaites' formula
      ibl = 2
      xsi = xssi(ibl, is)
      uei = uedg(ibl, is)
!      BULE = LOG(UEDG(IBL+1,IS)/UEI) / LOG(XSSI(IBL+1,IS)/XSI)
!      BULE = MAX( -.08 , BULE )
      bule = 1.0
      ucon = uei/xsi**bule
      tsq = 0.45/(ucon*(5.0*bule+1.0)*reybl)*xsi**(1.0-bule)
      thi = SQRT(tsq)
      dsi = 2.2*thi
      ami = 0.0
!
!---- initialize Ctau for first turbulent station
      cti = 0.03
!
      tran = .false.
      turb = .false.
      itran(is) = iblte(is)
!
!---- march downstream
      DO ibl=2,nbl(is)
        ibm = ibl - 1
!
        iw = ibl - iblte(is)
!
        simi = ibl .EQ. 2
        wake = ibl .GT. iblte(is)
!
!------ prescribed quantities
        xsi = xssi(ibl, is)
        uei = uedg(ibl, is)
!
        IF (wake) THEN
          iw = ibl - iblte(is)
          dswaki = wgap(iw)
        ELSE
          dswaki = 0.
        END IF
!
        direct = .true.
!
!------ Newton iteration loop for current station
        DO 100 itbl=1,25
!
!-------- assemble 10x3 linearized system for dCtau, dTh, dDs, dUe, dXi
!         at the previous "1" station and the current "2" station
!         (the "1" station coefficients will be ignored)
!
!
          CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
          CALL BLKIN()
!
!-------- check for transition and set appropriate flags and things
          IF (.NOT.simi .AND. (.NOT.turb)) THEN
            mrchue = TRCHEK()
            IF (abort_on_nan .AND. (.NOT.mrchue)) THEN
              RETURN
            ELSE
              ami = ampl2
!
              IF (tran) THEN
                itran(is) = ibl
                IF (cti .LE. 0.0) THEN
                  cti = 0.03
                  s2 = cti
                END IF
              ELSE
                itran(is) = ibl + 2
              END IF
            END IF
          END IF
!
!
!
          IF (ibl .EQ. iblte(is) + 1) THEN
            tte = thet(iblte(1), 1) + thet(iblte(2), 2)
            dte = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
            cte = (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(iblte(2), 2)&
&             *thet(iblte(2), 2))/tte
            CALL TESYS(cte, tte, dte)
          ELSE
            CALL BLSYS()
          END IF
!
          IF (direct) THEN
!
!--------- try direct mode (set dUe = 0 in currently empty 4th line)
            vs2(4, 1) = 0.
            vs2(4, 2) = 0.
            vs2(4, 3) = 0.
            vs2(4, 4) = 1.0
            vsrez(4) = 0.
!
!--------- solve Newton system for current "2" station
            CALL GAUSS(4, 4, vs2, vsrez, 1)
            IF (vsrez(2)/thi .GE. 0.) THEN
              x3 = vsrez(2)/thi
            ELSE
              x3 = -(vsrez(2)/thi)
            END IF
            IF (vsrez(3)/dsi .GE. 0.) THEN
              y1 = vsrez(3)/dsi
            ELSE
              y1 = -(vsrez(3)/dsi)
            END IF
            IF (x3 .LT. y1) THEN
              dmax = y1
            ELSE
              dmax = x3
            END IF
            IF (ibl .LT. itran(is)) THEN
              IF (vsrez(1)/10.0 .GE. 0.) THEN
                y2 = vsrez(1)/10.0
              ELSE
                y2 = -(vsrez(1)/10.0)
              END IF
              IF (dmax .LT. y2) THEN
                dmax = y2
              ELSE
                dmax = dmax
              END IF
            END IF
            IF (ibl .GE. itran(is)) THEN
              IF (vsrez(1)/cti .GE. 0.) THEN
                y3 = vsrez(1)/cti
              ELSE
                y3 = -(vsrez(1)/cti)
              END IF
              IF (dmax .LT. y3) THEN
                dmax = y3
              ELSE
                dmax = dmax
              END IF
            END IF
!
            rlx = 1.0
            IF (dmax .GT. 0.3) rlx = 0.3/dmax
!
!--------- see if direct mode is not applicable
            IF (ibl .NE. iblte(is) + 1) THEN
!
!---------- calculate resulting kinematic shape parameter Hk
              msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
              htest = (dsi+rlx*vsrez(3))/(thi+rlx*vsrez(2))
              CALL HKIN(htest, msq, hktest, dummy, dummyy)
!
!---------- decide whether to do direct or inverse problem based on Hk
              IF (ibl .LT. itran(is)) hmax = hlmax
              IF (ibl .GE. itran(is)) hmax = htmax
              direct = hktest .LT. hmax
            END IF
!
            IF (direct) THEN
!---------- update as usual
!cc            IF(IBL.LT.ITRAN(IS)) AMI = AMI + RLX*VSREZ(1)
              IF (ibl .GE. itran(is)) cti = cti + rlx*vsrez(1)
              thi = thi + rlx*vsrez(2)
              dsi = dsi + rlx*vsrez(3)
            ELSE
!---------- set prescribed Hk for inverse calculation at the current station
              IF (ibl .LT. itran(is)) THEN
!----------- laminar case: relatively slow increase in Hk downstream
                htarg = hk1 + 0.03*(x2-x1)/t1
              ELSE IF (ibl .EQ. itran(is)) THEN
!----------- transition interval: weighted laminar and turbulent case
                htarg = hk1 + (0.03*(xt-x1)-0.15*(x2-xt))/t1
              ELSE IF (wake) THEN
!----------- turbulent wake case:
!-           asymptotic wake behavior with approximate Backward Euler
                const = 0.03*(x2-x1)/t1
                hk2 = hk1
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                hk2 = hk2 - (hk2+const*(hk2-1.0)**3-hk1)/(1.0+3.0*const*&
&                 (hk2-1.0)**2)
                htarg = hk2
              ELSE
!----------- turbulent case: relatively fast decrease in Hk downstream
                htarg = hk1 - 0.15*(x2-x1)/t1
              END IF
!
!---------- limit specified Hk to something reasonable
              IF (wake) THEN
                IF (htarg .LT. 1.01) THEN
                  htarg = 1.01
                ELSE
                  htarg = htarg
                END IF
              ELSE IF (htarg .LT. hmax) THEN
                htarg = hmax
              ELSE
                htarg = htarg
              END IF
!
              IF (show_output) WRITE(*, 99001) ibl, htarg
              GOTO 100
            END IF
          ELSE
!
!---------- try again with prescribed Hk
!
!
!
!-------- inverse mode (force Hk to prescribed value HTARG)
            vs2(4, 1) = 0.
            vs2(4, 2) = hk2_t2
            vs2(4, 3) = hk2_d2
            vs2(4, 4) = hk2_u2
            vsrez(4) = htarg - hk2
!
            CALL GAUSS(4, 4, vs2, vsrez, 1)
            IF (vsrez(2)/thi .GE. 0.) THEN
              x4 = vsrez(2)/thi
            ELSE
              x4 = -(vsrez(2)/thi)
            END IF
            IF (vsrez(3)/dsi .GE. 0.) THEN
              y4 = vsrez(3)/dsi
            ELSE
              y4 = -(vsrez(3)/dsi)
            END IF
            IF (vsrez(4)/uei .GE. 0.) THEN
              z1 = vsrez(4)/uei
            ELSE
              z1 = -(vsrez(4)/uei)
            END IF
            IF (x4 .LT. y4) THEN
              IF (y4 .LT. z1) THEN
                dmax = z1
              ELSE
                dmax = y4
              END IF
            ELSE IF (x4 .LT. z1) THEN
              dmax = z1
            ELSE
              dmax = x4
            END IF
            IF (ibl .GE. itran(is)) THEN
              IF (vsrez(1)/cti .GE. 0.) THEN
                y5 = vsrez(1)/cti
              ELSE
                y5 = -(vsrez(1)/cti)
              END IF
              IF (dmax .LT. y5) THEN
                dmax = y5
              ELSE
                dmax = dmax
              END IF
            END IF
!
            rlx = 1.0
            IF (dmax .GT. 0.3) rlx = 0.3/dmax
!
!--------- update variables
!cc           IF(IBL.LT.ITRAN(IS)) AMI = AMI + RLX*VSREZ(1)
            IF (ibl .GE. itran(is)) cti = cti + rlx*vsrez(1)
            thi = thi + rlx*vsrez(2)
            dsi = dsi + rlx*vsrez(3)
            uei = uei + rlx*vsrez(4)
!
          END IF
!
!-------- eliminate absurd transients
          IF (ibl .GE. itran(is)) THEN
            IF (cti .GT. 0.30) THEN
              cti = 0.30
            ELSE
              cti = cti
            END IF
            IF (cti .LT. 0.0000001) THEN
              cti = 0.0000001
            ELSE
              cti = cti
            END IF
          END IF
!
          IF (ibl .LE. iblte(is)) THEN
            hklim = 1.02
          ELSE
            hklim = 1.00005
          END IF
          msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
          dsw = dsi - dswaki
          CALL DSLIM(dsw, thi, uei, msq, hklim)
          dsi = dsw + dswaki
!
          IF (dmax .LE. 1.0e-5) GOTO 20
 100    CONTINUE
!
        IF (show_output) WRITE(*, 99002) ibl, is, dmax
!
!------ the current unconverged solution might still be reasonable...
!CC        IF(DMAX .LE. 0.1) GO TO 110
        IF (dmax .GT. 0.1) THEN
!
!------- the current solution is garbage --> extrapolate values instead
          IF (ibl .GT. 3) THEN
            IF (ibl .LE. iblte(is)) THEN
              thi = thet(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              dsi = dstr(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
            ELSE IF (ibl .EQ. iblte(is) + 1) THEN
              cti = cte
              thi = tte
              dsi = dte
            ELSE
              thi = thet(ibm, is)
              ratlen = (xssi(ibl, is)-xssi(ibm, is))/(10.0*dstr(ibm, is)&
&               )
              dsi = (dstr(ibm, is)+thi*ratlen)/(1.0+ratlen)
            END IF
            IF (ibl .EQ. itran(is)) cti = 0.05
            IF (ibl .GT. itran(is)) cti = ctau(ibm, is)
!
            uei = uedg(ibl, is)
            IF (ibl .GT. 2 .AND. ibl .LT. nbl(is)) uei = 0.5*(uedg(ibl-1&
&               , is)+uedg(ibl+1, is))
          END IF
        END IF
!
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL BLKIN()
!
!------- check for transition and set appropriate flags and things
        IF (.NOT.simi .AND. (.NOT.turb)) THEN
          mrchue = TRCHEK()
          IF (abort_on_nan .AND. (.NOT.mrchue)) THEN
            RETURN
          ELSE
            ami = ampl2
            IF (tran) itran(is) = ibl
            IF (.NOT.tran) itran(is) = ibl + 2
          END IF
        END IF
!
!------- set all other extrapolated values for current station
        IF (ibl .LT. itran(is)) CALL BLVAR(1)
        IF (ibl .GE. itran(is)) CALL BLVAR(2)
        IF (wake) CALL BLVAR(3)
!
        IF (ibl .LT. itran(is)) CALL BLMID(1)
        IF (ibl .GE. itran(is)) CALL BLMID(2)
        IF (wake) CALL BLMID(3)
!
!------ pick up here after the Newton iterations
!
!------ store primary variables
 20     IF (ibl .LT. itran(is)) ctau(ibl, is) = ami
        IF (ibl .GE. itran(is)) ctau(ibl, is) = cti
        thet(ibl, is) = thi
        dstr(ibl, is) = dsi
        uedg(ibl, is) = uei
        mass(ibl, is) = dsi*uei
        tau(ibl, is) = 0.5*r2*u2*u2*cf2
        dis(ibl, is) = r2*u2*u2*u2*di2*hs2*0.5
        ctq(ibl, is) = cq2
        delt(ibl, is) = de2
        tstr(ibl, is) = hs2*t2
!
!------ set "1" variables to "2" variables for next streamwise station
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL BLKIN()
        CALL BLC_1FROM2()
!
!------ turbulent intervals will follow transition interval or TE
        IF (tran .OR. ibl .EQ. iblte(is)) THEN
          turb = .true.
!
!------- save transition location
          tforce(is) = trforc
          xssitr(is) = xt
        END IF
!
        tran = .false.
!
        IF (ibl .EQ. iblte(is)) THEN
          thi = thet(iblte(1), 1) + thet(iblte(2), 2)
          dsi = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
        END IF
      END DO
    END DO
99001 FORMAT(' MRCHUE: Inverse mode at', i4, '     Hk =', f8.3)
99002 FORMAT(' MRCHUE: Convergence failed at', i4, '  side', i2, &
&          '    Res =', e12.4)
  END FUNCTION MRCHUE

