            tte = thet(iblte(1), 1) + thet(iblte(2), 2)
            dte = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
            cte = (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(iblte(2), 2)&
&             *thet(iblte(2), 2))/tte
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8ARRAY(vsrez, 4)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to tesys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL TESYS(cte, tte, dte)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(rt1)
            CALL PUSHREAL8(di1_re)
            CALL PUSHREAL8(cf1_d1)
            CALL PUSHREAL8(u2_ms)
            CALL PUSHREAL8(hk2_ms)
            CALL PUSHREAL8(cf1_t1)
            CALL PUSHREAL8(rt2_ms)
            CALL PUSHREAL8(cq1)
            CALL PUSHREAL8(hc1_d1)
            CALL PUSHREAL8(us1_d1)
            CALL PUSHREAL8(h1_d1)
            CALL PUSHREAL8(hc1_t1)
            CALL PUSHREAL8(ampl2)
            CALL PUSHREAL8(us1_t1)
            CALL PUSHREAL8(hk1_u1)
            CALL PUSHREAL8(ampl1)
            CALL PUSHREAL8(rt1_u1)
            CALL PUSHREAL8(r2)
            CALL PUSHREAL8(cf1_re)
            CALL PUSHREAL8(r1)
            CALL PUSHREAL8(h1_t1)
            CALL PUSHREAL8(de1)
            CALL PUSHREAL8(h2_d2)
            CALL PUSHREAL8ARRAY(c1sav, ncom)
            CALL PUSHREAL8(u2)
            CALL PUSHREAL8(hk2_u2)
            CALL PUSHREAL8(di1_s1)
            CALL PUSHREAL8(u1)
            CALL PUSHREAL8(rt2_u2)
            CALL PUSHREAL8(us1_re)
            CALL PUSHREAL8(h2_t2)
            CALL PUSHREAL8(h2)
            CALL PUSHREAL8(cq1_ms)
            CALL PUSHREAL8(h1)
            CALL PUSHREAL8(de1_ms)
            CALL PUSHREAL8(hs1_ms)
            CALL PUSHREAL8(x2)
            CALL PUSHREAL8(x1)
            CALL PUSHREAL8ARRAY(c2sav, ncom)
            CALL PUSHREAL8(v1_re)
            CALL PUSHREAL8(hc1)
            CALL PUSHREAL8(v2_re)
            CALL PUSHREAL8(hs1)
            CALL PUSHREAL8(hk1_d1)
            CALL PUSHREAL8(di1_ms)
            CALL PUSHREAL8(cq1_u1)
            CALL PUSHREAL8(de1_u1)
            CALL PUSHREAL8(hk1_t1)
            CALL PUSHREAL8(rt1_t1)
            CALL PUSHREAL8(hs1_u1)
            CALL PUSHREAL8(us1)
            CALL PUSHREAL8(cf2)
            CALL PUSHREAL8ARRAY(vsrez, 4)
            CALL PUSHREAL8(hk2_d2)
            CALL PUSHREAL8(d2)
            CALL PUSHREAL8(cf1)
            CALL PUSHREAL8(d1)
            CALL PUSHREAL8(t2)
            CALL PUSHREAL8(hk2_t2)
            CALL PUSHREAL8(t1)
            CALL PUSHREAL8(rt2_t2)
            CALL PUSHREAL8(rt1_re)
            CALL PUSHREAL8(cf1_ms)
            CALL PUSHREAL8(r1_ms)
            CALL PUSHREAL8(u2_uei)
            CALL PUSHREAL8(dw2)
            CALL PUSHREAL8(di1_u1)
            CALL PUSHREAL8(dw1)
            CALL PUSHREAL8(m1_ms)
            CALL PUSHREAL8(hc1_ms)
            CALL PUSHREAL8(us1_ms)
            CALL PUSHREAL8(rt2_re)
            CALL PUSHREAL8(r2_ms)
            CALL PUSHREAL8(m2)
            CALL PUSHREAL8(cq1_d1)
            CALL PUSHREAL8(m2_ms)
            CALL PUSHREAL8(m1)
            CALL PUSHREAL8(de1_d1)
            CALL PUSHREAL8(v1_ms)
            CALL PUSHREAL8(hs1_d1)
            CALL PUSHREAL8(cq1_t1)
            CALL PUSHREAL8(cf1_u1)
            CALL PUSHREAL8(r1_u1)
            CALL PUSHREAL8(de1_t1)
            CALL PUSHREAL8(hs1_t1)
            CALL PUSHREAL8(m1_u1)
            CALL PUSHREAL8(u1_uei)
            CALL PUSHREAL8(v2_ms)
            CALL PUSHREAL8(hc1_u1)
            CALL PUSHREAL8(us1_u1)
            CALL PUSHREAL8(r2_u2)
            CALL PUSHREAL8(s2)
            CALL PUSHREAL8(cq1_re)
            CALL PUSHREAL8(s1)
            CALL PUSHREAL8ARRAY(vs2, 4*5)
            CALL PUSHREAL8ARRAY(vs1, 4*5)
            CALL PUSHREAL8(hs1_re)
            CALL PUSHREAL8(di1_d1)
            CALL PUSHREAL8(m2_u2)
            CALL PUSHREAL8(hk2)
            CALL PUSHREAL8(hk1)
            CALL PUSHREAL8(v2)
            CALL PUSHREAL8(v1_u1)
            CALL PUSHREAL8(di1_t1)
            CALL PUSHREAL8(v1)
            CALL PUSHREAL8(u1_ms)
            CALL PUSHREAL8(di1)
            CALL PUSHREAL8(hk1_ms)
            CALL PUSHREAL8(rt1_ms)
            CALL PUSHREAL8(v2_u2)
            CALL PUSHREAL8(rt2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blsys needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
            CALL BLSYS()
            CALL PUSHCONTROL1B(1)
          END IF
!
!-------- set stuff at first iteration...
          IF (itbl .EQ. 1) THEN
!
!--------- set "baseline" Ue and Hk for forming  Ue(Hk)  relation
            CALL PUSHREAL8(ueref)
            ueref = u2
            CALL PUSHREAL8(hkref)
            hkref = hk2
!
!--------- if current point IBL was turbulent and is now laminar, then...
            IF (ibl .LT. itran(is) .AND. ibl .GE. itrold) THEN
!---------- extrapolate baseline Hk
              uem = uedg(ibl-1, is)
              dsm = dstr(ibl-1, is)
              thm = thet(ibl-1, is)
              msq = uem*uem*hstinv/(gm1bl*(1.0-0.5*uem*uem*hstinv))
              arg1 = dsm/thm
              CALL HKIN(arg1, msq, hkref, dummy, dummyy)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
!--------- if current point IBL was laminar, then...
            IF (ibl .LT. itrold) THEN
!---------- reinitialize or extrapolate Ctau if it's now turbulent
              IF (tran) THEN
                CALL PUSHREAL8(ctau(ibl, is))
                ctau(ibl, is) = 0.03
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              IF (turb) THEN
                CALL PUSHREAL8(ctau(ibl, is))
                ctau(ibl, is) = ctau(ibl-1, is)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              IF (tran .OR. turb) THEN
                CALL PUSHREAL8(cti)
                cti = ctau(ibl, is)
                CALL PUSHCONTROL2B(0)
              ELSE
                CALL PUSHCONTROL2B(1)
              END IF
            ELSE
              CALL PUSHCONTROL2B(2)
            END IF
          ELSE
            CALL PUSHCONTROL2B(3)
          END IF
!
!
!
          IF (simi .OR. ibl .EQ. iblte(is) + 1) THEN
!
!--------- for similarity station or first wake point, prescribe Ue
            vs2(4, 1) = 0.
            vs2(4, 2) = 0.
            vs2(4, 3) = 0.
            vs2(4, 4) = u2_uei
            vsrez(4) = ueref - u2
!
            CALL PUSHCONTROL1B(1)
          ELSE
!
!********* calculate Ue-Hk characteristic slope
!
            DO k=1,4
              CALL PUSHREAL8(vztmp(k))
              vztmp(k) = vsrez(k)
              DO l=1,5
                CALL PUSHREAL8(vtmp(k, l))
                vtmp(k, l) = vs2(k, l)
              END DO
            END DO
!
!--------- set unit dHk
            CALL PUSHREAL8(vtmp(4, 1))
            vtmp(4, 1) = 0.
            CALL PUSHREAL8(vtmp(4, 2))
            vtmp(4, 2) = hk2_t2
            CALL PUSHREAL8(vtmp(4, 3))
            vtmp(4, 3) = hk2_d2
            CALL PUSHREAL8(vtmp(4, 4))
            vtmp(4, 4) = hk2_u2*u2_uei
            CALL PUSHREAL8(vztmp(4))
            vztmp(4) = 1.0
!
!--------- calculate dUe response
            CALL GAUSS_FWD(4, 4, vtmp, vztmp, 1)
!
!--------- set  SENSWT * (normalized dUe/dHk)
            sennew = senswt*vztmp(4)*hkref/ueref
            IF (itbl .LE. 5) THEN
              CALL PUSHREAL8(sens)
              sens = sennew
              CALL PUSHCONTROL2B(0)
            ELSE IF (itbl .LE. 15) THEN
              CALL PUSHREAL8(sens)
              sens = 0.5*(sens+sennew)
              CALL PUSHCONTROL2B(1)
            ELSE
              CALL PUSHCONTROL2B(2)
            END IF
!
!--------- set prescribed Ue-Hk combination
            vs2(4, 1) = 0.
            vs2(4, 2) = hk2_t2*hkref
            vs2(4, 3) = hk2_d2*hkref
            vs2(4, 4) = (hk2_u2*hkref+sens/ueref)*u2_uei
            vsrez(4) = -(hkref**2*(hk2/hkref-1.0)) - sens*(u2/ueref-1.0)
!
            CALL PUSHCONTROL1B(0)
          END IF
!
!-------- solve Newton system for current "2" station
          CALL GAUSS_FWD(4, 4, vs2, vsrez, 1)
          IF (vsrez(2)/thi .GE. 0.) THEN
            x3 = vsrez(2)/thi
            CALL PUSHCONTROL1B(0)
          ELSE
            x3 = -(vsrez(2)/thi)
            CALL PUSHCONTROL1B(1)
          END IF
          IF (vsrez(3)/dsi .GE. 0.) THEN
            y1 = vsrez(3)/dsi
            CALL PUSHCONTROL1B(0)
          ELSE
            y1 = -(vsrez(3)/dsi)
            CALL PUSHCONTROL1B(1)
          END IF
          IF (vsrez(4)/uei .GE. 0.) THEN
            z1 = vsrez(4)/uei
            CALL PUSHCONTROL1B(0)
          ELSE
            z1 = -(vsrez(4)/uei)
            CALL PUSHCONTROL1B(1)
          END IF
          IF (x3 .LT. y1) THEN
            IF (y1 .LT. z1) THEN
              CALL PUSHREAL8(dmax)
              dmax = z1
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHREAL8(dmax)
              dmax = y1
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE IF (x3 .LT. z1) THEN
            CALL PUSHREAL8(dmax)
            dmax = z1
            CALL PUSHCONTROL2B(2)
          ELSE
            CALL PUSHREAL8(dmax)
            dmax = x3
            CALL PUSHCONTROL2B(3)
          END IF
          IF (ibl .GE. itran(is)) THEN
            IF (vsrez(1)/(10.0*cti) .GE. 0.) THEN
              y2 = vsrez(1)/(10.0*cti)
              CALL PUSHCONTROL1B(0)
            ELSE
              y2 = -(vsrez(1)/(10.0*cti))
              CALL PUSHCONTROL1B(1)
            END IF
            IF (dmax .LT. y2) THEN
              dmax = y2
              CALL PUSHCONTROL2B(2)
            ELSE
              dmax = dmax
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHCONTROL2B(0)
          END IF
!
          CALL PUSHREAL8(rlx)
          rlx = 1.0
          IF (dmax .GT. 0.3) THEN
            rlx = 0.3/dmax
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!-------- update as usual
          IF (ibl .LT. itran(is)) THEN
            ami = ami + rlx*vsrez(1)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (ibl .GE. itran(is)) THEN
            CALL PUSHREAL8(cti)
            cti = cti + rlx*vsrez(1)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHREAL8(thi)
          thi = thi + rlx*vsrez(2)
          CALL PUSHREAL8(dsi)
          dsi = dsi + rlx*vsrez(3)
          CALL PUSHREAL8(uei)
          uei = uei + rlx*vsrez(4)
!
!-------- eliminate absurd transients
          IF (ibl .GE. itran(is)) THEN
            IF (cti .GT. 0.30) THEN
              CALL PUSHREAL8(cti)
              cti = 0.30
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(cti)
              cti = cti
              CALL PUSHCONTROL1B(1)
            END IF
            IF (cti .LT. 0.0000001) THEN
              cti = 0.0000001
              CALL PUSHCONTROL2B(2)
            ELSE
              CALL PUSHCONTROL2B(1)
              cti = cti
            END IF
          ELSE
            CALL PUSHCONTROL2B(0)
          END IF
!
          IF (ibl .LE. iblte(is)) THEN
            CALL PUSHREAL8(hklim)
            hklim = 1.02
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(hklim)
            hklim = 1.00005
            CALL PUSHCONTROL1B(1)
          END IF
          msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
          dsw = dsi - dswaki
          CALL PUSHREAL8(dsw)
          CALL DSLIM(dsw, thi, uei, msq, hklim)
          dsi = dsw + dswaki
!
          IF (dmax .LE. deps) THEN
            GOTO 100
          ELSE
            ad_count = ad_count + 1
          END IF
        END DO
        CALL PUSHCONTROL2B(0)
        CALL PUSHINTEGER4(ad_count)
!
!
        IF (show_output) WRITE(*, 99001) ibl, is, dmax
!
!------ XFOILAD: repeated failure at the transition station (see i_xfoil):
!       keep the values of the global Newton update
        IF (ibl .EQ. itran(is) .AND. dmax .LE. 0.1) THEN
          xad_mfcur(is) = ibl
          IF (ibl .EQ. xad_mfprv(is)) THEN
            xad_mfcnt(is) = xad_mfcnt(is) + 1
          ELSE
            xad_mfcnt(is) = 1
          END IF
          IF (xad_mfcnt(is) .GE. xad_mfmax) THEN
            CALL PUSHREAL8(thi)
            thi = thi0
            dsi = dsi0
            CALL PUSHREAL8(uei)
            uei = uei0
            CALL PUSHREAL8(cti)
            cti = cti0
            IF (xad_rlxcap*xad_rlxfac .LT. xad_rlxmin) THEN
              CALL PUSHREAL8(xad_rlxcap)
              xad_rlxcap = xad_rlxmin
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(xad_rlxcap)
              xad_rlxcap = xad_rlxcap*xad_rlxfac
              CALL PUSHCONTROL1B(1)
            END IF
            IF (show_output) THEN
              CALL PUSHCONTROL2B(0)
              WRITE(*, *) 'MRCHDU: transition station', ibl, &
&             ' keeps the global Newton update, step limited to', &
&             xad_rlxcap
            ELSE
              CALL PUSHCONTROL2B(0)
            END IF
          ELSE
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
!
!------ the current unconverged solution might still be reasonable...
!CC        IF(DMAX .LE. 0.1) GO TO 110
        IF (dmax .GT. 0.1) THEN
!
!------- the current solution is garbage --> extrapolate values instead
          IF (ibl .GT. 3) THEN
            IF (ibl .LE. iblte(is)) THEN
              CALL PUSHREAL8(thi)
              thi = thet(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              dsi = dstr(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              CALL PUSHREAL8(uei)
              uei = uedg(ibm, is)
              CALL PUSHCONTROL2B(0)
            ELSE IF (ibl .EQ. iblte(is) + 1) THEN
              CALL PUSHREAL8(cti)
              cti = cte
              CALL PUSHREAL8(thi)
              thi = tte
              dsi = dte
              CALL PUSHREAL8(uei)
              uei = uedg(ibm, is)
              CALL PUSHCONTROL2B(1)
            ELSE
              CALL PUSHREAL8(thi)
              thi = thet(ibm, is)
              CALL PUSHREAL8(ratlen)
              ratlen = (xssi(ibl, is)-xssi(ibm, is))/(10.0*dstr(ibm, is)&
&               )
              dsi = (dstr(ibm, is)+thi*ratlen)/(1.0+ratlen)
              CALL PUSHREAL8(uei)
              uei = uedg(ibm, is)
              CALL PUSHCONTROL2B(2)
            END IF
            IF (ibl .EQ. itran(is)) THEN
              CALL PUSHREAL8(cti)
              cti = 0.05
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (ibl .GT. itran(is)) THEN
              CALL PUSHREAL8(cti)
              cti = ctau(ibm, is)
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
        ELSE
          CALL PUSHCONTROL2B(3)
        END IF
!
        CALL PUSHREAL8(u2)
        CALL PUSHREAL8(d2)
        CALL PUSHREAL8(t2)
        CALL PUSHREAL8(u2_uei)
        CALL PUSHREAL8(s2)
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL PUSHREAL8(hk2_ms)
        CALL PUSHREAL8(rt2_ms)
        CALL PUSHREAL8(h2_d2)
        CALL PUSHREAL8(hk2_u2)
        CALL PUSHREAL8(rt2_u2)
        CALL PUSHREAL8(h2_t2)
        CALL PUSHREAL8(h2)
        CALL PUSHREAL8(hk2_d2)
        CALL PUSHREAL8(hk2_t2)
        CALL PUSHREAL8(rt2_t2)
        CALL PUSHREAL8(rt2_re)
        CALL PUSHREAL8(m2)
        CALL PUSHREAL8(m2_ms)
        CALL PUSHREAL8(m2_u2)
        CALL PUSHREAL8(hk2)
        CALL PUSHREAL8(rt2)
        CALL BLKIN()
!
!------- check for transition and set appropriate flags and things
        IF (.NOT.simi .AND. (.NOT.turb)) THEN
          CALL PUSHREAL8(u2_ms)
          CALL PUSHREAL8(hk2_ms)
          CALL PUSHREAL8(rt2_ms)
          CALL PUSHREAL8(xt_xf)
          CALL PUSHREAL8(cq2)
          CALL PUSHREAL8(cf2_d2)
          CALL PUSHREAL8(di2_re)
          CALL PUSHREAL8(cf2_t2)
          CALL PUSHREAL8(ampl2)
          CALL PUSHREAL8(r2)
          CALL PUSHREAL8(hc2_d2)
          CALL PUSHREAL8(us2_d2)
          CALL PUSHREAL8(de2)
          CALL PUSHREAL8(h2_d2)
          CALL PUSHREAL8(hc2_t2)
          CALL PUSHREAL8(us2_t2)
          CALL PUSHREAL8(u2)
          CALL PUSHREAL8(hk2_u2)
          CALL PUSHREAL8(rt2_u2)
          CALL PUSHREAL8(h2_t2)
          CALL PUSHREAL8(cf2_re)
          CALL PUSHREAL8(h2)
          CALL PUSHREAL8(x2)
          CALL PUSHREAL8ARRAY(c2sav, ncom)
          CALL PUSHREAL8(di2_s2)
          CALL PUSHREAL8(us2_re)
          CALL PUSHREAL8(cq2_ms)
          CALL PUSHREAL8(xt_ms)
          CALL PUSHREAL8(de2_ms)
          CALL PUSHREAL8(hc2)
          CALL PUSHREAL8(hs2_ms)
          CALL PUSHREAL8(hs2)
          CALL PUSHREAL8(v2_re)
          CALL PUSHREAL8(us2)
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2_d2)
          CALL PUSHREAL8(d2)
          CALL PUSHREAL8(di2_ms)
          CALL PUSHREAL8(cq2_u2)
          CALL PUSHREAL8(xt_u2)
          CALL PUSHREAL8(de2_u2)
          CALL PUSHREAL8(xt_u1)
          CALL PUSHREAL8(t2)
          CALL PUSHREAL8(hk2_t2)
          CALL PUSHREAL8(rt2_t2)
          CALL PUSHREAL8(hs2_u2)
          CALL PUSHREAL8(xt_x2)
          CALL PUSHREAL8(xt_x1)
          CALL PUSHREAL8(u2_uei)
          CALL PUSHREAL8(dw2)
          CALL PUSHREAL8(xt)
          CALL PUSHREAL8(rt2_re)
          CALL PUSHREAL8(cf2_ms)
          CALL PUSHREAL8(r2_ms)
          CALL PUSHREAL8(di2_u2)
          CALL PUSHREAL8(m2)
          CALL PUSHREAL8(m2_ms)
          CALL PUSHBOOLEAN(tran)
          CALL PUSHREAL8(xt_a1)
          CALL PUSHREAL8(hc2_ms)
          CALL PUSHREAL8(us2_ms)
          CALL PUSHREAL8(cq2_d2)
          CALL PUSHREAL8(xt_d2)
          CALL PUSHREAL8(de2_d2)
          CALL PUSHREAL8(xt_d1)
          CALL PUSHREAL8(hs2_d2)
          CALL PUSHREAL8(v2_ms)
          CALL PUSHREAL8(cq2_t2)
          CALL PUSHREAL8(cf2_u2)
          CALL PUSHREAL8(xt_t2)
          CALL PUSHREAL8(r2_u2)
          CALL PUSHREAL8(de2_t2)
          CALL PUSHREAL8(xt_t1)
          CALL PUSHREAL8(s2)
          CALL PUSHREAL8(hs2_t2)
          CALL PUSHREAL8(m2_u2)
          CALL PUSHREAL8(hk2)
          CALL PUSHREAL8(hc2_u2)
          CALL PUSHREAL8(v2)
          CALL PUSHREAL8(us2_u2)
          CALL PUSHREAL8(cq2_re)
          CALL PUSHREAL8(xt_re)
          CALL PUSHREAL8(di2)
          CALL PUSHREAL8(di2_d2)
          CALL PUSHREAL8(hs2_re)
          CALL PUSHREAL8(v2_u2)
          CALL PUSHREAL8(rt2)
          CALL PUSHREAL8(di2_t2)
          mrchdu = TRCHEK()
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (daeps SAVEd by trchek2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to trchek needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
          IF (abort_on_nan .AND. (.NOT.mrchdu)) THEN
            GOTO 110
          ELSE
            ami = ampl2
            IF (tran) THEN
              CALL PUSHINTEGER4(itran(is))
              itran(is) = ibl
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (.NOT.tran) THEN
              CALL PUSHINTEGER4(itran(is))
              itran(is) = ibl + 2
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          END IF
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
!
!------- set all other extrapolated values for current station
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(1)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (wake) THEN
          CALL PUSHREAL8(cf2)
          CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
          CALL BLVAR(3)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
!
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(1)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (wake) THEN
          CALL PUSHREAL8(rt1)
          CALL PUSHREAL8(hk1_u1)
          CALL PUSHREAL8(rt1_u1)
          CALL PUSHREAL8(hk1_d1)
          CALL PUSHREAL8(hk1_t1)
          CALL PUSHREAL8(rt1_t1)
          CALL PUSHREAL8(rt1_re)
          CALL PUSHREAL8(hk1)
          CALL PUSHREAL8(hk1_ms)
          CALL PUSHREAL8(rt1_ms)
          CALL BLMID(3)
          CALL PUSHCONTROL2B(1)
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
        GOTO 20
 100    CALL PUSHCONTROL2B(2)
        CALL PUSHINTEGER4(ad_count)
        CALL PUSHCONTROL2B(0)
!
!------ pick up here after the Newton iterations
!
 20     CALL PUSHREAL8(sens)
        sens = sennew
!
!------ store primary variables
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(ctau(ibl, is))
          ctau(ibl, is) = ami
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(ctau(ibl, is))
          ctau(ibl, is) = cti
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(thet(ibl, is))
        thet(ibl, is) = thi
        CALL PUSHREAL8(dstr(ibl, is))
        dstr(ibl, is) = dsi
        CALL PUSHREAL8(uedg(ibl, is))
        uedg(ibl, is) = uei
!
!------ set "1" variables to "2" variables for next streamwise station
        CALL PUSHREAL8(u2)
        CALL PUSHREAL8(d2)
        CALL PUSHREAL8(t2)
        CALL PUSHREAL8(u2_uei)
        CALL PUSHREAL8(s2)
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL PUSHREAL8(hk2_ms)
        CALL PUSHREAL8(rt2_ms)
        CALL PUSHREAL8(r2)
        CALL PUSHREAL8(h2_d2)
        CALL PUSHREAL8(hk2_u2)
        CALL PUSHREAL8(rt2_u2)
        CALL PUSHREAL8(h2_t2)
        CALL PUSHREAL8(h2)
        CALL PUSHREAL8(hk2_d2)
        CALL PUSHREAL8(hk2_t2)
        CALL PUSHREAL8(rt2_t2)
        CALL PUSHREAL8(rt2_re)
        CALL PUSHREAL8(m2)
        CALL PUSHREAL8(m2_ms)
        CALL PUSHREAL8(m2_u2)
        CALL PUSHREAL8(hk2)
        CALL PUSHREAL8(rt2)
        CALL BLKIN()
        CALL PUSHREAL8(rt1)
        CALL PUSHREAL8(hk1_u1)
        CALL PUSHREAL8(ampl1)
        CALL PUSHREAL8(rt1_u1)
        CALL PUSHREAL8(u1)
        CALL PUSHREAL8(x1)
        CALL PUSHREAL8(hk1_d1)
        CALL PUSHREAL8(hk1_t1)
        CALL PUSHREAL8(rt1_t1)
        CALL PUSHREAL8(d1)
        CALL PUSHREAL8(t1)
        CALL PUSHREAL8(rt1_re)
        CALL PUSHREAL8(hk1)
        CALL PUSHREAL8(hk1_ms)
        CALL PUSHREAL8(rt1_ms)
        CALL BLC_1FROM2()
!
!
!------ turbulent intervals will follow transition interval or TE
        IF (tran .OR. ibl .EQ. iblte(is)) THEN
          CALL PUSHBOOLEAN(turb)
          turb = .true.
!
!------- save transition location
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
!
        CALL PUSHBOOLEAN(tran)
        tran = .false.
        CALL PUSHINTEGER4(ibl)
        ad_count0 = ad_count0 + 1
      END DO
      CALL PUSHCONTROL2B(0)
      CALL PUSHINTEGER4(ad_count0)
!
!
!---- XFOILAD: cycle of the transition interval (see i_xfoil)
      IF (itran(is) .NE. itrold) THEN
        IF (itran(is) - itrold .GE. 0.) THEN
          abs0 = itran(is) - itrold
        ELSE
          abs0 = -(itran(is)-itrold)
        END IF
        IF (itran(is) .EQ. xad_trprv(is) .AND. abs0 .EQ. 1) THEN
          xad_trnfl(is) = xad_trnfl(is) + 1
          IF (xad_trnfl(is) .GE. xad_trnflmax) THEN
            IF (xad_rlxcap*xad_rlxfac .LT. xad_rlxmin) THEN
              CALL PUSHREAL8(xad_rlxcap)
              xad_rlxcap = xad_rlxmin
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(xad_rlxcap)
              xad_rlxcap = xad_rlxcap*xad_rlxfac
              CALL PUSHCONTROL1B(1)
            END IF
            IF (show_output) THEN
              CALL PUSHINTEGER4(is)
              CALL PUSHCONTROL3B(1)
              WRITE(*, *) 'MRCHDU: transition cycle on side', is, &
&             ', Newton step limited to', xad_rlxcap
            ELSE
              CALL PUSHINTEGER4(is)
              CALL PUSHCONTROL3B(1)
            END IF
          ELSE
            CALL PUSHINTEGER4(is)
            CALL PUSHCONTROL3B(2)
          END IF
        ELSE
          CALL PUSHINTEGER4(is)
          CALL PUSHCONTROL3B(3)
        END IF
        xad_trprv(is) = itrold
      ELSE
        CALL PUSHINTEGER4(is)
        CALL PUSHCONTROL3B(4)
      END IF
      xad_mfprv(is) = xad_mfcur(is)
    END DO
    amib = 0.0_8
    vtmpb = 0.0_8
    hkrefb = 0.0_8
    uerefb = 0.0_8
    cteb = 0.0_8
    vztmpb = 0.0_8
    sensb = 0.0_8
    sennewb = 0.0_8
    tteb = 0.0_8
    dteb = 0.0_8
    GOTO 210
 110 CALL PUSHCONTROL2B(2)
    CALL PUSHINTEGER4(ad_count0)
    GOTO 130
 120 CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count0)
 130 CALL POPINTEGER4(ad_count0)
    DO i0=1,ad_count0
      IF (i0 .EQ. 1) THEN
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          xiforcb = 0.0_8
          amcritb = 0.0_8
          GOTO 200
        ELSE IF (branch .EQ. 1) THEN
          rt2b = 0.0_8
          v2_u2b = 0.0_8
          v2b = 0.0_8
          hk2b = 0.0_8
          m2_u2b = 0.0_8
          xiforcb = 0.0_8
          s2b = 0.0_8
          r2_u2b = 0.0_8
          v2_msb = 0.0_8
          m2_msb = 0.0_8
          m2b = 0.0_8
          r2_msb = 0.0_8
          rt2_reb = 0.0_8
          dw2b = 0.0_8
          u2_ueib = 0.0_8
          rt2_t2b = 0.0_8
          hk2_t2b = 0.0_8
          t2b = 0.0_8
          d2b = 0.0_8
          hk2_d2b = 0.0_8
          v2_reb = 0.0_8
          x2b = 0.0_8
          amcritb = 0.0_8
          h2b = 0.0_8
          h2_t2b = 0.0_8
          rt2_u2b = 0.0_8
          hk2_u2b = 0.0_8
          u2b = 0.0_8
          h2_d2b = 0.0_8
          r2b = 0.0_8
          ampl2b = 0.0_8
          rt2_msb = 0.0_8
          hk2_msb = 0.0_8
          u2_msb = 0.0_8
          thi0b = 0.0_8
          vtmpb = 0.0_8
          thib = 0.0_8
          hkrefb = 0.0_8
          uei0b = 0.0_8
          dsi0b = 0.0_8
          uerefb = 0.0_8
          cteb = 0.0_8
          ctib = 0.0_8
          vztmpb = 0.0_8
          sensb = 0.0_8
          sennewb = 0.0_8
          dsib = 0.0_8
          ueib = 0.0_8
          tteb = 0.0_8
          dswakib = 0.0_8
          cti0b = 0.0_8
          xsib = 0.0_8
          dteb = 0.0_8
          GOTO 150
        ELSE
          rt2b = 0.0_8
          hk2b = 0.0_8
          m2_u2b = 0.0_8
          xiforcb = 0.0_8
          s2b = 0.0_8
          m2_msb = 0.0_8
          m2b = 0.0_8
          rt2_reb = 0.0_8
          rt2_t2b = 0.0_8
          hk2_t2b = 0.0_8
          t2b = 0.0_8
          d2b = 0.0_8
          hk2_d2b = 0.0_8
          amcritb = 0.0_8
          h2b = 0.0_8
          h2_t2b = 0.0_8
          rt2_u2b = 0.0_8
          hk2_u2b = 0.0_8
          u2b = 0.0_8
          h2_d2b = 0.0_8
          r2b = 0.0_8
          ampl2b = 0.0_8
          rt2_msb = 0.0_8
          hk2_msb = 0.0_8
          vtmpb = 0.0_8
          thib = 0.0_8
          hkrefb = 0.0_8
          uerefb = 0.0_8
          cteb = 0.0_8
          ctib = 0.0_8
          vztmpb = 0.0_8
          sennewb = 0.0_8
          dsib = 0.0_8
          ueib = 0.0_8
          tteb = 0.0_8
          dswakib = 0.0_8
          xsib = 0.0_8
          dteb = 0.0_8
        END IF
      ELSE
        CALL POPBOOLEAN(tran)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) CALL POPBOOLEAN(turb)
        CALL POPREAL8(rt1_ms)
        CALL POPREAL8(hk1_ms)
        CALL POPREAL8(hk1)
        CALL POPREAL8(rt1_re)
        CALL POPREAL8(t1)
        CALL POPREAL8(d1)
        CALL POPREAL8(rt1_t1)
        CALL POPREAL8(hk1_t1)
        CALL POPREAL8(hk1_d1)
        CALL POPREAL8(x1)
        CALL POPREAL8(u1)
        CALL POPREAL8(rt1_u1)
        CALL POPREAL8(ampl1)
        CALL POPREAL8(hk1_u1)
        CALL POPREAL8(rt1)
        u2_msb = 0.0_8
        hk2_msb = 0.0_8
        rt2_msb = 0.0_8
        ampl2b = 0.0_8
        r2b = 0.0_8
        h2_d2b = 0.0_8
        u2b = 0.0_8
        hk2_u2b = 0.0_8
        rt2_u2b = 0.0_8
        h2_t2b = 0.0_8
        h2b = 0.0_8
        x2b = 0.0_8
        v2_reb = 0.0_8
        hk2_d2b = 0.0_8
        d2b = 0.0_8
        t2b = 0.0_8
        hk2_t2b = 0.0_8
        rt2_t2b = 0.0_8
        u2_ueib = 0.0_8
        dw2b = 0.0_8
        rt2_reb = 0.0_8
        r2_msb = 0.0_8
        m2b = 0.0_8
        m2_msb = 0.0_8
        v2_msb = 0.0_8
        r2_u2b = 0.0_8
        s2b = 0.0_8
        m2_u2b = 0.0_8
        hk2b = 0.0_8
        v2b = 0.0_8
        v2_u2b = 0.0_8
        rt2b = 0.0_8
        CALL BLC_1FROM2_B()
        CALL POPREAL8(rt2)
        CALL POPREAL8(hk2)
        CALL POPREAL8(m2_u2)
        CALL POPREAL8(m2_ms)
        CALL POPREAL8(m2)
        CALL POPREAL8(rt2_re)
        CALL POPREAL8(rt2_t2)
        CALL POPREAL8(hk2_t2)
        CALL POPREAL8(hk2_d2)
        CALL POPREAL8(h2)
        CALL POPREAL8(h2_t2)
        CALL POPREAL8(rt2_u2)
        CALL POPREAL8(hk2_u2)
        CALL POPREAL8(h2_d2)
        CALL POPREAL8(r2)
        CALL POPREAL8(rt2_ms)
        CALL POPREAL8(hk2_ms)
        CALL BLKIN_B()
        CALL POPREAL8(s2)
        CALL POPREAL8(u2_uei)
        CALL POPREAL8(t2)
        CALL POPREAL8(d2)
        CALL POPREAL8(u2)
        xsib = 0.0_8
        ctib = 0.0_8
        thib = 0.0_8
        dsib = 0.0_8
        dswakib = 0.0_8
        ueib = 0.0_8
        CALL BLPRV_B(xsi, xsib, ami, amib, cti, ctib, thi, thib, dsi, &
&              dsib, dswaki, dswakib, uei, ueib)
        u2b = 2*u2*r2*cf2*0.5*taub(ibl, is)
        tempb1 = u2**2*0.5*taub(ibl, is)
        taub(ibl, is) = 0.0_8
        r2b = cf2*tempb1
        cf2b = cf2b + r2*tempb1
        dsib = dsib + uei*massb(ibl, is) + dstrb(ibl, is)
        ueib = ueib + dsi*massb(ibl, is) + uedgb(ibl, is)
        massb(ibl, is) = 0.0_8
        CALL POPREAL8(uedg(ibl, is))
        uedgb(ibl, is) = 0.0_8
        CALL POPREAL8(dstr(ibl, is))
        dstrb(ibl, is) = 0.0_8
        CALL POPREAL8(thet(ibl, is))
        thib = thib + thetb(ibl, is)
        thetb(ibl, is) = 0.0_8
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(ctau(ibl, is))
          ctib = ctib + ctaub(ibl, is)
          ctaub(ibl, is) = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(ctau(ibl, is))
          amib = amib + ctaub(ibl, is)
          ctaub(ibl, is) = 0.0_8
        END IF
        CALL POPREAL8(sens)
        sennewb = sennewb + sensb
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          GOTO 150
        ELSE
          IF (branch .EQ. 1) THEN
            simi = ibl .EQ. 2
            CALL POPREAL8(rt1_ms)
            CALL POPREAL8(hk1_ms)
            CALL POPREAL8(hk1)
            CALL POPREAL8(rt1_re)
            CALL POPREAL8(rt1_t1)
            CALL POPREAL8(hk1_t1)
            CALL POPREAL8(hk1_d1)
            CALL POPREAL8(rt1_u1)
            CALL POPREAL8(hk1_u1)
            CALL POPREAL8(rt1)
          END IF
          wake = ibl .GT. iblte(is)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(rt1_ms)
            CALL POPREAL8(hk1_ms)
            CALL POPREAL8(hk1)
            CALL POPREAL8(rt1_re)
            CALL POPREAL8(rt1_t1)
            CALL POPREAL8(hk1_t1)
            CALL POPREAL8(hk1_d1)
            CALL POPREAL8(rt1_u1)
            CALL POPREAL8(hk1_u1)
            CALL POPREAL8(rt1)
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(rt1_ms)
            CALL POPREAL8(hk1_ms)
            CALL POPREAL8(hk1)
            CALL POPREAL8(rt1_re)
            CALL POPREAL8(rt1_t1)
            CALL POPREAL8(hk1_t1)
            CALL POPREAL8(hk1_d1)
            CALL POPREAL8(rt1_u1)
            CALL POPREAL8(hk1_u1)
            CALL POPREAL8(rt1)
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(hk2)
            CALL POPREAL8(cf2)
            hk2_msb = 0.0_8
            rt2_msb = 0.0_8
            h2_d2b = 0.0_8
            hk2_u2b = 0.0_8
            rt2_u2b = 0.0_8
            h2_t2b = 0.0_8
            h2b = 0.0_8
            hk2_d2b = 0.0_8
            d2b = 0.0_8
            t2b = 0.0_8
            hk2_t2b = 0.0_8
            rt2_t2b = 0.0_8
            rt2_reb = 0.0_8
            m2b = 0.0_8
            m2_msb = 0.0_8
            s2b = 0.0_8
            m2_u2b = 0.0_8
            hk2b = 0.0_8
            rt2b = 0.0_8
            CALL BLVAR_B(3)
            di2_t2b = 0.0_8
            hs2_reb = 0.0_8
            di2_d2b = 0.0_8
            di2b = 0.0_8
            cq2_reb = 0.0_8
            us2_u2b = 0.0_8
            hc2_u2b = 0.0_8
            hs2_t2b = 0.0_8
            de2_t2b = 0.0_8
            cf2_u2b = 0.0_8
            cq2_t2b = 0.0_8
            hs2_d2b = 0.0_8
            de2_d2b = 0.0_8
            cq2_d2b = 0.0_8
            us2_msb = 0.0_8
            hc2_msb = 0.0_8
            di2_u2b = 0.0_8
            cf2_msb = 0.0_8
            hs2_u2b = 0.0_8
            de2_u2b = 0.0_8
            cq2_u2b = 0.0_8
            di2_msb = 0.0_8
            cf2b = 0.0_8
            us2b = 0.0_8
            hs2b = 0.0_8
            hs2_msb = 0.0_8
            hc2b = 0.0_8
            de2_msb = 0.0_8
            cq2_msb = 0.0_8
            us2_reb = 0.0_8
            di2_s2b = 0.0_8
            cf2_reb = 0.0_8
            us2_t2b = 0.0_8
            hc2_t2b = 0.0_8
            de2b = 0.0_8
            us2_d2b = 0.0_8
            hc2_d2b = 0.0_8
            cf2_t2b = 0.0_8
            di2_reb = 0.0_8
            cf2_d2b = 0.0_8
            cq2b = 0.0_8
          ELSE
            rt2b = 0.0_8
            hk2b = 0.0_8
            m2_u2b = 0.0_8
            s2b = 0.0_8
            m2_msb = 0.0_8
            m2b = 0.0_8
            rt2_reb = 0.0_8
            rt2_t2b = 0.0_8
            hk2_t2b = 0.0_8
