        CALL POPREAL8(cf2)
        CALL POPREAL8(us2)
        CALL POPREAL8(v2_re)
        CALL POPREAL8(hs2)
        CALL POPREAL8(hs2_ms)
        CALL POPREAL8(hc2)
        CALL POPREAL8(de2_ms)
        CALL POPREAL8(xt_ms)
        CALL POPREAL8(cq2_ms)
        CALL POPREAL8(us2_re)
        CALL POPREAL8(di2_s2)
        CALL POPREAL8ARRAY(c2sav, ncom)
        CALL POPREAL8(x2)
        CALL POPREAL8(h2)
        CALL POPREAL8(cf2_re)
        CALL POPREAL8(h2_t2)
        CALL POPREAL8(rt2_u2)
        CALL POPREAL8(hk2_u2)
        CALL POPREAL8(u2)
        CALL POPREAL8(us2_t2)
        CALL POPREAL8(hc2_t2)
        CALL POPREAL8(h2_d2)
        CALL POPREAL8(de2)
        CALL POPREAL8(us2_d2)
        CALL POPREAL8(hc2_d2)
        CALL POPREAL8(r2)
        CALL POPREAL8(ampl2)
        CALL POPREAL8(cf2_t2)
        CALL POPREAL8(di2_re)
        CALL POPREAL8(cf2_d2)
        CALL POPREAL8(cq2)
        CALL POPREAL8(xt_xf)
        CALL POPREAL8(rt2_ms)
        CALL POPREAL8(hk2_ms)
        CALL POPREAL8(u2_ms)
        CALL TRCHEK_B()
        amib = 0.0_8
 180    CALL POPREAL8(rt2)
        CALL POPREAL8(hk2)
        CALL POPREAL8(m2_u2)
        CALL POPREAL8(m2_ms)
        CALL POPREAL8(m2)
        CALL POPREAL8(rt2_re)
        CALL POPREAL8(rt2_t2)
        CALL POPREAL8(hk2_t2)
        CALL POPREAL8(hk2_d2)
        CALL POPREAL8(h2)
        CALL POPREAL8(h2_t2)
        CALL POPREAL8(rt2_u2)
        CALL POPREAL8(hk2_u2)
        CALL POPREAL8(h2_d2)
        CALL POPREAL8(rt2_ms)
        CALL POPREAL8(hk2_ms)
        CALL BLKIN_B()
        CALL POPREAL8(s2)
        CALL POPREAL8(u2_uei)
        CALL POPREAL8(t2)
        CALL POPREAL8(d2)
        CALL POPREAL8(u2)
        CALL BLPRV_B(xsi, xsib, ami, amib, cti, ctib, thi, thib, dsi, &
&              dsib, dswaki, dswakib, uei, ueib)
 190  CONTINUE
      ctib = ctib + cti0b
      ueib = ueib + uei0b
      dsib = dsib + dsi0b
      thib = thib + thi0b
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        max2b = dsib
        dswakib = dswakib + dsib
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          thib = thib + 1.00005*max2b
          dsib = 0.0_8
        ELSE
          dsib = max2b
          dswakib = dswakib - max2b
        END IF
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        max1b = dsib
        dswakib = dswakib + dsib
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          thib = thib + 1.02000*max1b
          dsib = 0.0_8
        ELSE
          dsib = max1b
          dswakib = dswakib - max1b
        END IF
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        wgapb(iw) = wgapb(iw) + dswakib
        CALL POPINTEGER4(iw)
      END IF
      CALL POPCONTROL2B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(cti)
        ctaub(ibl, is) = ctaub(ibl, is) + amib
        amib = 0.0_8
      ELSE
        IF (branch .EQ. 1) ctib = 0.0_8
        CALL POPREAL8(cti)
        ctaub(ibl, is) = ctaub(ibl, is) + ctib
      END IF
      CALL POPREAL8(dsi)
      dstrb(ibl, is) = dstrb(ibl, is) + dsib
      CALL POPREAL8(thi)
      thetb(ibl, is) = thetb(ibl, is) + thib
      CALL POPREAL8(uei)
      uedgb(ibl, is) = uedgb(ibl, is) + ueib
      xssib(ibl, is) = xssib(ibl, is) + xsib
      CALL POPBOOLEAN(wake)
      CALL POPBOOLEAN(simi)
 200  CALL POPINTEGER4(ibl)
    END DO
    CALL POPINTEGER4(itran(is))
    CALL POPBOOLEAN(turb)
    CALL POPREAL8(xiforc)
    CALL POPREAL8ARRAY(w1, 6*iqx)
    CALL POPREAL8ARRAY(w3, 6*iqx)
    CALL XIFSET_B(is)
    acritb(is) = acritb(is) + amcritb
 210 CALL POPCONTROL3B(branch)
! TAPENADE: (CF01) Irreductible entry into loop
    IF (branch .NE. 0) THEN
      IF (branch .LT. 3) THEN
        IF (branch .EQ. 1) THEN
          CALL POPINTEGER4(is)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(xad_rlxcap)
          ELSE
            CALL POPREAL8(xad_rlxcap)
          END IF
        ELSE
          CALL POPINTEGER4(is)
        END IF
      ELSE IF (branch .EQ. 3) THEN
        CALL POPINTEGER4(is)
      ELSE
        CALL POPINTEGER4(is)
      END IF
      bule = 1.0
      amcrit = acrit(is)
      GOTO 130
    END IF
    CALL POPINTEGER4(is)
99001 FORMAT(' MRCHDU: Convergence failed at', i4, '  side', i2, &
&          '    Res =', e12.4)
  END SUBROUTINE MRCHDU_B

!*==MRCHDU.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  FUNCTION MRCHDU()
    USE M_XBLSYS_DIFF, ONLY : hkin, tesys, trchek, blprv, blkin, blsys, blvar, blmid
    USE M_XSOLVE_DIFF, ONLY : gauss
    USE I_XFOIL_DIFF
    USE I_XBL_DIFF
    IMPLICIT NONE
!
    LOGICAL :: mrchdu
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ami, cte, cti, dmax, dsi, dsm, dsw, dswaki, dte, dummy, &
&   hklim, hkref, msq, ratlen, sennew, sens, senswt, thi, thm, tte, uei&
&   , uem, ueref, xsi, dummyy
    REAL :: cti0, dsi0, thi0, uei0
    REAL, SAVE :: deps
    INTEGER :: ibl, ibm, icom, is, itbl, itrold, iw, k, l
    REAL, DIMENSION(4, 5) :: vtmp
    REAL, DIMENSION(4) :: vztmp
    INTRINSIC MAX
    INTRINSIC ABS
    INTRINSIC MIN
    REAL :: x3
    REAL :: y1
    REAL :: z1
    REAL :: y2
    REAL :: max1
    REAL :: max2
    INTEGER :: abs0
    REAL :: arg1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!----------------------------------------------------
!     Marches the BLs and wake in mixed mode using
!     the current Ue and Hk.  The calculated Ue
!     and Hk lie along a line quasi-normal to the
!     natural Ue-Hk characteristic line of the
!     current BL so that the Goldstein or Levy-Lees
!     singularity is never encountered.  Continuous
!     checking of transition onset is performed.
!----------------------------------------------------
!cc   REAL MDI
!
    DATA deps /5.0e-6/
    mrchdu = .true.
!
!---- constant controlling how far Hk is allowed to deviate
!-    from the specified value.
    senswt = 1000.0
!
    DO is=1,2
!
      amcrit = acrit(is)
!
!---- set forced transition arc length position
      CALL XIFSET(is)
!
!---- set leading edge pressure gradient parameter  x/u du/dx
      ibl = 2
      xsi = xssi(ibl, is)
      uei = uedg(ibl, is)
!CC      BULE = LOG(UEDG(IBL+1,IS)/UEI) / LOG(XSSI(IBL+1,IS)/XSI)
!CC      BULE = MAX( -.08 , BULE )
      bule = 1.0
!
!---- old transition station
      itrold = itran(is)
      xad_mfcur(is) = 0
!
      tran = .false.
      turb = .false.
      itran(is) = iblte(is)
!
!---- march downstream
      DO ibl=2,nbl(is)
        ibm = ibl - 1
!
        simi = ibl .EQ. 2
        wake = ibl .GT. iblte(is)
!
!------ initialize current station to existing variables
        xsi = xssi(ibl, is)
        uei = uedg(ibl, is)
        thi = thet(ibl, is)
        dsi = dstr(ibl, is)
!CC        MDI = MASS(IBL,IS)
!
!------ fixed BUG   MD 7 June 99
        IF (ibl .LT. itrold) THEN
          ami = ctau(ibl, is)
          cti = 0.03
        ELSE
          cti = ctau(ibl, is)
          IF (cti .LE. 0.0) cti = 0.03
        END IF
!
!CC        DSI = MDI/UEI
!
        IF (wake) THEN
          iw = ibl - iblte(is)
          dswaki = wgap(iw)
        ELSE
          dswaki = 0.
        END IF
!
        IF (ibl .LE. iblte(is)) THEN
          IF (dsi - dswaki .LT. 1.02000*thi) THEN
            max1 = 1.02000*thi
          ELSE
            max1 = dsi - dswaki
          END IF
          dsi = max1 + dswaki
        END IF
        IF (ibl .GT. iblte(is)) THEN
          IF (dsi - dswaki .LT. 1.00005*thi) THEN
            max2 = 1.00005*thi
          ELSE
            max2 = dsi - dswaki
          END IF
          dsi = max2 + dswaki
        END IF
!
!------ XFOILAD: values of the global Newton update (deadlock fallback)
        thi0 = thi
        dsi0 = dsi
        uei0 = uei
        cti0 = cti
!
!------ Newton iteration loop for current station
        DO itbl=1,25
!
!-------- assemble 10x3 linearized system for dCtau, dTh, dDs, dUe, dXi
!         at the previous "1" station and the current "2" station
!         (the "1" station coefficients will be ignored)
!
          CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
          CALL BLKIN()
!
!-------- check for transition and set appropriate flags and things
          IF (.NOT.simi .AND. (.NOT.turb)) THEN
            mrchdu = TRCHEK()
            IF (abort_on_nan .AND. (.NOT.mrchdu)) THEN
              RETURN
            ELSE
              ami = ampl2
              IF (tran) itran(is) = ibl
              IF (.NOT.tran) itran(is) = ibl + 2
            END IF
          END IF
!
          IF (ibl .EQ. iblte(is) + 1) THEN
            tte = thet(iblte(1), 1) + thet(iblte(2), 2)
            dte = dstr(iblte(1), 1) + dstr(iblte(2), 2) + ante
            cte = (ctau(iblte(1), 1)*thet(iblte(1), 1)+ctau(iblte(2), 2)&
&             *thet(iblte(2), 2))/tte
            CALL TESYS(cte, tte, dte)
          ELSE
            CALL BLSYS()
          END IF
!
!-------- set stuff at first iteration...
          IF (itbl .EQ. 1) THEN
!
!--------- set "baseline" Ue and Hk for forming  Ue(Hk)  relation
            ueref = u2
            hkref = hk2
!
!--------- if current point IBL was turbulent and is now laminar, then...
            IF (ibl .LT. itran(is) .AND. ibl .GE. itrold) THEN
!---------- extrapolate baseline Hk
              uem = uedg(ibl-1, is)
              dsm = dstr(ibl-1, is)
              thm = thet(ibl-1, is)
              msq = uem*uem*hstinv/(gm1bl*(1.0-0.5*uem*uem*hstinv))
              arg1 = dsm/thm
              CALL HKIN(arg1, msq, hkref, dummy, dummyy)
            END IF
!
!--------- if current point IBL was laminar, then...
            IF (ibl .LT. itrold) THEN
!---------- reinitialize or extrapolate Ctau if it's now turbulent
              IF (tran) ctau(ibl, is) = 0.03
              IF (turb) ctau(ibl, is) = ctau(ibl-1, is)
              IF (tran .OR. turb) THEN
                cti = ctau(ibl, is)
                s2 = cti
              END IF
            END IF
          END IF
!
!
!
          IF (simi .OR. ibl .EQ. iblte(is) + 1) THEN
!
!--------- for similarity station or first wake point, prescribe Ue
            vs2(4, 1) = 0.
            vs2(4, 2) = 0.
            vs2(4, 3) = 0.
            vs2(4, 4) = u2_uei
            vsrez(4) = ueref - u2
!
          ELSE
!
!********* calculate Ue-Hk characteristic slope
!
            DO k=1,4
              vztmp(k) = vsrez(k)
              DO l=1,5
                vtmp(k, l) = vs2(k, l)
              END DO
            END DO
!
!--------- set unit dHk
            vtmp(4, 1) = 0.
            vtmp(4, 2) = hk2_t2
            vtmp(4, 3) = hk2_d2
            vtmp(4, 4) = hk2_u2*u2_uei
            vztmp(4) = 1.0
!
!--------- calculate dUe response
            CALL GAUSS(4, 4, vtmp, vztmp, 1)
!
!--------- set  SENSWT * (normalized dUe/dHk)
            sennew = senswt*vztmp(4)*hkref/ueref
            IF (itbl .LE. 5) THEN
              sens = sennew
            ELSE IF (itbl .LE. 15) THEN
              sens = 0.5*(sens+sennew)
            END IF
!
!--------- set prescribed Ue-Hk combination
            vs2(4, 1) = 0.
            vs2(4, 2) = hk2_t2*hkref
            vs2(4, 3) = hk2_d2*hkref
            vs2(4, 4) = (hk2_u2*hkref+sens/ueref)*u2_uei
            vsrez(4) = -(hkref**2*(hk2/hkref-1.0)) - sens*(u2/ueref-1.0)
!
          END IF
!
!-------- solve Newton system for current "2" station
          CALL GAUSS(4, 4, vs2, vsrez, 1)
          IF (vsrez(2)/thi .GE. 0.) THEN
            x3 = vsrez(2)/thi
          ELSE
            x3 = -(vsrez(2)/thi)
          END IF
          IF (vsrez(3)/dsi .GE. 0.) THEN
            y1 = vsrez(3)/dsi
          ELSE
            y1 = -(vsrez(3)/dsi)
          END IF
          IF (vsrez(4)/uei .GE. 0.) THEN
            z1 = vsrez(4)/uei
          ELSE
            z1 = -(vsrez(4)/uei)
          END IF
          IF (x3 .LT. y1) THEN
            IF (y1 .LT. z1) THEN
              dmax = z1
            ELSE
              dmax = y1
            END IF
          ELSE IF (x3 .LT. z1) THEN
            dmax = z1
          ELSE
            dmax = x3
          END IF
          IF (ibl .GE. itran(is)) THEN
            IF (vsrez(1)/(10.0*cti) .GE. 0.) THEN
              y2 = vsrez(1)/(10.0*cti)
            ELSE
              y2 = -(vsrez(1)/(10.0*cti))
            END IF
            IF (dmax .LT. y2) THEN
              dmax = y2
            ELSE
              dmax = dmax
            END IF
          END IF
!
          rlx = 1.0
          IF (dmax .GT. 0.3) rlx = 0.3/dmax
!
!-------- update as usual
          IF (ibl .LT. itran(is)) ami = ami + rlx*vsrez(1)
          IF (ibl .GE. itran(is)) cti = cti + rlx*vsrez(1)
          thi = thi + rlx*vsrez(2)
          dsi = dsi + rlx*vsrez(3)
          uei = uei + rlx*vsrez(4)
!
!-------- eliminate absurd transients
          IF (ibl .GE. itran(is)) THEN
            IF (cti .GT. 0.30) THEN
              cti = 0.30
            ELSE
              cti = cti
            END IF
            IF (cti .LT. 0.0000001) THEN
              cti = 0.0000001
            ELSE
              cti = cti
            END IF
          END IF
!
          IF (ibl .LE. iblte(is)) THEN
            hklim = 1.02
          ELSE
            hklim = 1.00005
          END IF
          msq = uei*uei*hstinv/(gm1bl*(1.0-0.5*uei*uei*hstinv))
          dsw = dsi - dswaki
          CALL DSLIM(dsw, thi, uei, msq, hklim)
          dsi = dsw + dswaki
!
          IF (dmax .LE. deps) GOTO 20
        END DO
!
!
        IF (show_output) WRITE(*, 99001) ibl, is, dmax
!
!------ XFOILAD: repeated failure at the transition station (see i_xfoil):
!       keep the values of the global Newton update
        IF (ibl .EQ. itran(is) .AND. dmax .LE. 0.1) THEN
          xad_mfcur(is) = ibl
          IF (ibl .EQ. xad_mfprv(is)) THEN
            xad_mfcnt(is) = xad_mfcnt(is) + 1
          ELSE
            xad_mfcnt(is) = 1
          END IF
          IF (xad_mfcnt(is) .GE. xad_mfmax) THEN
            thi = thi0
            dsi = dsi0
            uei = uei0
            cti = cti0
            IF (xad_rlxcap*xad_rlxfac .LT. xad_rlxmin) THEN
              xad_rlxcap = xad_rlxmin
            ELSE
              xad_rlxcap = xad_rlxcap*xad_rlxfac
            END IF
            IF (show_output) WRITE(*, *) 'MRCHDU: transition station', &
&                            ibl, &
&                     ' keeps the global Newton update, step limited to'&
&                            , xad_rlxcap
          END IF
        END IF
!
!------ the current unconverged solution might still be reasonable...
!CC        IF(DMAX .LE. 0.1) GO TO 110
        IF (dmax .GT. 0.1) THEN
!
!------- the current solution is garbage --> extrapolate values instead
          IF (ibl .GT. 3) THEN
            IF (ibl .LE. iblte(is)) THEN
              thi = thet(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              dsi = dstr(ibm, is)*(xssi(ibl, is)/xssi(ibm, is))**0.5
              uei = uedg(ibm, is)
            ELSE IF (ibl .EQ. iblte(is) + 1) THEN
              cti = cte
              thi = tte
              dsi = dte
              uei = uedg(ibm, is)
            ELSE
              thi = thet(ibm, is)
              ratlen = (xssi(ibl, is)-xssi(ibm, is))/(10.0*dstr(ibm, is)&
&               )
              dsi = (dstr(ibm, is)+thi*ratlen)/(1.0+ratlen)
              uei = uedg(ibm, is)
            END IF
            IF (ibl .EQ. itran(is)) cti = 0.05
            IF (ibl .GT. itran(is)) cti = ctau(ibm, is)
          END IF
        END IF
!
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL BLKIN()
!
!------- check for transition and set appropriate flags and things
        IF (.NOT.simi .AND. (.NOT.turb)) THEN
          mrchdu = TRCHEK()
          IF (abort_on_nan .AND. (.NOT.mrchdu)) THEN
            RETURN
          ELSE
            ami = ampl2
            IF (tran) itran(is) = ibl
            IF (.NOT.tran) itran(is) = ibl + 2
          END IF
        END IF
!
!------- set all other extrapolated values for current station
        IF (ibl .LT. itran(is)) CALL BLVAR(1)
        IF (ibl .GE. itran(is)) CALL BLVAR(2)
        IF (wake) CALL BLVAR(3)
!
        IF (ibl .LT. itran(is)) CALL BLMID(1)
        IF (ibl .GE. itran(is)) CALL BLMID(2)
        IF (wake) CALL BLMID(3)
!
!------ pick up here after the Newton iterations
!
 20     sens = sennew
!
!------ store primary variables
        IF (ibl .LT. itran(is)) ctau(ibl, is) = ami
        IF (ibl .GE. itran(is)) ctau(ibl, is) = cti
        thet(ibl, is) = thi
        dstr(ibl, is) = dsi
        uedg(ibl, is) = uei
        mass(ibl, is) = dsi*uei
        tau(ibl, is) = 0.5*r2*u2*u2*cf2
        dis(ibl, is) = r2*u2*u2*u2*di2*hs2*0.5
        ctq(ibl, is) = cq2
        delt(ibl, is) = de2
        tstr(ibl, is) = hs2*t2
!
!------ set "1" variables to "2" variables for next streamwise station
        CALL BLPRV(xsi, ami, cti, thi, dsi, dswaki, uei)
        CALL BLKIN()
        CALL BLC_1FROM2()
!
!
!------ turbulent intervals will follow transition interval or TE
        IF (tran .OR. ibl .EQ. iblte(is)) THEN
          turb = .true.
!
!------- save transition location
          tforce(is) = trforc
          xssitr(is) = xt
        END IF
!
        tran = .false.
      END DO
!
!
!---- XFOILAD: cycle of the transition interval (see i_xfoil)
      IF (itran(is) .NE. itrold) THEN
        xad_trstab = -1
        IF (itran(is) - itrold .GE. 0.) THEN
          abs0 = itran(is) - itrold
        ELSE
          abs0 = -(itran(is)-itrold)
        END IF
        IF (itran(is) .EQ. xad_trprv(is) .AND. abs0 .EQ. 1) THEN
          xad_trnfl(is) = xad_trnfl(is) + 1
          IF (xad_trnfl(is) .GE. xad_trnflmax) THEN
            IF (xad_rlxcap*xad_rlxfac .LT. xad_rlxmin) THEN
              xad_rlxcap = xad_rlxmin
            ELSE
              xad_rlxcap = xad_rlxcap*xad_rlxfac
            END IF
            IF (show_output) WRITE(*, *) &
&                            'MRCHDU: transition cycle on side', is, &
&                            ', Newton step limited to', xad_rlxcap
          END IF
        END IF
        xad_trprv(is) = itrold
      END IF
      xad_mfprv(is) = xad_mfcur(is)
    END DO
!
!
!---- XFOILAD: transition intervals unchanged for xad_trnstab iterations:
!     the step limit is released progressively (factor 2 per stable period)
    xad_trstab = xad_trstab + 1
    IF (xad_trstab .GE. xad_trnstab .AND. xad_rlxcap .LT. 1.0) THEN
      IF (2.0*xad_rlxcap .GT. 1.0) THEN
        xad_rlxcap = 1.0
      ELSE
        xad_rlxcap = 2.0*xad_rlxcap
      END IF
      xad_trstab = 0
    END IF
99001 FORMAT(' MRCHDU: Convergence failed at', i4, '  side', i2, &
&          '    Res =', e12.4)
  END FUNCTION MRCHDU

!  Differentiation of xifset in reverse (adjoint) mode (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILIN_XW PSWLIN QDC
!ALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLCALC CDCALC CPCA
!LC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile):
!   gradient     of useful results: xiforc xssi s xte x y yle w1
!                w3 sle xle yte sst
