!                xle yte sst
!*==XIFSET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE XIFSET_B(is)
    USE M_SPLINE_DIFF, ONLY : splind, splind_fwd, splind_bwd, sinvrt, sinvrt_fwd, sinvrt_bwd
    USE I_XFOIL_DIFF
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: is
! intent (in) Is
!
! Local variables
!
    REAL :: chsq, chx, chy, str
    REAL :: chsqb, chxb, chyb, strb
    INTEGER :: i
    INTRINSIC MIN
    REAL :: tempb
    INTEGER :: branch
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------
!     Sets forced-transition BL coordinate locations.
!-----------------------------------------------------
!
    IF (xstrip(is) .GE. 1.0) THEN
      xssib(iblte(is), is) = xssib(iblte(is), is) + xiforcb
    ELSE
!
      chx = xte - xle
      chy = yte - yle
      chsq = chx**2 + chy**2
!
!---- calculate chord-based x/c, y/c
      DO i=1,n
        w1(i) = ((x(i)-xle)*chx+(y(i)-yle)*chy)/chsq
      END DO
!
      CALL SPLIND_FWD(w1, w3, s, n, -999.0, -999.0)
!
      IF (is .EQ. 1) THEN
!
!----- set approximate arc length of forced transition point for SINVRT
        str = sle + (s(1)-sle)*xstrip(is)
!
!----- calculate actual arc length
        CALL SINVRT_FWD(str, xstrip(is), w1, w3, s, n)
        IF (sst - str .GT. xssi(iblte(is), is)) THEN
          CALL PUSHREAL8(xiforc)
          xiforc = xssi(iblte(is), is)
          CALL PUSHCONTROL2B(1)
        ELSE
          CALL PUSHREAL8(xiforc)
          xiforc = sst - str
          CALL PUSHCONTROL2B(0)
        END IF
      ELSE
!----- same for bottom side
!
        str = sle + (s(n)-sle)*xstrip(is)
        CALL SINVRT_FWD(str, xstrip(is), w1, w3, s, n)
        IF (str - sst .GT. xssi(iblte(is), is)) THEN
          CALL PUSHREAL8(xiforc)
          xiforc = xssi(iblte(is), is)
          CALL PUSHCONTROL2B(3)
        ELSE
          CALL PUSHREAL8(xiforc)
          xiforc = str - sst
          CALL PUSHCONTROL2B(2)
        END IF
      END IF
!
      IF (xiforc .LT. 0.0) THEN
        xssib(iblte(is), is) = xssib(iblte(is), is) + xiforcb
        xiforcb = 0.0_8
      END IF
      CALL POPCONTROL2B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(xiforc)
          sstb = sstb + xiforcb
          strb = -xiforcb
        ELSE
          CALL POPREAL8(xiforc)
          xssib(iblte(is), is) = xssib(iblte(is), is) + xiforcb
          strb = 0.0_8
        END IF
        CALL SINVRT_BWD(str, strb, xstrip(is), w1, w1b, w3, w3b, s, sb0&
&                 , n)
        sleb = sleb + (1.0-xstrip(is))*strb
        sb0(1) = sb0(1) + xstrip(is)*strb
      ELSE
        IF (branch .EQ. 2) THEN
          CALL POPREAL8(xiforc)
          strb = xiforcb
          sstb = sstb - xiforcb
        ELSE
          CALL POPREAL8(xiforc)
          xssib(iblte(is), is) = xssib(iblte(is), is) + xiforcb
          strb = 0.0_8
        END IF
        CALL SINVRT_BWD(str, strb, xstrip(is), w1, w1b, w3, w3b, s, sb0&
&                 , n)
        sleb = sleb + (1.0-xstrip(is))*strb
        sb0(n) = sb0(n) + xstrip(is)*strb
      END IF
      CALL SPLIND_BWD(w1, w1b, w3, w3b, s, sb0, n, -999.0, -999.0)
      chsqb = 0.0_8
      chxb = 0.0_8
      chyb = 0.0_8
      DO i=n,1,-1
        tempb = w1b(i)/chsq
        w1b(i) = 0.0_8
        xb0(i) = xb0(i) + chx*tempb
        xleb = xleb - chx*tempb
        chxb = chxb + (x(i)-xle)*tempb
        yb0(i) = yb0(i) + chy*tempb
        yleb = yleb - chy*tempb
        chyb = chyb + (y(i)-yle)*tempb
        chsqb = chsqb - ((x(i)-xle)*chx+(y(i)-yle)*chy)*tempb/chsq
      END DO
      chxb = chxb + 2*chx*chsqb
      chyb = chyb + 2*chy*chsqb
      yteb = yteb + chyb
      yleb = yleb - chyb
      xteb = xteb + chxb
      xleb = xleb - chxb
    END IF
99001 FORMAT(/' ***  Stagnation point is past trip on side', i2, '  ***'&
&         )
  END SUBROUTINE XIFSET_B

!*==XIFSET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE XIFSET(is)
    USE M_SPLINE_DIFF, ONLY : splind, sinvrt
    USE I_XFOIL_DIFF
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: is
! intent (in) Is
!
! Local variables
!
    REAL :: chsq, chx, chy, str
    INTEGER :: i
    INTRINSIC MIN
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------
!     Sets forced-transition BL coordinate locations.
!-----------------------------------------------------
!
    IF (xstrip(is) .GE. 1.0) THEN
      xiforc = xssi(iblte(is), is)
      RETURN
    ELSE
!
      chx = xte - xle
      chy = yte - yle
      chsq = chx**2 + chy**2
!
!---- calculate chord-based x/c, y/c
      DO i=1,n
        w1(i) = ((x(i)-xle)*chx+(y(i)-yle)*chy)/chsq
        w2(i) = ((y(i)-yle)*chx-(x(i)-xle)*chy)/chsq
      END DO
!
      CALL SPLIND(w1, w3, s, n, -999.0, -999.0)
      CALL SPLIND(w2, w4, s, n, -999.0, -999.0)
!
      IF (is .EQ. 1) THEN
!
!----- set approximate arc length of forced transition point for SINVRT
        str = sle + (s(1)-sle)*xstrip(is)
!
!----- calculate actual arc length
        CALL SINVRT(str, xstrip(is), w1, w3, s, n)
        IF (sst - str .GT. xssi(iblte(is), is)) THEN
          xiforc = xssi(iblte(is), is)
        ELSE
          xiforc = sst - str
        END IF
      ELSE
!----- same for bottom side
!
        str = sle + (s(n)-sle)*xstrip(is)
        CALL SINVRT(str, xstrip(is), w1, w3, s, n)
        IF (str - sst .GT. xssi(iblte(is), is)) THEN
          xiforc = xssi(iblte(is), is)
        ELSE
          xiforc = str - sst
        END IF
      END IF
!
      IF (xiforc .LT. 0.0) THEN
        IF (show_output) WRITE(*, 99001) is
        xiforc = xssi(iblte(is), is)
      END IF
    END IF
99001 FORMAT(/' ***  Stagnation point is past trip on side', i2, '  ***'&
&         )
  END SUBROUTINE XIFSET

