!                cl vdel uinv
!*==UPDATE.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE UPDATE_B()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ag, ag_ac, ag_ms, beta, beta_msq, bfac, bfac_msq, ca, cginc&
&   , clnew, cl_a, cl_ac, cl_ms, cpc_cpi, cpg1, cpg1_ac, cpg1_ms, cpg2, &
&   cpg2_ac, cpg2_ms, cpi_q, dac, dalmax, dalmin, dclmax, dclmin, dctau&
&   , ddstr, dhi, dlo, dmass, dn1, dn2, dn3, dn4, dsw, dswaki, dthet, &
&   duedg, dui, dui_ac, dx, dx_a, hklim, hstinv, msq, rdn1, rdn2, rdn3, &
&   rdn4, sa, ue_m, uinv_ac
    REAL :: agb, ag_acb, ag_msb, betab, beta_msqb, bfacb, bfac_msqb, cab&
&   , cgincb, clnewb, cl_ab, cl_acb, cl_msb, cpc_cpib, cpg1b, cpg1_acb, &
&   cpg1_msb, cpg2b, cpg2_acb, cpg2_msb, cpi_qb, dacb, dclminb, dctaub, &
&   ddstrb, dmassb, dn1b, dn2b, dn3b, dn4b, dswb, dswakib, dthetb, &
&   duedgb, duib, dui_acb, dxb, dx_ab, hstinvb, msqb, sab, ue_mb, &
&   uinv_acb
    INTEGER :: i, ibl, ip, is, iv, iw, j, jbl, js, jv, kbl
    REAL, DIMENSION(iqx) :: qnew, q_ac
    REAL, DIMENSION(iqx) :: qnewb, q_acb
    REAL, DIMENSION(ivx, 2) :: unew, u_ac
    REAL, DIMENSION(ivx, 2) :: unewb, u_acb
    INTRINSIC MAX
    INTRINSIC SIN
    INTRINSIC COS
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC FLOAT
    INTRINSIC MIN
    REAL :: abs0
    REAL :: abs0b
    REAL :: abs1
    REAL :: abs2
    REAL :: abs3
    REAL :: abs4
    REAL :: abs5
    REAL :: abs6
    REAL :: abs7
    REAL :: abs8
    REAL :: temp
    REAL :: temp0
    REAL :: tempb
    REAL :: tempb0
    REAL :: temp1
    REAL :: tempb1
    REAL :: temp2
    REAL :: tempb2
    INTEGER :: ad_to
    INTEGER :: branch
    INTEGER :: ad_to0
    INTEGER :: ad_to1
    INTEGER :: ad_to2
    INTEGER :: ad_to3
    INTEGER :: ad_to4
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
! XFOILAD: UNEW, U_AC, QNEW, Q_AC were EQUIVALENCEd to VA/VB as scratch
! memory in XFOIL; they are now plain local arrays (Tapenade-safe).
!------------------------------------------------------------------
!      Adds on Newton deltas to boundary layer variables.
!      Checks for excessive changes and underrelaxes if necessary.
!      Calculates max and rms changes.
!      Also calculates the change in the global variable "AC".
!        If LALFA=.TRUE. , "AC" is CL
!        If LALFA=.FALSE., "AC" is alpha
!------------------------------------------------------------------
!
!---- max allowable alpha changes per iteration
    dalmax = 0.5*dtor
    dalmin = -(0.5*dtor)
!
!---- max allowable CL change per iteration
    dclmax = 0.5
    dclmin = -0.5
    IF (matyp .NE. 1) THEN
      IF (-0.5 .LT. -(0.9*cl)) THEN
        dclmin = -(0.9*cl)
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHCONTROL2B(1)
        dclmin = -0.5
      END IF
    ELSE
      CALL PUSHCONTROL2B(0)
    END IF
!
    hstinv = gamm1*(minf/qinf)**2/(1.0+0.5*gamm1*minf**2)
!
!---- calculate new Ue distribution assuming no under-relaxation
!-    also set the sensitivity of Ue wrt to alpha or Re
    DO is=1,2
      DO ibl=2,nbl(is)
        i = ipan(ibl, is)
!
        dui = 0.
        dui_ac = 0.
        DO js=1,2
          DO jbl=2,nbl(js)
            j = ipan(jbl, js)
            jv = isys(jbl, js)
            ue_m = -(vti(ibl, is)*vti(jbl, js)*dij(i, j))
            dui = dui + ue_m*(mass(jbl, js)+vdel(3, 1, jv))
            dui_ac = dui_ac + ue_m*(-vdel(3, 2, jv))
          END DO
          CALL PUSHINTEGER4(jbl - 1)
        END DO
!
!-------- UINV depends on "AC" only if "AC" is alpha
        IF (lalfa) THEN
          CALL PUSHCONTROL1B(0)
          uinv_ac = 0.
        ELSE
          uinv_ac = uinv_a(ibl, is)
          CALL PUSHCONTROL1B(1)
        END IF
!
        unew(ibl, is) = uinv(ibl, is) + dui
        u_ac(ibl, is) = uinv_ac + dui_ac
      END DO
      CALL PUSHINTEGER4(ibl - 1)
    END DO
!
!
!---- set new Qtan from new Ue with appropriate sign change
    DO is=1,2
      DO ibl=2,iblte(is)
        i = ipan(ibl, is)
        qnew(i) = vti(ibl, is)*unew(ibl, is)
        q_ac(i) = vti(ibl, is)*u_ac(ibl, is)
      END DO
      CALL PUSHINTEGER4(ibl - 1)
    END DO
!
!---- calculate new CL from this new Qtan
    sa = SIN(alfa)
    ca = COS(alfa)
!
    beta = SQRT(1.0 - minf**2)
    beta_msq = -(0.5/beta)
!
    bfac = 0.5*minf**2/(1.0+beta)
    bfac_msq = 0.5/(1.0+beta) - bfac/(1.0+beta)*beta_msq
!
    clnew = 0.
    cl_a = 0.
    cl_ms = 0.
    cl_ac = 0.
!
    i = 1
    cginc = 1.0 - (qnew(i)/qinf)**2
    cpg1 = cginc/(beta+bfac*cginc)
    cpg1_ms = -(cpg1/(beta+bfac*cginc)*(beta_msq+bfac_msq*cginc))
!
    cpi_q = -(2.0*qnew(i)/qinf**2)
    cpc_cpi = (1.0-bfac*cpg1)/(beta+bfac*cginc)
    cpg1_ac = cpc_cpi*cpi_q*q_ac(i)
    CALL PUSHINTEGER4(i)
!
    DO i=1,n
      CALL PUSHINTEGER4(ip)
      ip = i + 1
      IF (i .EQ. n) ip = 1
!
      CALL PUSHREAL8(cginc)
      cginc = 1.0 - (qnew(ip)/qinf)**2
      CALL PUSHREAL8(cpg2)
      cpg2 = cginc/(beta+bfac*cginc)
      cpg2_ms = -(cpg2/(beta+bfac*cginc)*(beta_msq+bfac_msq*cginc))
!
      CALL PUSHREAL8(cpi_q)
      cpi_q = -(2.0*qnew(ip)/qinf**2)
      CALL PUSHREAL8(cpc_cpi)
      cpc_cpi = (1.0-bfac*cpg2)/(beta+bfac*cginc)
      cpg2_ac = cpc_cpi*cpi_q*q_ac(ip)
!
      dx = (x(ip)-x(i))*ca + (y(ip)-y(i))*sa
      dx_a = -((x(ip)-x(i))*sa) + (y(ip)-y(i))*ca
!
      ag = 0.5*(cpg2+cpg1)
      CALL PUSHREAL8(ag_ms)
      ag_ms = 0.5*(cpg2_ms+cpg1_ms)
      CALL PUSHREAL8(ag_ac)
      ag_ac = 0.5*(cpg2_ac+cpg1_ac)
!
      clnew = clnew + dx*ag
      cl_a = cl_a + dx_a*ag
      cl_ms = cl_ms + dx*ag_ms
      cl_ac = cl_ac + dx*ag_ac
!
      CALL PUSHREAL8(cpg1)
      cpg1 = cpg2
      cpg1_ms = cpg2_ms
      cpg1_ac = cpg2_ac
    END DO
!
!---- initialize under-relaxation factor
    rlx = 1.0
!
    IF (lalfa) THEN
!===== alpha is prescribed: AC is CL
!
!----- set change in Re to account for CL changing, since Re = Re(CL)
      dac = (clnew-cl)/(1.0-cl_ac-cl_ms*2.0*minf*minf_cl)
!
!----- set under-relaxation factor if Re change is too large
      IF (rlx*dac .GT. dclmax) THEN
        rlx = dclmax/dac
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (rlx*dac .LT. dclmin) THEN
        rlx = dclmin/dac
        CALL PUSHCONTROL2B(0)
      ELSE
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
!
!===== CL is prescribed: AC is alpha
!
!----- set change in alpha to drive CL to prescribed value
      dac = (clnew-clspec)/(0.0-cl_ac-cl_a)
!
!----- set under-relaxation factor if alpha change is too large
      IF (rlx*dac .GT. dalmax) THEN
        rlx = dalmax/dac
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (rlx*dac .LT. dalmin) THEN
        rlx = dalmin/dac
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHCONTROL2B(3)
      END IF
    END IF
!
