!-------- normalize changes
        IF (ibl .LT. itran(is)) THEN
          CALL PUSHREAL8(dn1)
          dn1 = dctau/10.0
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (ibl .GE. itran(is)) THEN
          CALL PUSHREAL8(dn1)
          dn1 = dctau/ctau(ibl, is)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        dn2 = dthet/thet(ibl, is)
        dn3 = ddstr/dstr(ibl, is)
        IF (duedg .GE. 0.) THEN
          abs0 = duedg
          CALL PUSHCONTROL1B(0)
        ELSE
          abs0 = -duedg
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(dn4)
        dn4 = abs0/0.25
!
!-------- accumulate for rms change
!
!-------- see if Ctau needs underrelaxation
        rdn1 = rlx*dn1
        IF (rdn1 .GT. dhi) THEN
          rlx = dhi/dn1
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (rdn1 .LT. dlo) THEN
          rlx = dlo/dn1
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
!
!-------- see if Theta needs underrelaxation
        rdn2 = rlx*dn2
        IF (rdn2 .GT. dhi) THEN
          rlx = dhi/dn2
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (rdn2 .LT. dlo) THEN
          rlx = dlo/dn2
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
!
!-------- see if Dstar needs underrelaxation
        rdn3 = rlx*dn3
        IF (rdn3 .GT. dhi) THEN
          rlx = dhi/dn3
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (rdn3 .LT. dlo) THEN
          rlx = dlo/dn3
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
!
!-------- see if Ue needs underrelaxation
        rdn4 = rlx*dn4
        IF (rdn4 .GT. dhi) THEN
          rlx = dhi/dn4
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (rdn4 .LT. dlo) THEN
          rlx = dlo/dn4
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHINTEGER4(ibl - 1)
    END DO
!
!
!---- set true rms change
!
!---- XFOILAD: under-relaxation after a cycle of the transition interval
    IF (rlx .GT. xad_rlxcap) THEN
      rlx = xad_rlxcap
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!
    IF (lalfa) THEN
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHCONTROL1B(0)
    END IF
!
!---- update BL variables with underrelaxed changes
    DO is=1,2
      DO ibl=2,nbl(is)
        iv = isys(ibl, is)
!
        dctau = vdel(1, 1, iv) - dac*vdel(1, 2, iv)
        dthet = vdel(2, 1, iv) - dac*vdel(2, 2, iv)
        dmass = vdel(3, 1, iv) - dac*vdel(3, 2, iv)
        CALL PUSHREAL8(duedg)
        duedg = unew(ibl, is) + dac*u_ac(ibl, is) - uedg(ibl, is)
        CALL PUSHREAL8(ddstr)
        ddstr = (dmass-dstr(ibl, is)*duedg)/uedg(ibl, is)
!
        CALL PUSHREAL8(ctau(ibl, is))
        ctau(ibl, is) = ctau(ibl, is) + rlx*dctau
        CALL PUSHREAL8(thet(ibl, is))
        thet(ibl, is) = thet(ibl, is) + rlx*dthet
        CALL PUSHREAL8(dstr(ibl, is))
        dstr(ibl, is) = dstr(ibl, is) + rlx*ddstr
        CALL PUSHREAL8(uedg(ibl, is))
        uedg(ibl, is) = uedg(ibl, is) + rlx*duedg
!
        IF (ibl .GT. iblte(is)) THEN
          CALL PUSHINTEGER4(iw)
          iw = ibl - iblte(is)
          dswaki = wgap(iw)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
          dswaki = 0.
        END IF
!
!-------- eliminate absurd transients
        IF (ibl .GE. itran(is)) THEN
          IF (ctau(ibl, is) .GT. 0.25) THEN
            CALL PUSHCONTROL2B(2)
          ELSE
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
          CALL PUSHCONTROL2B(0)
        END IF
!
        IF (ibl .LE. iblte(is)) THEN
          CALL PUSHREAL8(hklim)
          hklim = 1.02
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(hklim)
          hklim = 1.00005
          CALL PUSHCONTROL1B(1)
        END IF
        CALL PUSHREAL8(msq)
        msq = uedg(ibl, is)**2*hstinv/(gamm1*(1.0-0.5*uedg(ibl, is)**2*&
&         hstinv))
        dsw = dstr(ibl, is) - dswaki
        CALL PUSHREAL8(dsw)
        CALL DSLIM(dsw, thet(ibl, is), uedg(ibl, is), msq, hklim)
        dstr(ibl, is) = dsw + dswaki
!
!-------- set new mass defect (nonlinear update)
      END DO
      CALL PUSHINTEGER4(ibl - 1)
!
!
!------ make sure there are no "islands" of negative Ue
      DO ibl=3,iblte(is)
        IF (uedg(ibl-1, is) .GT. 0.0 .AND. uedg(ibl, is) .LE. 0.0) THEN
          CALL PUSHREAL8(uedg(ibl, is))
          uedg(ibl, is) = uedg(ibl-1, is)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHINTEGER4(ibl - 1)
    END DO
    DO kbl=nbl(2)-iblte(2),1,-1
      taub(iblte(2)+kbl, 2) = taub(iblte(2)+kbl, 2) + taub(iblte(1)+kbl&
&       , 1)
      taub(iblte(1)+kbl, 1) = 0.0_8
      uedgb(iblte(2)+kbl, 2) = uedgb(iblte(2)+kbl, 2) + uedgb(iblte(1)+&
&       kbl, 1)
      uedgb(iblte(1)+kbl, 1) = 0.0_8
      dstrb(iblte(2)+kbl, 2) = dstrb(iblte(2)+kbl, 2) + dstrb(iblte(1)+&
&       kbl, 1)
      dstrb(iblte(1)+kbl, 1) = 0.0_8
      thetb(iblte(2)+kbl, 2) = thetb(iblte(2)+kbl, 2) + thetb(iblte(1)+&
&       kbl, 1)
      thetb(iblte(1)+kbl, 1) = 0.0_8
      ctaub(iblte(2)+kbl, 2) = ctaub(iblte(2)+kbl, 2) + ctaub(iblte(1)+&
&       kbl, 1)
      ctaub(iblte(1)+kbl, 1) = 0.0_8
    END DO
    rlxb = 0.0_8
    dacb = 0.0_8
    unewb = 0.0_8
    hstinvb = 0.0_8
    u_acb = 0.0_8
    DO is=2,1,-1
      CALL POPINTEGER4(ad_to4)
      DO ibl=ad_to4,3,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          dstrb(ibl, is) = dstrb(ibl, is) + uedg(ibl, is)*massb(ibl, is)
          uedgb(ibl, is) = uedgb(ibl, is) + dstr(ibl, is)*massb(ibl, is)
          massb(ibl, is) = 0.0_8
          CALL POPREAL8(uedg(ibl, is))
          uedgb(ibl-1, is) = uedgb(ibl-1, is) + uedgb(ibl, is)
          uedgb(ibl, is) = 0.0_8
        END IF
      END DO
      CALL POPINTEGER4(ad_to3)
      DO ibl=ad_to3,2,-1
        dstrb(ibl, is) = dstrb(ibl, is) + uedg(ibl, is)*massb(ibl, is)
        dswb = dstrb(ibl, is)
        CALL POPREAL8(dsw)
        CALL DSLIM_B(dsw, dswb, thet(ibl, is), thetb(ibl, is), uedg(ibl&
&              , is), msq, msqb, hklim)
        dswakib = dstrb(ibl, is) - dswb
        dstrb(ibl, is) = dswb
        CALL POPREAL8(msq)
        temp1 = uedg(ibl, is)*uedg(ibl, is)
        temp0 = gamm1*(-(0.5*temp1*hstinv)+1.0)
        temp2 = uedg(ibl, is)*uedg(ibl, is)
        tempb0 = msqb/temp0
        tempb2 = 0.5*gamm1*temp2*hstinv*tempb0/temp0
        uedgb(ibl, is) = uedgb(ibl, is) + dstr(ibl, is)*massb(ibl, is) +&
&         2*uedg(ibl, is)*hstinv*tempb0 + 2*uedg(ibl, is)*hstinv*tempb2
        massb(ibl, is) = 0.0_8
        hstinvb = hstinvb + temp2*tempb0 + temp1*tempb2
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(hklim)
        ELSE
          CALL POPREAL8(hklim)
        END IF
        CALL POPCONTROL2B(branch)
        IF (branch .NE. 0) THEN
          IF (branch .NE. 1) ctaub(ibl, is) = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          wgapb(iw) = wgapb(iw) + dswakib
          CALL POPINTEGER4(iw)
        END IF
        iv = isys(ibl, is)
        dthet = vdel(2, 1, iv) - dac*vdel(2, 2, iv)
        dctau = vdel(1, 1, iv) - dac*vdel(1, 2, iv)
        CALL POPREAL8(uedg(ibl, is))
        rlxb = rlxb + duedg*uedgb(ibl, is) + ddstr*dstrb(ibl, is) + &
&         dthet*thetb(ibl, is) + dctau*ctaub(ibl, is)
        dmass = vdel(3, 1, iv) - dac*vdel(3, 2, iv)
        CALL POPREAL8(dstr(ibl, is))
        ddstrb = rlx*dstrb(ibl, is)
        CALL POPREAL8(thet(ibl, is))
        dthetb = rlx*thetb(ibl, is)
        CALL POPREAL8(ctau(ibl, is))
        dctaub = rlx*ctaub(ibl, is)
        CALL POPREAL8(ddstr)
        tempb1 = ddstrb/uedg(ibl, is)
        duedgb = rlx*uedgb(ibl, is) - dstr(ibl, is)*tempb1
        dmassb = tempb1
        dstrb(ibl, is) = dstrb(ibl, is) - duedg*tempb1
        uedgb(ibl, is) = uedgb(ibl, is) - (dmass-dstr(ibl, is)*duedg)*&
&         tempb1/uedg(ibl, is) - duedgb
        CALL POPREAL8(duedg)
        unewb(ibl, is) = unewb(ibl, is) + duedgb
        dacb = dacb + u_ac(ibl, is)*duedgb - vdel(3, 2, iv)*dmassb - &
&         vdel(2, 2, iv)*dthetb - vdel(1, 2, iv)*dctaub
        u_acb(ibl, is) = u_acb(ibl, is) + dac*duedgb
        vdelb(3, 1, iv) = vdelb(3, 1, iv) + dmassb
        vdelb(3, 2, iv) = vdelb(3, 2, iv) - dac*dmassb
        vdelb(2, 1, iv) = vdelb(2, 1, iv) + dthetb
        vdelb(2, 2, iv) = vdelb(2, 2, iv) - dac*dthetb
        vdelb(1, 1, iv) = vdelb(1, 1, iv) + dctaub
        vdelb(1, 2, iv) = vdelb(1, 2, iv) - dac*dctaub
      END DO
    END DO
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      rlxb = rlxb + dac*alfab
      dacb = dacb + rlx*alfab
    ELSE
      rlxb = rlxb + dac*clb
      dacb = dacb + rlx*clb
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) rlxb = 0.0_8
    dn1b = 0.0_8
    DO is=2,1,-1
      CALL POPINTEGER4(ad_to2)
      DO ibl=ad_to2,2,-1
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn4b = 0.0_8
        ELSE
          dn4b = -(dlo*rlxb/dn4**2)
          rlxb = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn4b = dn4b - dhi*rlxb/dn4**2
          rlxb = 0.0_8
        END IF
        iv = isys(ibl, is)
        dmass = vdel(3, 1, iv) - dac*vdel(3, 2, iv)
        ddstr = (dmass-dstr(ibl, is)*duedg)/uedg(ibl, is)
        dn3 = ddstr/dstr(ibl, is)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn3b = 0.0_8
        ELSE
          dn3b = -(dlo*rlxb/dn3**2)
          rlxb = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn3b = dn3b - dhi*rlxb/dn3**2
          rlxb = 0.0_8
        END IF
        dthet = vdel(2, 1, iv) - dac*vdel(2, 2, iv)
        dn2 = dthet/thet(ibl, is)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn2b = 0.0_8
        ELSE
          dn2b = -(dlo*rlxb/dn2**2)
          rlxb = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn2b = dn2b - dhi*rlxb/dn2**2
          rlxb = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          dn1b = dn1b - dlo*rlxb/dn1**2
          rlxb = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dn1b = dn1b - dhi*rlxb/dn1**2
          rlxb = 0.0_8
        END IF
        CALL POPREAL8(dn4)
        abs0b = dn4b/0.25
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          duedgb = abs0b
        ELSE
          duedgb = -abs0b
        END IF
        tempb1 = dn3b/dstr(ibl, is)
        ddstrb = tempb1
        dstrb(ibl, is) = dstrb(ibl, is) - ddstr*tempb1/dstr(ibl, is)
        tempb1 = dn2b/thet(ibl, is)
        dthetb = tempb1
        thetb(ibl, is) = thetb(ibl, is) - dthet*tempb1/thet(ibl, is)
        dctau = vdel(1, 1, iv) - dac*vdel(1, 2, iv)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          dctaub = 0.0_8
        ELSE
          CALL POPREAL8(dn1)
          tempb1 = dn1b/ctau(ibl, is)
          dctaub = tempb1
          ctaub(ibl, is) = ctaub(ibl, is) - dctau*tempb1/ctau(ibl, is)
          dn1b = 0.0_8
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(dn1)
          dctaub = dctaub + dn1b/10.0
          dn1b = 0.0_8
        END IF
        tempb1 = ddstrb/uedg(ibl, is)
        dmassb = tempb1
        dstrb(ibl, is) = dstrb(ibl, is) - duedg*tempb1
        duedgb = duedgb - dstr(ibl, is)*tempb1
        uedgb(ibl, is) = uedgb(ibl, is) - (dmass-dstr(ibl, is)*duedg)*&
&         tempb1/uedg(ibl, is) - duedgb
        CALL POPREAL8(duedg)
        unewb(ibl, is) = unewb(ibl, is) + duedgb
        dacb = dacb + u_ac(ibl, is)*duedgb - vdel(3, 2, iv)*dmassb - &
&         vdel(2, 2, iv)*dthetb - vdel(1, 2, iv)*dctaub
        u_acb(ibl, is) = u_acb(ibl, is) + dac*duedgb
        vdelb(3, 1, iv) = vdelb(3, 1, iv) + dmassb
        vdelb(3, 2, iv) = vdelb(3, 2, iv) - dac*dmassb
        vdelb(2, 1, iv) = vdelb(2, 1, iv) + dthetb
        vdelb(2, 2, iv) = vdelb(2, 2, iv) - dac*dthetb
        vdelb(1, 1, iv) = vdelb(1, 1, iv) + dctaub
        vdelb(1, 2, iv) = vdelb(1, 2, iv) - dac*dctaub
      END DO
    END DO
    CALL POPCONTROL2B(branch)
    IF (branch .LT. 2) THEN
      IF (branch .EQ. 0) THEN
        dclminb = rlxb/dac
        dacb = dacb - dclmin*rlxb/dac**2
        rlxb = 0.0_8
      ELSE
        dclminb = 0.0_8
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) dacb = dacb - dclmax*rlxb/dac**2
      temp1 = -(2.0*cl_ms*minf*minf_cl) - cl_ac + 1.0
      tempb = dacb/temp1
      clnewb = tempb
      clb = clb - tempb
      tempb1 = -((clnew-cl)*tempb/temp1)
      tempb0 = -(minf_cl*2.0*tempb1)
      minf_clb = minf_clb - cl_ms*minf*2.0*tempb1
      cl_acb = -tempb1
      cl_msb = minf*tempb0
      minfb = minfb + cl_ms*tempb0
      cl_ab = 0.0_8
    ELSE
      IF (branch .EQ. 2) THEN
        dacb = dacb - dalmin*rlxb/dac**2
        rlxb = 0.0_8
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) dacb = dacb - dalmax*rlxb/dac**2
      tempb1 = dacb/(-cl_ac-cl_a)
      clnewb = tempb1
      clspecb = clspecb - tempb1
      tempb = -((clnew-clspec)*tempb1/(-cl_ac-cl_a))
      cl_acb = -tempb
      cl_ab = -tempb
      dclminb = 0.0_8
      cl_msb = 0.0_8
    END IF
    cpg1_msb = 0.0_8
    cpg1_acb = 0.0_8
    bfac_msqb = 0.0_8
    qnewb = 0.0_8
    bfacb = 0.0_8
    sab = 0.0_8
    cab = 0.0_8
    betab = 0.0_8
    beta_msqb = 0.0_8
    cpg1b = 0.0_8
    q_acb = 0.0_8
    DO i=n,1,-1
      dx = (x(ip)-x(i))*ca + (y(ip)-y(i))*sa
      ag_acb = dx*cl_acb
      ag_msb = dx*cl_msb
      cpg2_acb = cpg1_acb + 0.5*ag_acb
      cpg2_msb = cpg1_msb + 0.5*ag_msb
      CALL POPREAL8(cpg1)
      ag = 0.5*(cpg2+cpg1)
      dxb = ag_ac*cl_acb + ag_ms*cl_msb + ag*clnewb
      dx_a = -((x(ip)-x(i))*sa) + (y(ip)-y(i))*ca
      dx_ab = ag*cl_ab
      agb = dx_a*cl_ab + dx*clnewb
      CALL POPREAL8(ag_ac)
      cpg1_acb = 0.5*ag_acb
      CALL POPREAL8(ag_ms)
      cpg1_msb = 0.5*ag_msb
      yb0(ip) = yb0(ip) + ca*dx_ab
      yb0(i) = yb0(i) - ca*dx_ab
      cab = cab + (y(ip)-y(i))*dx_ab + (x(ip)-x(i))*dxb
      xb0(ip) = xb0(ip) - sa*dx_ab
      xb0(i) = xb0(i) + sa*dx_ab
      sab = sab + (y(ip)-y(i))*dxb - (x(ip)-x(i))*dx_ab
      xb0(ip) = xb0(ip) + ca*dxb
      xb0(i) = xb0(i) - ca*dxb
      yb0(ip) = yb0(ip) + sa*dxb
      yb0(i) = yb0(i) - sa*dxb
      cpc_cpib = cpi_q*q_ac(ip)*cpg2_acb
      cpi_qb = cpc_cpi*q_ac(ip)*cpg2_acb
      q_acb(ip) = q_acb(ip) + cpc_cpi*cpi_q*cpg2_acb
      CALL POPREAL8(cpc_cpi)
      tempb1 = cpc_cpib/(beta+bfac*cginc)
      cpg2b = cpg1b + 0.5*agb - bfac*tempb1
      cpg1b = 0.5*agb
      tempb = -((1.0-bfac*cpg2)*tempb1/(beta+bfac*cginc))
      bfacb = bfacb + cginc*tempb - cpg2*tempb1
      betab = betab + tempb
      cgincb = bfac*tempb
      CALL POPREAL8(cpi_q)
      tempb1 = -(cpg2_msb/(beta+bfac*cginc))
      cpg2b = cpg2b + (beta_msq+bfac_msq*cginc)*tempb1
      tempb = cpg2*tempb1
      tempb0 = -(cpg2*(beta_msq+bfac_msq*cginc)*tempb1/(beta+bfac*cginc)&
&       )
      cgincb = cgincb + bfac*tempb0 + bfac_msq*tempb
      beta_msqb = beta_msqb + tempb
      bfac_msqb = bfac_msqb + cginc*tempb
      CALL POPREAL8(cpg2)
      tempb1 = cpg2b/(beta+bfac*cginc)
      tempb = -(cginc*tempb1/(beta+bfac*cginc))
      betab = betab + tempb0 + tempb
      bfacb = bfacb + cginc*tempb0 + cginc*tempb
      cgincb = cgincb + tempb1 + bfac*tempb
      qnewb(ip) = qnewb(ip) - 2.0*cpi_qb/qinf**2 - 2*qnew(ip)*cgincb/&
&       qinf**2
      CALL POPREAL8(cginc)
      CALL POPINTEGER4(ip)
    END DO
    CALL POPINTEGER4(i)
    cpc_cpib = cpi_q*q_ac(i)*cpg1_acb
    cpi_qb = cpc_cpi*q_ac(i)*cpg1_acb
    q_acb(i) = q_acb(i) + cpc_cpi*cpi_q*cpg1_acb
    tempb1 = cpc_cpib/(beta+bfac*cginc)
    tempb = -((1.0-bfac*cpg1)*tempb1/(beta+bfac*cginc))
    bfacb = bfacb + cginc*tempb - cpg1*tempb1
    betab = betab + tempb
    cgincb = bfac*tempb
    tempb = -(cpg1_msb/(beta+bfac*cginc))
    cpg1b = cpg1b + (beta_msq+bfac_msq*cginc)*tempb - bfac*tempb1
    tempb0 = cpg1*tempb
    tempb1 = -(cpg1*(beta_msq+bfac_msq*cginc)*tempb/(beta+bfac*cginc))
    cgincb = cgincb + bfac*tempb1 + bfac_msq*tempb0
    beta_msqb = beta_msqb + tempb0
    bfac_msqb = bfac_msqb + cginc*tempb0
    tempb = cpg1b/(beta+bfac*cginc)
    tempb0 = -(cginc*tempb/(beta+bfac*cginc))
    cgincb = cgincb + tempb + bfac*tempb0
    qnewb(i) = qnewb(i) - 2.0*cpi_qb/qinf**2 - 2*qnew(i)*cgincb/qinf**2
    tempb = -(bfac_msqb/(beta+1.0))
    betab = betab + tempb1 + tempb0 - 0.5*bfac_msqb/(beta+1.0)**2 - bfac&
&     *beta_msq*tempb/(beta+1.0)
    bfacb = bfacb + cginc*tempb1 + cginc*tempb0 + beta_msq*tempb
    beta_msqb = beta_msqb + bfac*tempb
    tempb = 0.5*bfacb/(beta+1.0)
    betab = betab + 0.5*beta_msqb/beta**2 - minf**2*tempb/(beta+1.0)
    IF (1.0 - minf**2 .EQ. 0.0_8) THEN
      minfb = minfb + 2*minf*tempb
    ELSE
      minfb = minfb + 2*minf*tempb - 2*minf*betab/(2.0*SQRT(1.0-minf**2)&
&       )
    END IF
    alfab = alfab + COS(alfa)*sab - SIN(alfa)*cab
    DO is=2,1,-1
      CALL POPINTEGER4(ad_to1)
      DO ibl=ad_to1,2,-1
        i = ipan(ibl, is)
        u_acb(ibl, is) = u_acb(ibl, is) + vti(ibl, is)*q_acb(i)
        q_acb(i) = 0.0_8
        unewb(ibl, is) = unewb(ibl, is) + vti(ibl, is)*qnewb(i)
        qnewb(i) = 0.0_8
      END DO
    END DO
    DO is=2,1,-1
      CALL POPINTEGER4(ad_to0)
      DO ibl=ad_to0,2,-1
        uinv_acb = u_acb(ibl, is)
        dui_acb = u_acb(ibl, is)
        u_acb(ibl, is) = 0.0_8
        uinvb(ibl, is) = uinvb(ibl, is) + unewb(ibl, is)
        duib = unewb(ibl, is)
        unewb(ibl, is) = 0.0_8
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) uinv_ab(ibl, is) = uinv_ab(ibl, is) + &
&           uinv_acb
        i = ipan(ibl, is)
        DO js=2,1,-1
          CALL POPINTEGER4(ad_to)
          DO jbl=ad_to,2,-1
            jv = isys(jbl, js)
            j = ipan(jbl, js)
            ue_m = -(vti(ibl, is)*vti(jbl, js)*dij(i, j))
            ue_mb = (mass(jbl, js)+vdel(3, 1, jv))*duib - vdel(3, 2, jv)&
&             *dui_acb
            vdelb(3, 2, jv) = vdelb(3, 2, jv) - ue_m*dui_acb
            massb(jbl, js) = massb(jbl, js) + ue_m*duib
            vdelb(3, 1, jv) = vdelb(3, 1, jv) + ue_m*duib
            dijb(i, j) = dijb(i, j) - vti(ibl, is)*vti(jbl, js)*ue_mb
          END DO
        END DO
      END DO
    END DO
    temp = qinf*qinf*(0.5*gamm1*(minf*minf)+1.0)
    tempb = gamm1*hstinvb/temp
    minfb = minfb + (2*minf-2*minf**3*gamm1*0.5*qinf**2/temp)*tempb
    CALL POPCONTROL2B(branch)
    IF (branch .NE. 0) THEN
      IF (branch .NE. 1) clb = clb - 0.9*dclminb
    END IF
  END SUBROUTINE UPDATE_B

!*==UPDATE.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE UPDATE()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ag, ag_ac, ag_ms, beta, beta_msq, bfac, bfac_msq, ca, cginc&
&   , clnew, cl_a, cl_ac, cl_ms, cpc_cpi, cpg1, cpg1_ac, cpg1_ms, cpg2, &
&   cpg2_ac, cpg2_ms, cpi_q, dac, dalmax, dalmin, dclmax, dclmin, dctau&
&   , ddstr, dhi, dlo, dmass, dn1, dn2, dn3, dn4, dsw, dswaki, dthet, &
&   duedg, dui, dui_ac, dx, dx_a, hklim, hstinv, msq, rdn1, rdn2, rdn3, &
&   rdn4, sa, ue_m, uinv_ac
    INTEGER :: i, ibl, ip, is, iv, iw, j, jbl, js, jv, kbl
    REAL, DIMENSION(iqx) :: qnew, q_ac
    REAL, DIMENSION(ivx, 2) :: unew, u_ac
    INTRINSIC MAX
    INTRINSIC SIN
    INTRINSIC COS
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC FLOAT
    INTRINSIC MIN
    REAL :: abs0
    REAL :: abs1
    REAL :: abs2
    REAL :: abs3
    REAL :: abs4
    REAL :: abs5
    REAL :: abs6
    REAL :: abs7
    REAL :: abs8
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
! XFOILAD: UNEW, U_AC, QNEW, Q_AC were EQUIVALENCEd to VA/VB as scratch
! memory in XFOIL; they are now plain local arrays (Tapenade-safe).
!------------------------------------------------------------------
!      Adds on Newton deltas to boundary layer variables.
!      Checks for excessive changes and underrelaxes if necessary.
!      Calculates max and rms changes.
!      Also calculates the change in the global variable "AC".
!        If LALFA=.TRUE. , "AC" is CL
!        If LALFA=.FALSE., "AC" is alpha
!------------------------------------------------------------------
!
!---- max allowable alpha changes per iteration
    dalmax = 0.5*dtor
    dalmin = -(0.5*dtor)
!
!---- max allowable CL change per iteration
    dclmax = 0.5
    dclmin = -0.5
    IF (matyp .NE. 1) THEN
      IF (-0.5 .LT. -(0.9*cl)) THEN
        dclmin = -(0.9*cl)
      ELSE
        dclmin = -0.5
      END IF
    END IF
!
    hstinv = gamm1*(minf/qinf)**2/(1.0+0.5*gamm1*minf**2)
!
!---- calculate new Ue distribution assuming no under-relaxation
!-    also set the sensitivity of Ue wrt to alpha or Re
    DO is=1,2
      DO ibl=2,nbl(is)
        i = ipan(ibl, is)
!
        dui = 0.
        dui_ac = 0.
        DO js=1,2
          DO jbl=2,nbl(js)
            j = ipan(jbl, js)
            jv = isys(jbl, js)
            ue_m = -(vti(ibl, is)*vti(jbl, js)*dij(i, j))
            dui = dui + ue_m*(mass(jbl, js)+vdel(3, 1, jv))
            dui_ac = dui_ac + ue_m*(-vdel(3, 2, jv))
          END DO
        END DO
!
!-------- UINV depends on "AC" only if "AC" is alpha
        IF (lalfa) THEN
          uinv_ac = 0.
        ELSE
          uinv_ac = uinv_a(ibl, is)
        END IF
!
        unew(ibl, is) = uinv(ibl, is) + dui
        u_ac(ibl, is) = uinv_ac + dui_ac
      END DO
    END DO
!
!
!---- set new Qtan from new Ue with appropriate sign change
    DO is=1,2
      DO ibl=2,iblte(is)
        i = ipan(ibl, is)
        qnew(i) = vti(ibl, is)*unew(ibl, is)
        q_ac(i) = vti(ibl, is)*u_ac(ibl, is)
      END DO
    END DO
!
!---- calculate new CL from this new Qtan
    sa = SIN(alfa)
    ca = COS(alfa)
!
    beta = SQRT(1.0 - minf**2)
    beta_msq = -(0.5/beta)
!
    bfac = 0.5*minf**2/(1.0+beta)
    bfac_msq = 0.5/(1.0+beta) - bfac/(1.0+beta)*beta_msq
!
    clnew = 0.
    cl_a = 0.
    cl_ms = 0.
    cl_ac = 0.
!
    i = 1
    cginc = 1.0 - (qnew(i)/qinf)**2
    cpg1 = cginc/(beta+bfac*cginc)
    cpg1_ms = -(cpg1/(beta+bfac*cginc)*(beta_msq+bfac_msq*cginc))
!
    cpi_q = -(2.0*qnew(i)/qinf**2)
    cpc_cpi = (1.0-bfac*cpg1)/(beta+bfac*cginc)
    cpg1_ac = cpc_cpi*cpi_q*q_ac(i)
!
    DO i=1,n
      ip = i + 1
      IF (i .EQ. n) ip = 1
!
      cginc = 1.0 - (qnew(ip)/qinf)**2
      cpg2 = cginc/(beta+bfac*cginc)
      cpg2_ms = -(cpg2/(beta+bfac*cginc)*(beta_msq+bfac_msq*cginc))
!
      cpi_q = -(2.0*qnew(ip)/qinf**2)
      cpc_cpi = (1.0-bfac*cpg2)/(beta+bfac*cginc)
      cpg2_ac = cpc_cpi*cpi_q*q_ac(ip)
!
      dx = (x(ip)-x(i))*ca + (y(ip)-y(i))*sa
      dx_a = -((x(ip)-x(i))*sa) + (y(ip)-y(i))*ca
!
      ag = 0.5*(cpg2+cpg1)
      ag_ms = 0.5*(cpg2_ms+cpg1_ms)
      ag_ac = 0.5*(cpg2_ac+cpg1_ac)
!
      clnew = clnew + dx*ag
      cl_a = cl_a + dx_a*ag
      cl_ms = cl_ms + dx*ag_ms
      cl_ac = cl_ac + dx*ag_ac
!
      cpg1 = cpg2
      cpg1_ms = cpg2_ms
      cpg1_ac = cpg2_ac
    END DO
!
!---- initialize under-relaxation factor
    rlx = 1.0
!
    IF (lalfa) THEN
!===== alpha is prescribed: AC is CL
!
!----- set change in Re to account for CL changing, since Re = Re(CL)
      dac = (clnew-cl)/(1.0-cl_ac-cl_ms*2.0*minf*minf_cl)
!
!----- set under-relaxation factor if Re change is too large
      IF (rlx*dac .GT. dclmax) rlx = dclmax/dac
      IF (rlx*dac .LT. dclmin) rlx = dclmin/dac
    ELSE
!
!===== CL is prescribed: AC is alpha
!
!----- set change in alpha to drive CL to prescribed value
      dac = (clnew-clspec)/(0.0-cl_ac-cl_a)
!
!----- set under-relaxation factor if alpha change is too large
      IF (rlx*dac .GT. dalmax) rlx = dalmax/dac
      IF (rlx*dac .LT. dalmin) rlx = dalmin/dac
    END IF
!
!
    rmsbl = 0.
    rmxbl = 0.
!
    dhi = 1.5
    dlo = -.5
!
!---- calculate changes in BL variables and under-relaxation if needed
    DO is=1,2
      DO ibl=2,nbl(is)
        iv = isys(ibl, is)
!
!-------- set changes without underrelaxation
        dctau = vdel(1, 1, iv) - dac*vdel(1, 2, iv)
        dthet = vdel(2, 1, iv) - dac*vdel(2, 2, iv)
        dmass = vdel(3, 1, iv) - dac*vdel(3, 2, iv)
        duedg = unew(ibl, is) + dac*u_ac(ibl, is) - uedg(ibl, is)
        ddstr = (dmass-dstr(ibl, is)*duedg)/uedg(ibl, is)
!
!-------- normalize changes
        IF (ibl .LT. itran(is)) dn1 = dctau/10.0
        IF (ibl .GE. itran(is)) dn1 = dctau/ctau(ibl, is)
        dn2 = dthet/thet(ibl, is)
        dn3 = ddstr/dstr(ibl, is)
        IF (duedg .GE. 0.) THEN
          abs0 = duedg
        ELSE
          abs0 = -duedg
        END IF
        dn4 = abs0/0.25
!
!-------- accumulate for rms change
        rmsbl = rmsbl + dn1**2 + dn2**2 + dn3**2 + dn4**2
!
!-------- see if Ctau needs underrelaxation
        rdn1 = rlx*dn1
        IF (dn1 .GE. 0.) THEN
          abs1 = dn1
        ELSE
          abs1 = -dn1
        END IF
        IF (rmxbl .GE. 0.) THEN
          abs5 = rmxbl
        ELSE
          abs5 = -rmxbl
        END IF
        IF (abs1 .GT. abs5) THEN
          rmxbl = dn1
          IF (ibl .LT. itran(is)) vmxbl = 'n'
          IF (ibl .GE. itran(is)) vmxbl = 'C'
          imxbl = ibl
          ismxbl = is
        END IF
        IF (rdn1 .GT. dhi) rlx = dhi/dn1
        IF (rdn1 .LT. dlo) rlx = dlo/dn1
!
!-------- see if Theta needs underrelaxation
        rdn2 = rlx*dn2
        IF (dn2 .GE. 0.) THEN
          abs2 = dn2
        ELSE
          abs2 = -dn2
        END IF
        IF (rmxbl .GE. 0.) THEN
          abs6 = rmxbl
        ELSE
          abs6 = -rmxbl
        END IF
        IF (abs2 .GT. abs6) THEN
          rmxbl = dn2
          vmxbl = 'T'
          imxbl = ibl
          ismxbl = is
        END IF
        IF (rdn2 .GT. dhi) rlx = dhi/dn2
        IF (rdn2 .LT. dlo) rlx = dlo/dn2
!
!-------- see if Dstar needs underrelaxation
        rdn3 = rlx*dn3
        IF (dn3 .GE. 0.) THEN
          abs3 = dn3
        ELSE
          abs3 = -dn3
        END IF
        IF (rmxbl .GE. 0.) THEN
          abs7 = rmxbl
        ELSE
          abs7 = -rmxbl
        END IF
        IF (abs3 .GT. abs7) THEN
          rmxbl = dn3
          vmxbl = 'D'
          imxbl = ibl
          ismxbl = is
        END IF
        IF (rdn3 .GT. dhi) rlx = dhi/dn3
        IF (rdn3 .LT. dlo) rlx = dlo/dn3
!
!-------- see if Ue needs underrelaxation
        rdn4 = rlx*dn4
        IF (dn4 .GE. 0.) THEN
          abs4 = dn4
        ELSE
          abs4 = -dn4
        END IF
        IF (rmxbl .GE. 0.) THEN
          abs8 = rmxbl
        ELSE
          abs8 = -rmxbl
        END IF
        IF (abs4 .GT. abs8) THEN
          rmxbl = duedg
          vmxbl = 'U'
          imxbl = ibl
          ismxbl = is
        END IF
        IF (rdn4 .GT. dhi) rlx = dhi/dn4
        IF (rdn4 .LT. dlo) rlx = dlo/dn4
      END DO
    END DO
!
!
!---- set true rms change
    rmsbl = SQRT(rmsbl/(4.0*FLOAT(nbl(1)+nbl(2))))
!
!---- XFOILAD: under-relaxation after a cycle of the transition interval
    IF (rlx .GT. xad_rlxcap) rlx = xad_rlxcap
!
!
    IF (lalfa) THEN
!----- set underrelaxed change in Reynolds number from change in lift
      cl = cl + rlx*dac
    ELSE
!----- set underrelaxed change in alpha
      alfa = alfa + rlx*dac
      adeg = alfa/dtor
    END IF
!
!---- update BL variables with underrelaxed changes
    DO is=1,2
      DO ibl=2,nbl(is)
        iv = isys(ibl, is)
!
        dctau = vdel(1, 1, iv) - dac*vdel(1, 2, iv)
        dthet = vdel(2, 1, iv) - dac*vdel(2, 2, iv)
        dmass = vdel(3, 1, iv) - dac*vdel(3, 2, iv)
        duedg = unew(ibl, is) + dac*u_ac(ibl, is) - uedg(ibl, is)
        ddstr = (dmass-dstr(ibl, is)*duedg)/uedg(ibl, is)
!
        ctau(ibl, is) = ctau(ibl, is) + rlx*dctau
        thet(ibl, is) = thet(ibl, is) + rlx*dthet
        dstr(ibl, is) = dstr(ibl, is) + rlx*ddstr
        uedg(ibl, is) = uedg(ibl, is) + rlx*duedg
!
        IF (ibl .GT. iblte(is)) THEN
          iw = ibl - iblte(is)
          dswaki = wgap(iw)
        ELSE
          dswaki = 0.
        END IF
!
!-------- eliminate absurd transients
        IF (ibl .GE. itran(is)) THEN
          IF (ctau(ibl, is) .GT. 0.25) THEN
            ctau(ibl, is) = 0.25
          ELSE
            ctau(ibl, is) = ctau(ibl, is)
          END IF
        END IF
!
        IF (ibl .LE. iblte(is)) THEN
          hklim = 1.02
        ELSE
          hklim = 1.00005
        END IF
        msq = uedg(ibl, is)**2*hstinv/(gamm1*(1.0-0.5*uedg(ibl, is)**2*&
&         hstinv))
        dsw = dstr(ibl, is) - dswaki
        CALL DSLIM(dsw, thet(ibl, is), uedg(ibl, is), msq, hklim)
        dstr(ibl, is) = dsw + dswaki
!
!-------- set new mass defect (nonlinear update)
        mass(ibl, is) = dstr(ibl, is)*uedg(ibl, is)
      END DO
!
!
!------ make sure there are no "islands" of negative Ue
      DO ibl=3,iblte(is)
        IF (uedg(ibl-1, is) .GT. 0.0 .AND. uedg(ibl, is) .LE. 0.0) THEN
          uedg(ibl, is) = uedg(ibl-1, is)
          mass(ibl, is) = dstr(ibl, is)*uedg(ibl, is)
        END IF
      END DO
    END DO
!
!
!---- equate upper wake arrays to lower wake arrays
    DO kbl=1,nbl(2)-iblte(2)
      ctau(iblte(1)+kbl, 1) = ctau(iblte(2)+kbl, 2)
      thet(iblte(1)+kbl, 1) = thet(iblte(2)+kbl, 2)
      dstr(iblte(1)+kbl, 1) = dstr(iblte(2)+kbl, 2)
      uedg(iblte(1)+kbl, 1) = uedg(iblte(2)+kbl, 2)
      tau(iblte(1)+kbl, 1) = tau(iblte(2)+kbl, 2)
      dis(iblte(1)+kbl, 1) = dis(iblte(2)+kbl, 2)
      ctq(iblte(1)+kbl, 1) = ctq(iblte(2)+kbl, 2)
      delt(iblte(1)+kbl, 1) = delt(iblte(2)+kbl, 2)
      tstr(iblte(1)+kbl, 1) = tstr(iblte(2)+kbl, 2)
    END DO
  END SUBROUTINE UPDATE

